local config = {
  ui_story_5040_50400101_1_dialog_content = "（唉……難得的假期……）",
  ui_story_5040_50400101_2_dialog_content = "（不行，必須打起精神來！）",
  ui_story_5040_50400101_3_dialog_content = "「滴滴，距離<color=#FFB400>冠月節</color>還有3天。」",
  ui_story_5040_50400101_4_dialog_content = "「冠月節是艾斯特拉傳統節日，是情侶表達愛意的日子，也適合舉辦婚禮。」",
  ui_story_5040_50400101_5_dialog_content = "知道啦，知道啦！要不是因為去年太忙錯過了冠月節，現在也不會……",
  ui_story_5040_50400101_6_dialog_content = "總之一定要把薇絲和卡蓮看中的浮雕唱片機買回來，過節時給她們一個驚喜！",
  ui_story_5040_50400101_7_dialog_content = "（她們兩個最近說要休假，不知道跑哪裡去了。算了，我就獨自努力吧！）",
  ui_story_5040_50400101_8_dialog_content = "PlayerName，真是少見，找我有什麼事嗎？",
  ui_story_5040_50400101_9_dialog_content = "抱歉，信使公會節日前忙得一塌糊塗，閒聊的時間可能不多。",
  ui_story_5040_50400101_10_dialog_content = "有位信使公會紅油扳手分部的同事弄亂了大量送到白夜的信件……",
  ui_story_5040_50400101_11_dialog_content = "啊，有什麼我能幫忙的嗎？",
  ui_story_5040_50400101_12_dialog_content = "最近過節，我有想買的東西，為了賺錢所以在接委託。",
  ui_story_5040_50400101_13_dialog_content = "之前塔塔也受你關照了，本來不想再麻煩你。",
  ui_story_5040_50400101_14_dialog_content = "既然你都這麼說了，確實有件事可以麻煩你跑一趟紅油扳手分部。",
  ui_story_5040_50400101_15_dialog_content = "我有一位北境的老朋友要舉辦婚禮，婚期和很多人一樣訂在冠月節。",
  ui_story_5040_50400101_16_dialog_content = "只是他的未婚妻前一陣子在紅油沙漠受了點小傷，等休養好再去北境怕是來不及了。",
  ui_story_5040_50400101_17_dialog_content = "要借用巨像送她過去嗎？沒問題，這個簡單。",
  ui_story_5040_50400101_18_dialog_content = "（話說納努塞爾朋友的婚禮，她自己不去嗎？）",
  ui_story_5040_50400101_19_dialog_content = "（詳細情況索性找當事人問一回。這裡應該就是紅油扳手分部了吧？）",
  ui_story_5040_50400101_20_dialog_content = "<color=#e8d9bb>咚咚——</color>",
  ui_story_5040_50400101_21_dialog_content = "請問……",
  ui_story_5040_50400101_22_dialog_content = "是專程來幫忙的空裔小哥嗎，等候多時了～",
  ui_story_5040_50400101_23_dialog_content = "納努塞爾總說空裔的巨像很快，我還以為會更早到呢。",
  ui_story_5040_50400101_X23_dialog_content = "（好、好大的蛇！這也是信使的言靈嗎？！太厲害了。）",
  ui_story_5040_50400101_X24_dialog_content = "（還有這間辦公室……怎麼說呢，精緻得完全不像紅油扳手的風格啊。）",
  ui_story_5040_50400101_24_dialog_content = "（這間辦公室……怎麼說呢，精緻得完全不像紅油扳手的風格啊。）",
  ui_story_5040_50400101_25_dialog_content = "初次見面，我是受納努塞爾委託來這裡幫忙的PlayerName。",
  ui_story_5040_50400101_26_dialog_content = "兩位是？",
  ui_story_5040_50400101_27_dialog_content = "比我想像中的還要年輕。自我介紹一下——",
  ui_story_5040_50400101_28_dialog_content = "我是紅油扳手分部的長老<color=#FFB400>耶利亞</color>，這是<color=#FFB400>塔拉</color>，我們本次任務的目標。",
  ui_story_5040_50400101_29_dialog_content = "你好，我是塔拉，想不到能見到傳說中的空裔！真是太幸運了！",
  ui_story_5040_50400101_30_dialog_content = "不敢當，不過耶利亞長老也要一起去北境嗎？",
  ui_story_5040_50400101_31_dialog_content = "喊我耶利亞就好。呵呵，信件方面出了點紕漏，不得不請納努塞爾幫忙。",
  ui_story_5040_50400101_32_dialog_content = "所以參加婚禮和證婚的事情，就由我代她出面了。",
  ui_story_5040_50400101_33_dialog_content = "（納努塞爾之前說弄亂了大量信件的紅油同事，難道就是她？）",
  ui_story_5040_50400101_34_dialog_content = "證婚？之前聽說過，新人婚禮上能讓信使公會的人出面，是相當幸運的兆頭。",
  ui_story_5040_50400101_35_dialog_content = "是的！冠月節那天想讓信使參加婚禮可不容易，這次說什麼也要借納努塞爾的人情了！",
  ui_story_5040_50400101_36_dialog_content = "納努塞爾已經忙到一天都抽不出來了嗎？",
  ui_story_5040_50400101_37_dialog_content = "冠月節前後本來就是信使公會最忙的時候，各種請柬、信件滿天飛。",
  ui_story_5040_50400101_38_dialog_content = "然後這位美麗的耶利亞女士又「不慎」弄錯了大量到北境的包裹。",
  ui_story_5040_50400101_39_dialog_content = "我猜妳委託空裔小哥過來，應該有比挖苦我更重要的事。先出發吧，難道妳不想見到未婚夫了？",
  ui_story_5040_50400101_40_dialog_content = "說的也是，即使巨像很快，也還是早點出發的好。",
  ui_story_5040_50400101_41_dialog_content = "哇，PlayerName的巨像和大蜥蜴的感覺完全不同！",
  ui_story_5040_50400101_42_dialog_content = "啊哈哈，感覺妳一上來就很興奮。",
  ui_story_5040_50400101_43_dialog_content = "不過沙漠出身的新娘和北境出身的新郎，這樣的組合很奇妙呢，這種通婚不算普遍吧？",
  ui_story_5040_50400101_44_dialog_content = "這個嘛，怎麼說呢～算罕見吧！",
  ui_story_5040_50400101_45_dialog_content = "世界很大，無奇不有。但以光靈的觀點來說，算是有點稀奇吧。",
  ui_story_5040_50400101_46_dialog_content = "欸！這樣嗎？",
  ui_story_5040_50400101_47_dialog_content = "耶利亞長……耶利亞也是紅油沙漠出身？",
  ui_story_5040_50400101_48_dialog_content = "雖然不想承認，但確實如此。",
  ui_story_5040_50400101_49_dialog_content = "耶利亞也很奇怪啊，明明是土生土長的沙漠人，在紅油扳手怎麼連幾個熟人都沒有？",
  ui_story_5040_50400101_50_dialog_content = "我打聽了一大圈才找到妳的辦公室。",
  ui_story_5040_50400101_51_dialog_content = "呵呵，每個人都有自己的生存之道而已。",
  ui_story_5040_50400101_52_dialog_content = "我的事情並不重要，這次妳才是主角。",
  ui_story_5040_50400101_53_dialog_content = "是啊！我還是第一次見到準新娘呢！",
  ui_story_5040_50400101_54_dialog_content = "也沒什麼大不了的，沙漠人的愛情觀都很開放。",
  ui_story_5040_50400101_55_dialog_content = "總之時間有限，我想先參觀一下巨像。",
  ui_story_5040_50400101_56_dialog_content = "PlayerName，麻煩你幫我帶路啦！",
  ui_story_5040_50400101_57_dialog_content = "啊，好的，等等我。",
  ui_story_5040_50400101_58_dialog_content = "這樣說可能不太好，但感覺塔拉不太像個新娘呢。",
  ui_story_5040_50400101_59_dialog_content = "大家的行事風格各異。空裔小哥，背地裡說閒話可不恰當哦。",
  ui_story_5040_50400101_60_dialog_content = "嗯，是。",
  ui_story_5040_50400101_61_dialog_content = "（耶利亞這人真是……明明是去參加人家的婚禮。）",
  ui_story_5040_50400101_62_dialog_content = "呼，終於到了。",
  ui_story_5040_50400101_63_dialog_content = "塔拉是去找人了嗎？我記得附近好像有個村子？",
  ui_story_5040_50400101_64_dialog_content = "降臨鎮，這裡地處北境邊緣。大部分人很傳統，習慣在村內的殿堂裡舉行結婚儀式。",
  ui_story_5040_50400101_65_dialog_content = "那我們是要去殿堂嗎？",
  ui_story_5040_50400101_66_dialog_content = "我猜他們兩個應該是在別的地方吧。",
  ui_story_5040_50400101_67_dialog_content = "（話說人已經送到了，我還要留在這參加婚禮嗎？）",
  ui_story_5040_50400101_68_dialog_content = "你是不是在想，自己可以回去了？",
  ui_story_5040_50400101_69_dialog_content = "（啊，被看穿了。）",
  ui_story_5040_50400101_70_dialog_content = "你也是納努塞爾的熟人，他們一定會邀請你參加婚禮的。",
  ui_story_5040_50400101_71_dialog_content = "來都來了，北境人結婚雖然不像白夜城的婚禮那麼熱鬧，但也別有風情喔。",
  ui_story_5040_50400101_72_dialog_content = "說得也是。不過耶利亞雖然是紅油扳手分部的長老，好像也很熟悉北境呢。",
  ui_story_5040_50400101_73_dialog_content = "何止北境，除了工作以外，她可是天上地下無所不曉。",
  ui_story_5040_50400101_74_dialog_content = "啊哈哈，妳回來了，新郎來了嗎？",
  ui_story_5040_50400101_75_dialog_content = "塔拉！",
  ui_story_5040_50400101_76_dialog_content = "久、久等了……！",
  ui_story_5040_50400101_77_dialog_content = "你可真慢——",
  ui_story_5040_50400101_78_dialog_content = "這位是耶利亞，就是我之前提到的那位紅油沙漠信使公會的長老。",
  ui_story_5040_50400101_79_dialog_content = "這位是送我們來這裡的PlayerName，是空裔！他的巨像真的好厲害。",
  ui_story_5040_50400101_80_dialog_content = "他是<color=#FFB400>亞度尼斯</color>，我的未婚夫……啊，說出這個詞果然好彆扭，平時都是直接說名字的。",
  ui_story_5040_50400101_81_dialog_content = "耶利亞長老，PlayerName，你們好。",
  ui_story_5040_50400101_82_dialog_content = "抱歉，今天慌慌張張的。我和納努塞爾是老同學了，這次也是受了她的幫助。",
  ui_story_5040_50400101_83_dialog_content = "我們的婚禮，PlayerName也請一定要賞臉參加。",
  ui_story_5040_50400101_84_dialog_content = "對了，你回過家了嗎？",
  ui_story_5040_50400101_85_dialog_content = "還……還沒。",
  ui_story_5040_50400101_86_dialog_content = "還沒說？",
  ui_story_5040_50400101_87_dialog_content = "你要拖到什麼時候？",
  ui_story_5040_50400101_88_dialog_content = "就這一兩天，明天……明天就回去。",
  ui_story_5040_50400101_89_dialog_content = "這點事今天拖明天，明天拖後天！你到底要不要跟你父母說了？！",
  ui_story_5040_50400101_90_dialog_content = "……",
  ui_story_5040_50400101_91_dialog_content = "（這是什麼情況？）",
  ui_story_5040_50400101_92_dialog_content = "看來有些內情。",
  ui_story_5040_50400101_93_dialog_content = "我和空裔小哥既已受託來此，不如也讓我們知道狀況吧？",
  ui_story_5040_50400101_94_dialog_content = "哼，你自己說！",
  ui_story_5040_50400101_95_dialog_content = "……說出來不怕兩位笑話，其實我們這次是私下舉辦婚禮。",
  ui_story_5040_50400101_96_dialog_content = "我的父母從一開始就不同意我和塔拉的婚事。",
  ui_story_5040_50400101_97_dialog_content = "怪不得。",
  ui_story_5040_50400101_98_dialog_content = "北境人和沙漠出身的人通婚的情況確實不常聽到。",
  ui_story_5040_50400101_99_dialog_content = "但我是認真的，我這次一定要和父母坦白！",
  ui_story_5040_50400101_100_dialog_content = "然後我們兩個就一起遠走高飛！去紅油沙漠，或者其他哪裡都好。",
  ui_story_5040_50400101_101_dialog_content = "這是要私奔的意思嗎？",
  ui_story_5040_50400101_102_dialog_content = "我當然是希望說服我父母，但是……",
  ui_story_5040_50400101_103_dialog_content = "但是什麼？你不是到現在也還沒開口嗎？",
  ui_story_5040_50400101_104_dialog_content = "對你來說，把自己的想法說出來就這麼難？！",
  ui_story_5040_50400101_105_dialog_content = "我……",
  ui_story_5040_50400101_106_dialog_content = "我有些好奇，亞度尼斯小哥，你不會從來沒離開過北境吧？",
  ui_story_5040_50400101_107_dialog_content = "沒……沒有。我和塔拉是在北境認識的。",
  ui_story_5040_50400101_108_dialog_content = "啊哈，溫室的花朵突然要過遊匪的生活，還真是勇氣可嘉呢。",
  ui_story_5040_50400101_109_dialog_content = "我已經準備好了！只要兩個人在一起，什麼困難都能解決！",
  ui_story_5040_50400101_110_dialog_content = "是嗎！那你怎麼連跟你父母坦白這點小事都還沒解決？",
  ui_story_5040_50400101_111_dialog_content = "那個，打擾一下！",
  ui_story_5040_50400101_112_dialog_content = "亞度尼斯，有你的包裹。因為你之前說很急，我先給你送來了。",
  ui_story_5040_50400101_113_dialog_content = "唷，這不是北境的小鳥兒嗎？",
  ui_story_5040_50400101_114_dialog_content = "耶、耶利亞長老？",
  ui_story_5040_50400101_115_dialog_content = "上次錯寄到北境的那幾封信也是麻煩妳幫忙了，我很感激喔。",
  ui_story_5040_50400101_116_dialog_content = "那應該不是「幾封」吧，請您下次小心一點啊。",
  ui_story_5040_50400101_117_dialog_content = "<size=33>那個工作量我不想回憶起第二次……</size>",
  ui_story_5040_50400101_118_dialog_content = "<color=#FFB400>凱雅</color>，謝謝妳了。",
  ui_story_5040_50400101_119_dialog_content = "這是什麼？",
  ui_story_5040_50400101_120_dialog_content = "對了，那個寄東西的靈媒說，這個藥水要小心一點用，好像效果很厲害。",
  ui_story_5040_50400101_121_dialog_content = "藥水？什麼藥水？",
  ui_story_5040_50400101_122_dialog_content = "這、這個嘛……我回去再跟妳說。",
  ui_story_5040_50400101_123_dialog_content = "到底什麼東西，這麼支支吾吾的？！",
  ui_story_5040_50400101_124_dialog_content = "唉。",
  ui_story_5040_50400101_125_dialog_content = "這是一位很高明的靈媒製作的<color=#FFB400>萬能魔藥</color>，喝了可以改變自己的精神意志，比如勇氣。",
  ui_story_5040_50400101_126_dialog_content = "我想有了這個，和我父母理論的時候應該就能更有底氣些了……",
  ui_story_5040_50400101_127_dialog_content = "（魔藥？這種東西是真實存在的嗎？）",
  ui_story_5040_50400101_128_dialog_content = "哈？你腦子壞了嗎！這種東西你也信？！讓我看看！",
  ui_story_5040_50400101_129_dialog_content = "真不敢相信，現在還有人會被靈媒之類的人唬弄！",
  ui_story_5040_50400101_130_dialog_content = "而且我們在一起三年了！到現在你還需要靠什麼魔藥，才敢跟父母坦白嗎？！",
  ui_story_5040_50400101_131_dialog_content = "這……這也是為了我們倆好啊！",
  ui_story_5040_50400101_132_dialog_content = "你就這麼膽小？對我們的未來這麼沒信心？！",
  ui_story_5040_50400101_133_dialog_content = "我們的感情到現在還需要借助外力才能堅持嗎，亞度尼斯！",
  ui_story_5040_50400101_134_dialog_content = "就你現在這個樣子，這婚禮還是別……",
  ui_story_5040_50400101_135_dialog_content = "<color=#e8d9bb>沙沙——</color>",
  ui_story_5040_50400101_136_dialog_content = "<size=45>嘎嗷！！</size>",
  ui_story_5040_50400101_137_dialog_content = "<size=45>嘎——嗷！！</size>",
  ui_story_5040_50400101_138_dialog_content = "暗鬼？哪來的暗鬼？",
  ui_story_5040_50400101_139_dialog_content = "這裡怎麼會有暗鬼！",
  ui_story_5040_50400101_140_dialog_content = "沒想到會碰上這種東西，還真麻煩呢。",
  ui_story_5040_50400201_1_dialog_content = "<color=#e8d9bb>——砰！</color>",
  ui_story_5040_50400201_2_dialog_content = "嘎——！",
  ui_story_5040_50400201_3_dialog_content = "嘎——嗷！",
  ui_story_5040_50400201_4_dialog_content = "怎麼會？！從哪裡冒出來這麼多暗鬼？！",
  ui_story_5040_50400201_5_dialog_content = "雖然很麻煩，總之當心一點比較好。",
  ui_story_5040_50400201_6_dialog_content = "中間那隻暗鬼看起來不太對勁呢。",
  ui_story_5040_50400201_7_dialog_content = "呼……呼……",
  ui_story_5040_50400201_8_dialog_content = "塔拉！妳後面！",
  ui_story_5040_50400201_9_dialog_content = "亞度尼斯，別過來！這裡交給我們！",
  ui_story_5040_50400201_10_dialog_content = "塔拉小姐小心！那隻奇怪的暗鬼好像一直在盯著妳！",
  ui_story_5040_50400201_11_dialog_content = "給……",
  ui_story_5040_50400201_12_dialog_content = "給……我……",
  ui_story_5040_50400201_13_dialog_content = "我要……要……",
  ui_story_5040_50400201_14_dialog_content = "你說什麼？！",
  ui_story_5040_50400201_15_dialog_content = "（牠在說通用語嗎？）",
  ui_story_5040_50400201_16_dialog_content = "塔拉，把妳手上那瓶藥水扔出去。",
  ui_story_5040_50400201_17_dialog_content = "什……",
  ui_story_5040_50400201_18_dialog_content = "<color=#e8d9bb>嗖——砰——</color>",
  ui_story_5040_50400201_19_dialog_content = "塔拉！！",
  ui_story_5040_50400201_20_dialog_content = "危險，快閃開！",
  ui_story_5040_50400201_21_dialog_content = "<color=#e8d9bb>嘶拉——</color>",
  ui_story_5040_50400201_22_dialog_content = "呃啊！！",
  ui_story_5040_50400201_23_dialog_content = "呼……！藥……",
  ui_story_5040_50400201_24_dialog_content = "嘎——",
  ui_story_5040_50400201_25_dialog_content = "嘎嘎嗷！",
  ui_story_5040_50400201_27_dialog_content = "暗鬼跑了？",
  ui_story_5040_50400201_28_dialog_content = "這幾隻小的還在。",
  ui_story_5040_50400201_29_dialog_content = "亞度尼斯，保護好你的未婚妻哦。",
  ui_story_5040_50400202_1_dialog_content = "終於解決了，大家還好嗎？",
  ui_story_5040_50400202_2_dialog_content = "塔拉！塔拉！",
  ui_story_5040_50400202_3_dialog_content = "糟糕，她好像昏過去了！",
  ui_story_5040_50400202_4_dialog_content = "你們兩個讓開，我看一下。",
  ui_story_5040_50400202_5_dialog_content = "沒有嚴重的外傷，那隻逃跑的暗鬼似乎沒給她造成什麼傷害。",
  ui_story_5040_50400202_6_dialog_content = "只是有點擦破皮而已。",
  ui_story_5040_50400202_7_dialog_content = "沒有外傷怎麼會暈倒？是不是頭被撞到了？？",
  ui_story_5040_50400202_8_dialog_content = "你先冷靜下來，我目前沒看到有什麼問題，先把她帶到安全的地方靜養吧。",
  ui_story_5040_50400202_9_dialog_content = "啊，那瓶藥水好像灑到她身上了。",
  ui_story_5040_50400202_10_dialog_content = "這藥水裡沒有什麼不好的東西吧？！",
  ui_story_5040_50400202_11_dialog_content = "我……我也不知道啊，是亞度尼斯你要的，我只是負責替靈媒送來而已。",
  ui_story_5040_50400202_12_dialog_content = "你先別著急，總之還是先把她送到可以休息的地方。",
  ui_story_5040_50400202_13_dialog_content = "嗯，不好意思了，各位，麻煩先回我家吧。",
  ui_story_5040_50400202_14_dialog_content = "我也先去送信了，好好照顧塔拉小姐呀。",
  ui_story_5040_50400202_15_dialog_content = "<color=#e8d9bb>咚咚咚——</color>",
  ui_story_5040_50400202_16_dialog_content = "亞度尼斯？怎麼這個時……",
  ui_story_5040_50400202_17_dialog_content = "這是怎麼回事？！",
  ui_story_5040_50400202_18_dialog_content = "父親，說來話長，先讓我們進去。",
  ui_story_5040_50400202_19_dialog_content = "亞度尼斯，這些是你的朋友？這個女孩是……塔拉？",
  ui_story_5040_50400202_20_dialog_content = "打擾了。",
  ui_story_5040_50400202_21_dialog_content = "母親，她受傷了，剛才遇到暗鬼……總之先把她安頓一下，我再和你們解釋。",
  ui_story_5040_50400202_22_dialog_content = "暗鬼？！家裡有應急的藥草，需要處理傷口嗎？你沒受傷吧！",
  ui_story_5040_50400202_23_dialog_content = "您不必緊張，她只是有點擦傷和受驚，其他人都沒事。",
  ui_story_5040_50400202_24_dialog_content = "我去協助她安頓，你們先聊。",
  ui_story_5040_50400202_25_dialog_content = "呼，其實事情是這樣的……",
  ui_story_5040_50400202_26_dialog_content = "真是胡鬧！！",
  ui_story_5040_50400202_27_dialog_content = "這麼大的事情，你怎麼能不和我們說呢？",
  ui_story_5040_50400202_28_dialog_content = "如果這孩子沒受傷，你們是準備偷偷舉辦完婚禮後離開北境嗎？",
  ui_story_5040_50400202_29_dialog_content = "我……",
  ui_story_5040_50400202_30_dialog_content = "原本以為你只是頭腦簡單，沒想到傻得可憐！",
  ui_story_5040_50400202_31_dialog_content = "諾維亞老師教的東西，都讓你吃進肚子裡了嗎？！",
  ui_story_5040_50400202_32_dialog_content = "你真覺得自己離開北境能活下去，那就走吧！別回來了！",
  ui_story_5040_50400202_33_dialog_content = "我們就當沒你這個兒子！",
  ui_story_5040_50400202_34_dialog_content = "父親，母親，我……我不是這個意思！",
  ui_story_5040_50400202_35_dialog_content = "別做無謂的解釋了，我不想聽！",
  ui_story_5040_50400202_36_dialog_content = "你父親在氣頭上，說話有些重。",
  ui_story_5040_50400202_37_dialog_content = "但是亞度尼斯，你真的很讓我們痛心。",
  ui_story_5040_50400202_38_dialog_content = "……",
  ui_story_5040_50400202_39_dialog_content = "唉……",
  ui_story_5040_50400202_40_dialog_content = "（這……這種場合我還是第一次遇到。）",
  ui_story_5040_50400202_41_option_content = "安慰亞度尼斯",
  ui_story_5040_50400202_42_dialog_content = "你先別太難過，他們只是在氣頭上。",
  ui_story_5040_50400202_43_dialog_content = "畢竟遇到這種事，情緒有些激動也是必然。",
  ui_story_5040_50400202_44_dialog_content = "但他們是你的父母，之後好好溝通的話，一定能說清楚的。",
  ui_story_5040_50400202_45_dialog_content = "唉，父母不諒解我，塔拉又受了傷。",
  ui_story_5040_50400202_46_dialog_content = "我真是個失敗的人啊。",
  ui_story_5040_50400202_47_dialog_content = "（不好，他似乎陷入自我否定了的漩渦中了……）",
  ui_story_5040_50400202_48_option_content = "向耶利亞求助",
  ui_story_5040_50400202_49_dialog_content = "耶利亞，這怎麼辦？",
  ui_story_5040_50400202_50_dialog_content = "嗯？怎麼了？",
  ui_story_5040_50400202_51_dialog_content = "（她是恍神了？！在這種情況下也能恍神嗎！）",
  ui_story_5040_50400202_52_dialog_content = "這種情況，要說些什麼好？",
  ui_story_5040_50400202_53_dialog_content = "那是他自己的問題，別人說什麼也沒用。",
  ui_story_5040_50400202_54_dialog_content = "就算現在說兩句好聽的，也解決不了他的問題。",
  ui_story_5040_50400202_55_dialog_content = "（雖說道理是這樣，但也不能什麼都不說吧！）",
  ui_story_5040_50400202_56_dialog_content = "（天啊，氣氛凝結的感覺好可怕。）",
  ui_story_5040_50400202_57_dialog_content = "抱歉了兩位，讓你們看笑話了。",
  ui_story_5040_50400202_58_dialog_content = "沒有沒有，有什麼我們能幫上忙的儘管說。",
  ui_story_5040_50400202_59_dialog_content = "唉，都是我自己造成的問題。",
  ui_story_5040_50400202_60_dialog_content = "你們專程大老遠過來，也沒招待你們。",
  ui_story_5040_50400202_61_dialog_content = "呵呵，現在就別說這些了吧。",
  ui_story_5040_50400202_62_dialog_content = "PlayerName，你帶他出去走走吧，轉換心情，我也幫塔拉換洗一下。",
  ui_story_5040_50400202_63_dialog_content = "好的，那我們出去走走。",
  ui_story_5040_50400202_64_dialog_content = "嗯……",
  ui_story_5040_50400202_65_dialog_content = "……",
  ui_story_5040_50400202_66_dialog_content = "妳也差不多該起來了吧？",
  ui_story_5040_50400202_67_dialog_content = "？！",
  ui_story_5040_50400202_68_dialog_content = "妳怎麼知道我醒了？",
  ui_story_5040_50400202_69_dialog_content = "豈止是沒有外傷，那隻暗鬼根本就沒真的攻擊妳。",
  ui_story_5040_50400202_70_dialog_content = "怎麼可能昏迷這麼久？",
  ui_story_5040_50400202_71_dialog_content = "……",
  ui_story_5040_50400202_72_dialog_content = "我只不過是來幫納努塞爾辦事，其他的我不會多說。",
  ui_story_5040_50400202_73_dialog_content = "跟我也沒有關係。",
  ui_story_5040_50400202_74_dialog_content = "不過看在這份人情的面子上，我就姑且多問一句，妳準備怎麼辦？",
  ui_story_5040_50400202_75_dialog_content = "我……唉……",
  ui_story_5040_50400202_76_dialog_content = "說實話，我也不知道。在沙漠的時候根本沒這麼多煩心事，煩死了。",
  ui_story_5040_50400202_77_dialog_content = "亞度尼斯給我帶來很多快樂，我不否認，可是他這麼沒擔當，我不確定自己能不能和他結婚。",
  ui_story_5040_50400202_78_dialog_content = "人的本性不是一朝一夕就能改變的，你們相處這麼久，不會今天才發現問題吧？",
  ui_story_5040_50400202_79_dialog_content = "當然。",
  ui_story_5040_50400202_80_dialog_content = "三年前，我在北境尋找遺跡期間遭到暗鬼襲擊。雖然好運逃出生天，卻暈倒在路邊。",
  ui_story_5040_50400202_80X1_dialog_content = "當時就是他救了我，還把我帶回家。",
  ui_story_5040_50400202_81_dialog_content = "那天下著大雪，要是沒有他，可能我也凶多吉少。",
  ui_story_5040_50400202_82_dialog_content = "唉，後來我們無話不談，說的都是彼此從沒見過的事情。",
  ui_story_5040_50400202_83_dialog_content = "即使回了沙漠，我還是一直跟他保持著書信聯繫。",
  ui_story_5040_50400202_84_dialog_content = "他心思細膩又體貼。我是個沒父母的孩子，沒有人那麼細心對待過我。",
  ui_story_5040_50400202_85_dialog_content = "我真的很感動。",
  ui_story_5040_50400202_86_dialog_content = "嗯～原來如此。",
  ui_story_5040_50400202_87_dialog_content = "可是到後來，每次提到離開北境，他總是很猶豫的樣子。我覺得他有點變了。",
  ui_story_5040_50400202_88_dialog_content = "不像是以前的他了，做決定有這麼難嗎？",
  ui_story_5040_50400202_89_dialog_content = "我就沒見過這麼膽小，這麼優柔寡斷的男人！他到底是不是真的喜歡我！",
  ui_story_5040_50400202_90_dialog_content = "我為我們的婚禮籌畫了好久，還準備了一份很特別的禮物。可現在……唉。",
  ui_story_5040_50400202_91_dialog_content = "其實這話不該由我來說，但妳之前有戀愛過嗎？",
  ui_story_5040_50400202_92_dialog_content = "之前？沒有，他是我的初戀。",
  ui_story_5040_50400202_93_dialog_content = "怪不得，看來妳對他抱持太過不切實際的幻想了。",
  ui_story_5040_50400202_94_dialog_content = "愛情可能是很美好的，不過妳也要尊重本性，每個個體都是複雜的，並不是非黑即白。",
  ui_story_5040_50400202_95_dialog_content = "什、什麼意思……我聽不太懂。",
  ui_story_5040_50400202_96_dialog_content = "呵呵，或許你以後就會明白。",
  ui_story_5040_50400202_97_dialog_content = "……",
  ui_story_5040_50400202_98_dialog_content = "等等！我有了！我有主意了！",
  ui_story_5040_50400202_99_dialog_content = "？",
  ui_story_5040_50400202_102_dialog_content = "就這麼辦！",
  ui_story_5040_50400202_103_dialog_content = "我就假裝失憶吧！從零開始，看看他到底對我是什麼態度！",
  ui_story_5040_50400202_104_dialog_content = "……",
  ui_story_5040_50400202_105_dialog_content = "認真的嗎？",
  ui_story_5040_50400202_106_dialog_content = "求求妳了，幫幫我吧！",
  ui_story_5040_50400202_107_dialog_content = "你們要是不結婚，實際上我應該就可以走了。",
  ui_story_5040_50400202_108_dialog_content = "啊，不要啊！妳回去怎麼和納努塞爾交代？",
  ui_story_5040_50400202_109_dialog_content = "妳的語氣是在威脅我嗎？",
  ui_story_5040_50400202_110_dialog_content = "啊！不敢，不敢！我怎麼敢呢。我的好姐姐～十萬分的拜託！求求妳了！",
  ui_story_5040_50400202_111_dialog_content = "不只是納努塞爾，也看在我們是同鄉的份上！拜託了！",
  ui_story_5040_50400202_112_dialog_content = "還真會使喚人。",
  ui_story_5040_50400202_113_dialog_content = "真是麻煩。",
  ui_story_5040_50400202_114_dialog_content = "耶！妳最好了！",
  ui_story_5040_50400202_115_dialog_content = "你們兩個的事你們自己看著辦，我只是旁觀。",
  ui_story_5040_50400202_116_dialog_content = "妳的把戲能演到什麼地步，全看妳自己了。",
  ui_story_5040_50400202_117_dialog_content = "<color=#e8d9bb>第二天——</color>",
  ui_story_5040_50400202_118_dialog_content = "早啊，耶利亞、亞度尼斯。",
  ui_story_5040_50400202_119_dialog_content = "早安，空裔小哥。",
  ui_story_5040_50400202_120_dialog_content = "早，我去看看塔拉有沒有醒……",
  ui_story_5040_50400202_121_dialog_content = "（呵欠～）",
  ui_story_5040_50400202_122_dialog_content = "塔拉！妳醒了！妳身體沒事吧？",
  ui_story_5040_50400202_123_dialog_content = "……？",
  ui_story_5040_50400202_124_dialog_content = "妳怎麼了，怎麼這種眼神看我？",
  ui_story_5040_50400202_125_dialog_content = "你是誰？",
  ui_story_5040_50400202_126_dialog_content = "妳說什麼呢？塔拉。",
  ui_story_5040_50400202_127_dialog_content = "我不認識你，不要碰我！",
  ui_story_5040_50400202_128_dialog_content = "這是哪裡？你是誰？",
  ui_story_5040_50400202_129_dialog_content = "我記得昨天和耶利亞他們搭乘巨像來北境，奇怪，是要來幹什麼的？",
  ui_story_5040_50400202_130_dialog_content = "塔拉，這個笑話一點都……",
  ui_story_5040_50400202_131_dialog_content = "不好笑啊！",
  ui_story_5040_50400202_132_dialog_content = "亞度尼斯，你還好嗎？",
  ui_story_5040_50400202_133_dialog_content = "（奇怪，剛才感應到塔拉並沒有情緒上的大起大落，難道她是故意這麼說的？）",
  ui_story_5040_50400202_134_dialog_content = "（感情上的事情我也不太懂，戳破可能更糟，還是先不要多管閒事吧。）",
  ui_story_5040_50400202_135_dialog_content = "都是我的錯，都是我的錯。",
  ui_story_5040_50400202_136_dialog_content = "那什麼破藥水，我一開始就不該打這種念頭！",
  ui_story_5040_50400202_137_dialog_content = "你認為是藥水讓她失憶的嗎？",
  ui_story_5040_50400202_138_dialog_content = "靈媒說那瓶藥水是萬能的，什麼作用都可能有！除此之外沒有別的原因了！",
  ui_story_5040_50400202_139_dialog_content = "肯定是因為藥水潑了她一身，她又已經討厭我了，想忘了我！所以藥水起了作用！",
  ui_story_5040_50400202_140_dialog_content = "都怪我！",
  ui_story_5040_50400202_141_dialog_content = "如果是這樣的話，要不要去問問那個靈媒呢？",
  ui_story_5040_50400202_142_dialog_content = "你在這哭天喊地也沒有用啊。",
  ui_story_5040_50400202_143_dialog_content = "靈媒？",
  ui_story_5040_50400202_144_dialog_content = "對，你說得對！我想起來了，那個靈媒偶爾會在市集擺攤。",
  ui_story_5040_50400202_145_dialog_content = "去，現在就去！",
  ui_story_5040_50400202_146_dialog_content = "呼、呼……是、是這個人！",
  ui_story_5040_50400202_147_dialog_content = "（跑……跑得真快。）",
  ui_story_5040_50400202_148_dialog_content = "嗯？你是？",
  ui_story_5040_50400202_149_dialog_content = "我是前一陣子找你買過萬能魔藥的人，我有急事問你！",
  ui_story_5040_50400202_150_dialog_content = "啊……喔！那個啊！",
  ui_story_5040_50400202_151_dialog_content = "怎麼樣，那可是我的精心之作，好不好用啊？",
  ui_story_5040_50400202_152_dialog_content = "長話短說，我未婚妻不小心用了藥水，現在失憶了，你馬上給我解藥！",
  ui_story_5040_50400202_153_dialog_content = "哈？？這不可能啊……",
  ui_story_5040_50400202_154_dialog_content = "你不是說那瓶藥水是萬能的，能讓人心想事成嗎？！",
  ui_story_5040_50400202_155_dialog_content = "這……這我倒是確實說過。",
  ui_story_5040_50400202_156_dialog_content = "但是想要解藥嘛，估計要費點勁了。",
  ui_story_5040_50400202_157_dialog_content = "啊？為什麼！",
  ui_story_5040_50400202_158_dialog_content = "因為它是用傳說中根本沒人目睹過的，紅油沙漠最珍貴稀有的粉色大沙蟲的閃亮鱗片製成的啊！",
  ui_story_5040_50400202_159_dialog_content = "我就是沙漠來的，我怎麼從沒聽說過？",
  ui_story_5040_50400202_160_dialog_content = "！",
  ui_story_5040_50400202_161_dialog_content = "咳，你們普通人要是知道，那還叫最珍貴稀有嗎？！",
  ui_story_5040_50400202_162_dialog_content = "這種神祕的粉色沙蟲，一般人根本一輩子都見不到一次！",
  ui_story_5040_50400202_163_dialog_content = "（感覺這個靈媒在說謊。況且誰會想見那種東西啊！）",
  ui_story_5040_50400202_164_dialog_content = "牠的鱗片閃著七彩的光芒，通體粉色，像貝殼一樣絢麗奪目！",
  ui_story_5040_50400202_165_dialog_content = "總之想要解藥，就需要牠身上的鱗片才行，你們自己想辦法吧！",
  ui_story_5040_50400202_166_dialog_content = "這！你這不是強人所難嗎！",
  ui_story_5040_50400202_167_dialog_content = "又不是我要，不是你想要嗎？我已經好心告訴你了。快走，別影響我做生意。",
  ui_story_5040_50400202_168_dialog_content = "……",
  ui_story_5040_50400202_169_dialog_content = "完了，全完了。",
  ui_story_5040_50400202_170_dialog_content = "要我跑腿受累什麼我都可以做，但是和沙蟲戰鬥……不可能啊。",
  ui_story_5040_50400202_171_dialog_content = "我連家裡的蟲子都害怕，怎麼可能去沙漠找沙蟲？！",
  ui_story_5040_50400202_172_dialog_content = "嗯，像你這種膽小的男人確實不多見。",
  ui_story_5040_50400202_173_dialog_content = "（請不要火上澆油好嗎！）",
  ui_story_5040_50400202_174_dialog_content = "先往好處想，至少人沒事。而且據我瞭解，她僅僅是把和你相關的事情忘了。",
  ui_story_5040_50400202_175_dialog_content = "與其去找什麼不切實際的沙蟲，不如想想如何讓感情恢復如初吧。",
  ui_story_5040_50400202_176_dialog_content = "確實，她也不是徹徹底底的失憶。只要人沒事，就還有可能性。",
  ui_story_5040_50400202_177_dialog_content = "你們能做這麼久的戀人，肯定也是有原因的，想要重新建立關係應該不是難事吧？",
  ui_story_5040_50400202_178_dialog_content = "是，你們說得對。",
  ui_story_5040_50400202_179_dialog_content = "可是，我現在完全不知道如何下手，在她眼裡我已經是陌生人了。",
  ui_story_5040_50400202_180_dialog_content = "說到這個，我原本是替納努塞爾來這裡參加婚禮的，你們應該沒忘吧。",
  ui_story_5040_50400202_181_dialog_content = "其實冠月節本來就有很多人舉辦婚禮，也有很多人希望能有信使參加自己的婚禮儀式。",
  ui_story_5040_50400202_182_dialog_content = "這個我聽說過，好像有信使參加新人婚禮，是幸福和希望的象徵。",
  ui_story_5040_50400202_183_dialog_content = "正是，所以公會近幾年索性推出了一些冠月節的活動，專為新婚人士和情侶設計。",
  ui_story_5040_50400202_184_dialog_content = "這樣也能緩解一些信使的壓力，畢竟這個時期本來就很忙。",
  ui_story_5040_50400202_185_dialog_content = "欸？這我還是第一次聽說。",
  ui_story_5040_50400202_186_dialog_content = "嗯，很正常，畢竟是「情侶向」，不會通知長期單身的人士。",
  ui_story_5040_50400202_187_dialog_content = "唔！",
  ui_story_5040_50400202_188_dialog_content = "什麼意思？",
  ui_story_5040_50400202_189_dialog_content = "這個活動在一些地方取代了信使出席婚禮這項風俗，一樣能給新人帶來好運。",
  ui_story_5040_50400202_190_dialog_content = "每個分部的活動都不一樣，通過了就會蓋上信使公會的羽毛章。",
  ui_story_5040_50400202_191_dialog_content = "你要不要考慮和塔拉一起參加信使公會的活動，順便去外面看看呢？",
  ui_story_5040_50400202_192_dialog_content = "離開北境……嗎？",
  ui_story_5040_50400202_193_dialog_content = "失憶可以透過一些外界刺激來喚醒過去的記憶，這也是民間的一種治療方法。",
  ui_story_5040_50400202_194_dialog_content = "我只是隨口說說，信使公會的活動可以成為契機，是否願意把握就看你自己了。",
  ui_story_5040_50400202_195_dialog_content = "繭居的人只能獨自懊惱，不走出去看看世界，如何知道是否有解決辦法？",
  ui_story_5040_50400202_196_dialog_content = "雖然和我無關，但出去四處走走，說不定也能發現什麼恢復記憶的方法喔。",
  ui_story_5040_50400202_197_dialog_content = "我也同意耶利亞說的！",
  ui_story_5040_50400202_198_dialog_content = "我也曾經一個人度過了很長時間，所有知識都是聽來的。",
  ui_story_5040_50400202_199_dialog_content = "後來走出那個地方，才發現大陸上有那麼多我不知道的事情。",
  ui_story_5040_50400202_200_dialog_content = "要是能到處走走，不只可能喚醒記憶，說不定也能打聽到相關疾病的情報！",
  ui_story_5040_50400202_201_dialog_content = "二位……！",
  ui_story_5040_50400202_202_dialog_content = "我實在是，唉，不知道該說什麼好。",
  ui_story_5040_50400202_203_dialog_content = "真的很感謝你們幫我想辦法。現在塔拉的病是迫在眉睫的問題。",
  ui_story_5040_50400202_204_dialog_content = "嗯！我覺得我們之間的感情沒有那麼脆弱，失去的一定還能重新找回來！",
  ui_story_5040_50400202_205_dialog_content = "……",
  ui_story_5040_50400202_206_dialog_content = "……",
  ui_story_5040_50400202_207_dialog_content = "這就是我的想法！",
  ui_story_5040_50400202_208_dialog_content = "我知道你們可能不會同意，但我……",
  ui_story_5040_50400202_209_dialog_content = "嗯，去吧。",
  ui_story_5040_50400202_210_dialog_content = "欸？",
  ui_story_5040_50400202_211_dialog_content = "如果你們兩人四處遊歷過後，還想在一起生活的話，我們就認真考慮這件事。",
  ui_story_5040_50400202_212_dialog_content = "真、真的嗎！",
  ui_story_5040_50400202_213_dialog_content = "太好了！謝謝你們！父親！母親！",
  ui_story_5040_50400202_214_dialog_content = "只是你從未離開過北境，外面的世界危險重重，在外面一定要多加小心啊。",
  ui_story_5040_50400202_215_dialog_content = "<size=33>耶利亞，他們為什麼突然轉變心態了？</size>",
  ui_story_5040_50400202_216_dialog_content = "嗯，為什麼呢？",
  ui_story_5040_50400202_217_dialog_content = "先生，可以借一步說話嗎？",
  ui_story_5040_50400202_218_dialog_content = "嗯？你是？",
  ui_story_5040_50400202_219_dialog_content = "我是信使公會的長老，耶利亞。",
  ui_story_5040_50400202_220_dialog_content = "哦，您找我有什麼事嗎？如果是關於那個不孝子的……",
  ui_story_5040_50400202_221_dialog_content = "我懂您的心情。",
  ui_story_5040_50400202_222_dialog_content = "父母沒有不希望子女幸福的，您的擔心，恐怕也是出於他的單純和幼稚吧。",
  ui_story_5040_50400202_223_dialog_content = "一個從未出過家門的人，突然要去過遊匪的生活。",
  ui_story_5040_50400202_224_dialog_content = "換做是我也接受不了呢。",
  ui_story_5040_50400202_225_dialog_content = "唉，正如您所說。生活哪是那麼容易的事啊！",
  ui_story_5040_50400202_226_dialog_content = "亞度尼斯自小受諾維亞老師的指導，細心而又聰明，只是太過單純。",
  ui_story_5040_50400202_227_dialog_content = "什麼都沒經歷過，所以只會把一切都想得很美好。",
  ui_story_5040_50400202_228_dialog_content = "那，要不要借機讓他歷練一下？",
  ui_story_5040_50400202_229_dialog_content = "雛鳥越不離開父母，就越沒有生存能力。",
  ui_story_5040_50400202_230_dialog_content = "不夠強大的人是無法主動抓住幸福的，只能被動接受。",
  ui_story_5040_50400202_231_dialog_content = "比起這一點，無論去哪裡、和誰生活，都不是最重要的事。",
  ui_story_5040_50400202_232_dialog_content = "我覺得您是個明事理的父親，您怎麼看？",
  ui_story_5040_50400202_233_dialog_content = "雖然不知道耶利亞說了什麼，不過要是能順利解決也好。",
  ui_story_5040_50400301_1_dialog_content = "這是您的信件！請查收～",
  ui_story_5040_50400301_2_dialog_content = "多謝了，凱雅妹妹，這麼晚了還不休息嗎？",
  ui_story_5040_50400301_3_dialog_content = "快過節了，能多送一點也好，大家肯定也等得很著急。",
  ui_story_5040_50400301_4_dialog_content = "哎呀，新人就是努力啊，加油吧。",
  ui_story_5040_50400301_5_dialog_content = "呼～都這麼晚了。",
  ui_story_5040_50400301_6_dialog_content = "終於送完了，今天就收工吧。",
  ui_story_5040_50400301_7_dialog_content = "（中午聽亞度尼斯說塔拉小姐得了失憶症……這和昨天的暗鬼有關嗎？）",
  ui_story_5040_50400301_8_dialog_content = "（有點不放心啊，回去的時候順路去昨天那個地方看看吧。）",
  ui_story_5040_50400301_9_dialog_content = "（我記得好像是這裡。）",
  ui_story_5040_50400301_10_dialog_content = "咦？",
  ui_story_5040_50400301_11_dialog_content = "這冰霜怎麼是紫色的？是之前說的那種藥水嗎？",
  ui_story_5040_50400301_12_dialog_content = "結冰的紫色痕跡好像一直延伸到森林裡去了。",
  ui_story_5040_50400301_13_dialog_content = "啊，不管了，去看看吧！",
  ui_story_5040_50400301_14_dialog_content = "<color=#e8d9bb>嘎——嘎——</color>",
  ui_story_5040_50400301_15_dialog_content = "（好黑，要不還是回去吧，好可怕。）",
  ui_story_5040_50400301_16_dialog_content = "等等，藥水的痕跡怎麼到這裡就沒了？",
  ui_story_5040_50400301_17_dialog_content = "啊……",
  ui_story_5040_50400301_18_dialog_content = "<size=50>呀啊啊！！！</size>",
  ui_story_5040_50400301_19_dialog_content = "誰！誰在那？！",
  ui_story_5040_50400301_20_dialog_content = "幫……幫……",
  ui_story_5040_50400301_21_dialog_content = "幫……我……",
  ui_story_5040_50400301_22_dialog_content = "誰……誰在說話？！",
  ui_story_5040_50400301_23_dialog_content = "我……我！",
  ui_story_5040_50400301_24_dialog_content = "暗鬼？！",
  ui_story_5040_50400301_25_dialog_content = "不……不要……",
  ui_story_5040_50400301_26_dialog_content = "我……不會……傷害……",
  ui_story_5040_50400301_27_dialog_content = "什麼？會說通用語？妳是昨天攻擊了塔拉的暗鬼！",
  ui_story_5040_50400301_28_dialog_content = "我……不……傷害……妳……",
  ui_story_5040_50400301_29_dialog_content = "別過來！妳要幹什麼？",
  ui_story_5040_50400301_30_dialog_content = "請……妳……",
  ui_story_5040_50400301_31_dialog_content = "幫幫……我……",
  ui_story_5040_50400301_32_dialog_content = "妳說什麼？",
  ui_story_5040_50400301_33_dialog_content = "我……沒有……記憶……",
  ui_story_5040_50400301_34_dialog_content = "忘了……我……是誰……",
  ui_story_5040_50400301_35_dialog_content = "害怕……",
  ui_story_5040_50400301_36_dialog_content = "好……害怕……",
  ui_story_5040_50400301_37_dialog_content = "不知道自己是誰？那妳昨天為什麼攻擊我們？",
  ui_story_5040_50400301_38_dialog_content = "我……沒有……攻擊……",
  ui_story_5040_50400301_39_dialog_content = "想要……藥水……",
  ui_story_5040_50400301_40_dialog_content = "藥水？",
  ui_story_5040_50400301_41_dialog_content = "我……躲在……市集……",
  ui_story_5040_50400301_42_dialog_content = "聽到……藥水……萬能……",
  ui_story_5040_50400301_43_dialog_content = "想用……那個、藥水……恢復……記憶。",
  ui_story_5040_50400301_44_dialog_content = "但是……被……你們、拿走了……",
  ui_story_5040_50400301_45_dialog_content = "原來是這麼一回事。",
  ui_story_5040_50400301_46_dialog_content = "可是暗鬼怎麼會有記憶……難道妳曾經是光靈？",
  ui_story_5040_50400301_47_dialog_content = "我想……是的……但是、我、忘了。",
  ui_story_5040_50400301_48_dialog_content = "我……害怕……",
  ui_story_5040_50400301_49_dialog_content = "（大家對暗鬼避之唯恐不及，可牠看起來不像是在說謊……）",
  ui_story_5040_50400301_50_dialog_content = "（被發現幫了暗鬼的話，信使的工作也保不住了吧。可能會被抓起來也說不定。）",
  ui_story_5040_50400301_51_dialog_content = "冷……",
  ui_story_5040_50400301_52_dialog_content = "啊啊！真是的！",
  ui_story_5040_50400301_53_dialog_content = "起來，跟我走吧。",
  ui_story_5040_50400301_54_dialog_content = "謝……！",
  ui_story_5040_50400301_55_dialog_content = "我先說好，只要妳有奇怪的舉動，我會馬上讓言靈叫人來喔！",
  ui_story_5040_50400301_56_dialog_content = "嗯！",
  ui_story_5040_50400301_57_dialog_content = "……這樣……然後……",
  ui_story_5040_50400301_58_dialog_content = "這裡再遮一遮。",
  ui_story_5040_50400301_59_dialog_content = "嗯！我想這樣應該沒問題了！",
  ui_story_5040_50400301_60_dialog_content = "可以……嗎……",
  ui_story_5040_50400301_61_dialog_content = "妳確定要選這件衣服嗎？這是我以前當伴娘時穿的裙子。",
  ui_story_5040_50400301_62_dialog_content = "這麼看妳還滿像光靈的呢，雖然裙子突兀了點。",
  ui_story_5040_50400301_63_dialog_content = "謝……謝……喜歡、裙子。",
  ui_story_5040_50400301_64_dialog_content = "算了，喜歡就穿吧。我叫凱雅。在外面怎麼稱呼妳？妳記得自己的名字嗎？",
  ui_story_5040_50400301_65_dialog_content = "不……知道。",
  ui_story_5040_50400301_66_dialog_content = "那，我先叫妳小黑怎麼樣？",
  ui_story_5040_50400301_67_dialog_content = "好……好的……",
  ui_story_5040_50400301_68_dialog_content = "妳真的一點都記不起來以前的事情了嗎？",
  ui_story_5040_50400301_69_dialog_content = "是……",
  ui_story_5040_50400301_70_dialog_content = "妳一直在北境？",
  ui_story_5040_50400301_71_dialog_content = "不……我好像……從很遠的地方……來。",
  ui_story_5040_50400301_72_dialog_content = "這樣啊，那讓我想想。",
  ui_story_5040_50400301_73_dialog_content = "<color=#e8d9bb>翌日——</color>",
  ui_story_5040_50400301_74_dialog_content = "都準備好了嗎？",
  ui_story_5040_50400301_75_dialog_content = "亞度尼斯，塔拉，這次是遠行，你們想帶的可都帶好了？",
  ui_story_5040_50400301_76_dialog_content = "嗯！鯡魚罐頭、鹿肉罐頭、鯊魚肉罐頭，都帶了一個月份。",
  ui_story_5040_50400301_77_dialog_content = "乾貨海豹凍乾、白甜蝦、蛟魚皮乾，也足夠吃兩個月。",
  ui_story_5040_50400301_78_dialog_content = "另外還有應急用的攜帶式爐具、十磅錘、刀、方鏟、水壺、水鞋、防寒雨衣……",
  ui_story_5040_50400301_79_dialog_content = "我確認一下，我們是去白夜城，不是去祕境求生對吧？",
  ui_story_5040_50400301_80_dialog_content = "這也太誇張了，你到底把白夜城想像成什麼樣的地方啊？",
  ui_story_5040_50400301_81_dialog_content = "這一趟要去白夜城、迦南城和紅油沙漠，我想盡量有備無患。",
  ui_story_5040_50400301_82_dialog_content = "話是沒錯啦，但應該用不上吧，要去的每個地方都不缺食物啊。",
  ui_story_5040_50400301_83_dialog_content = "……",
  ui_story_5040_50400301_84_dialog_content = "什麼？旅行？和一個陌生人？！",
  ui_story_5040_50400301_85_dialog_content = "妳先冷靜下來，塔拉。說是旅行，其實也是想讓妳能盡快恢復記憶。",
  ui_story_5040_50400301_86_dialog_content = "妳自己難道不想記起過去的事嗎？",
  ui_story_5040_50400301_87_dialog_content = "我是想恢復記憶，但是這也太離譜了。",
  ui_story_5040_50400301_88_dialog_content = "況且只是沒有了跟你之間的記憶而已。",
  ui_story_5040_50400301_89_dialog_content = "話是這麼說，但妳我之間的回憶，無論是對我，還是對妳，都很重要啊。",
  ui_story_5040_50400301_90_dialog_content = "唔……",
  ui_story_5040_50400301_91_dialog_content = "我當然尊重妳的意見，只是我想透過遊歷來幫妳恢復記憶。",
  ui_story_5040_50400301_92_dialog_content = "妳覺得呢？如果妳不想去，我不會強迫妳的。",
  ui_story_5040_50400301_93_dialog_content = "（真是的，最後還是來了。我怎麼這麼心軟啊。）",
  ui_story_5040_50400301_94_dialog_content = "放心吧，塔拉，我會照顧好妳的！妳什麼都不用擔心！",
  ui_story_5040_50400301_95_dialog_content = "一路上妳就認真開心玩就好。",
  ui_story_5040_50400301_96_dialog_content = "我跟你又不熟，你對我好，我也不會被打動的。",
  ui_story_5040_50400301_97_dialog_content = "我要回家。",
  ui_story_5040_50400301_98_dialog_content = "會帶妳回家的，最後一站就去沙漠。",
  ui_story_5040_50400301_99_dialog_content = "前面就當是去玩，我們順便想想辦法，看能不能讓妳恢復記憶，好不好？",
  ui_story_5040_50400301_100_dialog_content = "唔，好吧。",
  ui_story_5040_50400301_101_dialog_content = "那如果萬事俱備，就準備出發吧。我順便把你們帶回白夜城，我也好去和納努塞爾匯報。",
  ui_story_5040_50400301_102_dialog_content = "PlayerName！等一下！",
  ui_story_5040_50400301_103_dialog_content = "這是？",
  ui_story_5040_50400301_104_dialog_content = "哈……哈……可算趕上了！",
  ui_story_5040_50400301_105_dialog_content = "這不是北境的小鳥嗎？喘不過氣的樣子也挺可愛的呢。",
  ui_story_5040_50400301_106_dialog_content = "耶利亞長老請不要揶揄我！咳，聽說各位要去白夜城，可以順路把我們也帶上嗎？",
  ui_story_5040_50400301_107_dialog_content = "「我們」？",
  ui_story_5040_50400301_108_dialog_content = "小鳥說的不會是這位看起來樣貌酷似暗鬼的奇怪人士吧？",
  ui_story_5040_50400301_109_dialog_content = "怎……怎麼能說人家長得像暗鬼！",
  ui_story_5040_50400301_110_dialog_content = "這是我的一個……一個遠房親戚，她叫小黑！",
  ui_story_5040_50400301_111_dialog_content = "大……大家……好。",
  ui_story_5040_50400301_112_dialog_content = "（這個小黑身上的暗能如此強烈，絕對不是我多心。）",
  ui_story_5040_50400301_113_dialog_content = "（但好像也沒什麼不對勁的，先觀察看看好了。）",
  ui_story_5040_50400301_114_dialog_content = "原來是只黑色的小鳥，這身衣服也很別緻呢。",
  ui_story_5040_50400301_115_dialog_content = "小、小黑喜歡穿禮服！好不容易出來玩，所以想打扮得體面一點。",
  ui_story_5040_50400301_116_dialog_content = "（雖然不是很懂，但她好像很喜歡這種大裙子，是有什麼執念嗎？）",
  ui_story_5040_50400301_117_dialog_content = "你們也要去白夜城嗎？",
  ui_story_5040_50400301_118_dialog_content = "我想趁著過節帶她去各個地方玩一玩，可以帶上我們嗎？正好我在白夜城也有信要送。",
  ui_story_5040_50400301_119_dialog_content = "當然沒問題，那準備好了的話，我們就出發吧。",
  ui_story_5040_50400301_120_dialog_content = "<color=#e8d9bb>臨空者號</color>",
  ui_story_5040_50400301_121_dialog_content = "話說，耶利亞不去休息一下嗎？",
  ui_story_5040_50400301_122_dialog_content = "呵呵，讀書對我來說就是休息。",
  ui_story_5040_50400301_123_dialog_content = "我並不會覺得累。",
  ui_story_5040_50400301_124_dialog_content = "空裔小哥累了的話就去睡吧。",
  ui_story_5040_50400301_125_dialog_content = "真厲害，妳讀的東西我完全看不懂。",
  ui_story_5040_50400301_126_dialog_content = "術業有專攻，我只是喜歡鑽研古籍而已。",
  ui_story_5040_50400301_127_dialog_content = "比起和光靈交往要輕鬆些。",
  ui_story_5040_50400301_128_dialog_content = "欸？",
  ui_story_5040_50400301_129_dialog_content = "話說到了白夜城，妳要回納努塞爾那邊嗎？",
  ui_story_5040_50400301_130_dialog_content = "我們都有任務要完成，回去先跟她說明情況吧。",
  ui_story_5040_50400301_131_dialog_content = "呀啊啊啊！！！",
  ui_story_5040_50400301_132_dialog_content = "？！",
  ui_story_5040_50400301_133_dialog_content = "有暗鬼！耶利亞長老、PlayerName，小心！",
  ui_story_5040_50400301_134_dialog_content = "救……救命……！",
  ui_story_5040_50400301_135_dialog_content = "巨像上哪來的暗鬼？？跟著一起上來的嗎？",
  ui_story_5040_50400301_136_dialog_content = "這些話一會再說，先清理髒東西吧。",
  ui_story_5040_50400302_1_dialog_content = "<color=#e8d9bb>解決完暗鬼後，大家各自休息整頓，也順利抵達白夜城——</color>",
  ui_story_5040_50400302_2_dialog_content = "呼，剛剛的進城檢查可真夠嚴格的，好在沒有太為難我們。",
  ui_story_5040_50400302_3_dialog_content = "（如果不是有空裔保證，小黑說不定就暴露了，還好是跟著他們一起進城。）",
  ui_story_5040_50400302_4_dialog_content = "PlayerName！耶利亞長老！我帶我家親戚去逛逛城裡順便送信！先走了！",
  ui_story_5040_50400302_5_dialog_content = "好……好快！",
  ui_story_5040_50400302_6_dialog_content = "……",
  ui_story_5040_50400302_7_dialog_content = "哇……這裡就是白夜城嗎！氛圍完全不同。",
  ui_story_5040_50400302_8_dialog_content = "塔拉，妳覺得呢？",
  ui_story_5040_50400302_9_dialog_content = "……我又不是第一次來。",
  ui_story_5040_50400302_10_dialog_content = "也……也是。",
  ui_story_5040_50400302_11_dialog_content = "事不宜遲，我們直接去找納努塞爾吧。",
  ui_story_5040_50400302_12_dialog_content = "納努塞爾！好久不見了！",
  ui_story_5040_50400302_13_dialog_content = "這是……？亞度尼斯！",
  ui_story_5040_50400302_14_dialog_content = "真的好久不見，你怎麼會來白夜城？諾維亞老師和伯父伯母都還好嗎？",
  ui_story_5040_50400302_15_dialog_content = "他們都很好，不用擔心。",
  ui_story_5040_50400302_16_dialog_content = "這位就是我在書信裡常跟妳提到的塔拉。",
  ui_story_5040_50400302_17_dialog_content = "……",
  ui_story_5040_50400302_18_dialog_content = "納努塞爾，之所以會回白夜城，其實是因為有點小狀況……",
  ui_story_5040_50400302_19_dialog_content = "<color=#e8d9bb>將情況轉告納努塞爾後——</color>",
  ui_story_5040_50400302_20_dialog_content = "怎麼會有這種事？",
  ui_story_5040_50400302_21_dialog_content = "能讓人失憶的魔藥，我還真是從未聽說過。",
  ui_story_5040_50400302_22_dialog_content = "唉，我現在也很苦惱。",
  ui_story_5040_50400302_23_dialog_content = "我能幫忙些什麼呢？我們也是老朋友了，有話直說不用客氣。",
  ui_story_5040_50400302_24_dialog_content = "其實，耶利亞提議讓我們參加各個城市的信使公會冠月節活動，集齊羽毛章。",
  ui_story_5040_50400302_25_dialog_content = "藉著這個契機，到各個地方走走看看，說不定也能發現治療塔拉失憶症的線索。",
  ui_story_5040_50400302_26_dialog_content = "羽毛章啊。",
  ui_story_5040_50400302_27_dialog_content = "信使公會在每年冠月節，確實會有專為年輕情侶設計的挑戰活動。",
  ui_story_5040_50400302_28_dialog_content = "不過……",
  ui_story_5040_50400302_29_dialog_content = "怎麼了？是有什麼難為之處嗎？",
  ui_story_5040_50400302_30_dialog_content = "我們是老朋友了，在冬宮跟隨女王學習的時候，也常常見到你和諾維亞老師的身影。",
  ui_story_5040_50400302_31_dialog_content = "正因如此，我希望你選擇和塔拉一起面對生活，是經過深思熟慮後的決定，這是最重要的。",
  ui_story_5040_50400302_32_dialog_content = "冠月節也好，信使公會的活動也好，不過都是形式而已。",
  ui_story_5040_50400302_33_dialog_content = "嗯，我明白。",
  ui_story_5040_50400302_34_dialog_content = "如果你希望以此為契機，我會支持你們的。",
  ui_story_5040_50400302_35_dialog_content = "謝謝妳！納努塞爾！",
  ui_story_5040_50400302_36_dialog_content = "冠月節活動的話……",
  ui_story_5040_50400302_37_dialog_content = "這批是今年信使公會冠月節出版的紀念郵票，全部賣出去就算通過考驗。",
  ui_story_5040_50400302_38_dialog_content = "沒問題，小意思！對吧，塔拉？",
  ui_story_5040_50400302_39_dialog_content = "啊，應該吧。",
  ui_story_5040_50400302_40_dialog_content = "不過這麼細緻的工作，我也沒做過。",
  ui_story_5040_50400302_41_dialog_content = "我們配合，一定沒問題的。來吧！現在出發。",
  ui_story_5040_50400302_42_dialog_content = "希望一切順利。",
  ui_story_5040_50400302_43_dialog_content = "辛苦了，PlayerName，還有耶利亞。",
  ui_story_5040_50400302_44_dialog_content = "但他們似乎還想去其他的信使公會，PlayerName，能麻煩你多跑幾趟嗎？",
  ui_story_5040_50400302_45_dialog_content = "沒問題，也算是成人之美了。",
  ui_story_5040_50400302_46_dialog_content = "那你就先去休息吧。",
  ui_story_5040_50400302_47_dialog_content = "之後的考驗，由我陪同他們就好。",
  ui_story_5040_50400302_48_dialog_content = "至於耶利亞，借一步說話。",
  ui_story_5040_50400302_49_dialog_content = "……",
  ui_story_5040_50400302_50_dialog_content = "妳沒有什麼要說的嗎？",
  ui_story_5040_50400302_51_dialog_content = "呵呵，是指哪件事呢？",
  ui_story_5040_50400302_52_dialog_content = "請不要再裝傻了，妳知不知道這堆紅油沙漠轉寄到白夜城的包裹，裡面都是什麼啊？",
  ui_story_5040_50400302_53_dialog_content = "嗯～是什麼呢～其實我也沒怎麼注意。",
  ui_story_5040_50400302_54_dialog_content = "妳是怎麼敢沒拆開看過就轉寄過來的……阿褐和我忙得焦頭爛額。",
  ui_story_5040_50400302_55_dialog_content = "本來過節前的包裹信件就已堆積如山，現在白夜城的信使公會都快癱瘓了。",
  ui_story_5040_50400302_56_dialog_content = "我沒有和上面說，不然妳回去一定會被他們嘮叨的。",
  ui_story_5040_50400302_57_dialog_content = "是我欠妳一個人情，這不是幫妳去北境跑腿了？",
  ui_story_5040_50400302_58_dialog_content = "唉，誰知道亞度尼斯還會碰到這種事情。",
  ui_story_5040_50400302_59_dialog_content = "妳就好人做到底，幫幫他倆吧。",
  ui_story_5040_50400302_60_dialog_content = "真是麻煩啊……我也無法理解，明明不合適，為什麼非要和對方在一起。",
  ui_story_5040_50400302_61_dialog_content = "妳自己也常常說每個個體都是複雜的，不是嗎？",
  ui_story_5040_50400302_62_dialog_content = "妳會明白的，耶利亞。我們都不可能永遠獨自生存下去。",
  ui_story_5040_50400302_63_dialog_content = "塔拉，這些是準備分裝的郵票，都在這裡了。",
  ui_story_5040_50400302_64_dialog_content = "妳往年都會寄給我冠月節的郵票，還記得嗎？我每一張都有好好珍藏起來。",
  ui_story_5040_50400302_65_dialog_content = "是嗎，我不記得了。",
  ui_story_5040_50400302_66_dialog_content = "沒關係，以後換我送給妳。今年的設計也很別緻呢。",
  ui_story_5040_50400302_67_dialog_content = "啊……！封裝袋快掉了！",
  ui_story_5040_50400302_68_dialog_content = "小心！小心！",
  ui_story_5040_50400302_69_dialog_content = "還好還好，沒掉到地上。",
  ui_story_5040_50400302_70_dialog_content = "這麼細緻的活我做不了啊，我一向不擅長這種事。找我賣火槍還差不多。",
  ui_story_5040_50400302_71_dialog_content = "啊哈哈，每個人擅長的事物不一樣，很正常，五根手指伸出來還不一樣長呢。",
  ui_story_5040_50400302_72_dialog_content = "沒事的，郵票的分封包裝我來，妳負責接待客人就好了。",
  ui_story_5040_50400302_73_dialog_content = "這個我應該沒問題。",
  ui_story_5040_50400302_74_dialog_content = "<color=#e8d9bb>一段時間後——</color>",
  ui_story_5040_50400302_75_dialog_content = "也請給我一套今年的紀念版郵票！",
  ui_story_5040_50400302_76_dialog_content = "我的怎麼還沒包好？",
  ui_story_5040_50400302_77_dialog_content = "請您先別急，冠月節郵票畢竟是紀念版，得幫您包得緊緊的，您說對吧？",
  ui_story_5040_50400302_78_dialog_content = "給您～這是您的！",
  ui_story_5040_50400302_79_dialog_content = "塔拉，忙得過來嗎？",
  ui_story_5040_50400302_80_dialog_content = "我只是動動嘴巴，你得多留意手上的郵票才對。",
  ui_story_5040_50400302_81_dialog_content = "呵呵，看來生意不錯。",
  ui_story_5040_50400302_82_dialog_content = "嗯！目前很順利。",
  ui_story_5040_50400302_83_dialog_content = "我看看……似乎剩沒多少了，可喜可賀。",
  ui_story_5040_50400302_84_dialog_content = "啊哈，最後一套，完成！",
  ui_story_5040_50400302_85_dialog_content = "呼，真不容易。",
  ui_story_5040_50400302_86_dialog_content = "恭喜兩位。",
  ui_story_5040_50400302_87_dialog_content = "喂，說恭喜的時候好歹真誠一點啊。",
  ui_story_5040_50400302_88_dialog_content = "哈欠——請問，這裡有賣信使公會的郵票嗎？",
  ui_story_5040_50400302_89_dialog_content = "是，但很不湊巧，最後一套已經賣掉了。",
  ui_story_5040_50400302_90_dialog_content = "今年的郵票雖然也很可愛，但我不是來買這一套郵票的。",
  ui_story_5040_50400302_91_dialog_content = "我想問去年的冠月節郵票是否還有存貨，如果可以的話……我願意出高價。",
  ui_story_5040_50400302_92_dialog_content = "這……",
  ui_story_5040_50400302_93_dialog_content = "我們兩個是臨時來幫忙的，耶利亞，妳知道嗎？",
  ui_story_5040_50400302_94_dialog_content = "信使公會的郵票是不重複販售的，也沒有存貨。",
  ui_story_5040_50400302_95_dialog_content = "想從官方買的話，是不可能的。",
  ui_story_5040_50400302_96_dialog_content = "這樣啊，這可怎麼辦呢……",
  ui_story_5040_50400302_97_dialog_content = "是遇到什麼困難了嗎？",
  ui_story_5040_50400302_98_dialog_content = "呼……其實，我是受朋友所托來買郵票的。",
  ui_story_5040_50400302_99_dialog_content = "他的戀人在啟光生活，而他每年都會寄送冠月節的郵票給戀人。",
  ui_story_5040_50400302_100_dialog_content = "只不過，他的家族比較保守，堅決反對兩人之間的戀情。",
  ui_story_5040_50400302_101_dialog_content = "所以他只好偷偷拜託我幫忙購買郵票和寄信了。",
  ui_story_5040_50400302_102_dialog_content = "嗯～倒是很有白夜城的特色。",
  ui_story_5040_50400302_103_dialog_content = "欸？白夜城有送郵票的風俗嗎？",
  ui_story_5040_50400302_104_dialog_content = "白夜城的情侶們會在冠月節送郵票給對方。不過貴族之間似乎有更加奢侈的做法。",
  ui_story_5040_50400302_105_dialog_content = "嗯～比起這種鋪張浪費的活動，我還是更喜歡窩在被子裡補眠呢。",
  ui_story_5040_50400302_106_dialog_content = "問題在於，他的戀人似乎不小心把去年的紀念郵票弄丟了……",
  ui_story_5040_50400302_107_dialog_content = "她很失落，也很自責。我的朋友為了讓戀人開心，這才拜託我再買一套相同的郵票。",
  ui_story_5040_50400302_108_dialog_content = "一套郵票而已，用其他東西彌補不行嗎？",
  ui_story_5040_50400302_109_dialog_content = "那怎麼能一樣，丟的是關於這件東西的回憶，什麼豪華禮物也彌補不了的。",
  ui_story_5040_50400302_110_dialog_content = "白夜城貴族和啟光女孩嗎……有趣。",
  ui_story_5040_50400302_111_dialog_content = "這段感情恐怕是有不少阻礙吧。",
  ui_story_5040_50400302_112_dialog_content = "雖然稱不上有去無回的絕路，但也算是道阻且長吧～",
  ui_story_5040_50400302_113_dialog_content = "他已經在慢慢說服自己的父母和親友，試圖讓他們認同自己的決意了。",
  ui_story_5040_50400302_114_dialog_content = "但是，可能還需要很久才行呢。",
  ui_story_5040_50400302_115_dialog_content = "看來白夜城還真的像傳聞中一樣講究門當戶對。",
  ui_story_5040_50400302_116_dialog_content = "是嗎？但我認為，就算雙方是出身相似的大貴族，也不一定會幸福呀。",
  ui_story_5040_50400302_117_dialog_content = "我工作的審判庭，每隔一段時間就會收到貴族們的離婚訴訟案件。",
  ui_story_5040_50400302_118_dialog_content = "每一樁案件都有各自的離奇曲折之處，還因為貴族之間的利益糾紛而難以釐清。",
  ui_story_5040_50400302_119_dialog_content = "是大家都不願意接手的麻煩案件呢～",
  ui_story_5040_50400302_120_dialog_content = "看來就算是貴族，也會有感情方面的煩惱啊。",
  ui_story_5040_50400302_121_dialog_content = "沒錯喔，所以我的建議是遵從自己的本心。",
  ui_story_5040_50400302_122_dialog_content = "畢竟就算委曲求全，與出身相似的人在一起，也不見得就會幸福嘛。",
  ui_story_5040_50400302_123_dialog_content = "這話從白夜城的貴族口中聽到，還真是稀奇了。",
  ui_story_5040_50400302_124_dialog_content = "只能說各人有各人的選擇，感情本來就不是能被定義的東西，喜歡就是喜歡了。",
  ui_story_5040_50400302_125_dialog_content = "喜歡一個人的感情是無法控制的，無論身處何地，出身如何。",
  ui_story_5040_50400302_126_dialog_content = "我對此可是感同身受哦。",
  ui_story_5040_50400302_127_dialog_content = "妳說得太好了！我完全同意！",
  ui_story_5040_50400302_128_dialog_content = "喔？難道這位可愛的小姑娘有心上人了？",
  ui_story_5040_50400302_129_dialog_content = "不是喔，只是在不久前，偶然遇到了一個有趣的毛茸茸小傢伙。",
  ui_story_5040_50400302_130_dialog_content = "而且那個小傢伙還會說通用語，簡直太不可思議了。",
  ui_story_5040_50400302_131_dialog_content = "昨天我還給那個小傢伙寄了一封信，也不知道什麼時候能收到回信。",
  ui_story_5040_50400302_132_dialog_content = "耶利亞，還有什麼方法能幫幫她的朋友嗎？",
  ui_story_5040_50400302_133_dialog_content = "……",
  ui_story_5040_50400302_134_dialog_content = "我也沒什麼好辦法，不過……",
  ui_story_5040_50400302_135_dialog_content = "如果妳的朋友願意付出一些代價，或許可以問問影鎮的艾爾戈絲，她的收藏可是很齊全的。",
  ui_story_5040_50400302_136_dialog_content = "這些小東西應該也不在話下吧。",
  ui_story_5040_50400302_137_dialog_content = "原來如此，幫大忙了～謝謝！",
  ui_story_5040_50400302_138_dialog_content = "那我就趁著還沒有很睏，去影鎮看看吧。",
  ui_story_5040_50400302_139_dialog_content = "真是萬事通啊，耶利亞。",
  ui_story_5040_50400302_140_dialog_content = "希望她能找到想要的東西。",
  ui_story_5040_50400302_141_dialog_content = "不過我們的任務完成了，回去蓋章吧！",
  ui_story_5040_50400302_142_dialog_content = "嗯……",
  ui_story_5040_50400302_143_dialog_content = "怎麼了，塔拉？哪裡不舒服嗎？",
  ui_story_5040_50400302_144_dialog_content = "沒有，沒事。",
  ui_story_5040_50400302_145_dialog_content = "……",
  ui_story_5040_50400302_146_dialog_content = "<color=#e8d9bb>與此同時，另一邊——</color>",
  ui_story_5040_50400302_147_dialog_content = "完全沒有收穫啊……",
  ui_story_5040_50400302_148_dialog_content = "還是什麼都沒想起來嗎？",
  ui_story_5040_50400302_149_dialog_content = "對……對……不起……",
  ui_story_5040_50400302_150_dialog_content = "不用跟我道歉，妳又沒做錯什麼。",
  ui_story_5040_50400302_151_dialog_content = "還有什麼能成為線索呢……？",
  ui_story_5040_50400302_152_dialog_content = "啊……那……那個……",
  ui_story_5040_50400302_153_dialog_content = "什麼？",
  ui_story_5040_50400302_154_dialog_content = "那……個……手裡……拿的……",
  ui_story_5040_50400302_155_dialog_content = "誰？拿什麼了？",
  ui_story_5040_50400302_156_dialog_content = "他……",
  ui_story_5040_50400302_157_dialog_content = "郵……票……",
  ui_story_5040_50400302_158_dialog_content = "郵票？那個走過去的人嗎？他拿的是冠月節的郵票沒錯。",
  ui_story_5040_50400302_159_dialog_content = "妳對這個東西有印象？",
  ui_story_5040_50400302_160_dialog_content = "好像……有……",
  ui_story_5040_50400302_161_dialog_content = "欸？妳從哪拿到的？這好像是很早之前的冠月節郵票！",
  ui_story_5040_50400302_162_dialog_content = "我……好像……有……很多……",
  ui_story_5040_50400302_163_dialog_content = "有很多什麼，類似這樣的郵票嗎？",
  ui_story_5040_50400302_164_dialog_content = "嗯……",
  ui_story_5040_50400302_165_dialog_content = "一般人有很多郵票的話，說明是需要經常寄信吧？",
  ui_story_5040_50400302_166_dialog_content = "這就好辦了，我帶妳去找找公會裡無人認領的信件吧？說不定能發現什麼。",
  ui_story_5040_50400302_167_dialog_content = "謝、謝……凱……雅……",
  ui_story_5040_50400302_168_dialog_content = "<color=#e8d9bb>一段時間後——</color>",
  ui_story_5040_50400302_169_dialog_content = "沒有嗎？",
  ui_story_5040_50400302_170_dialog_content = "都……不……是……",
  ui_story_5040_50400302_171_dialog_content = "嗯，說不定妳之前郵寄的地區不是白夜城。",
  ui_story_5040_50400302_172_dialog_content = "不過有條線索可追，總好過先前的漫無目的尋找。",
  ui_story_5040_50400302_173_dialog_content = "跟著PlayerName他們去啟光和紅油扳手分部找找吧。",
  ui_story_5040_50400302_174_dialog_content = "別擔心，會找到的。",
  ui_story_5040_50400302_175_dialog_content = "凱……雅……",
  ui_story_5040_50400302_176_dialog_content = "謝、謝。",
  ui_story_5040_50400302_177_dialog_content = "為、為什麼這麼……幫我？",
  ui_story_5040_50400302_178_dialog_content = "我自己也不知道，可能就是不能放著有難的人不管吧。",
  ui_story_5040_50400302_179_dialog_content = "（我一定也是腦子壞掉了，竟然在幫暗鬼。到底是怎麼想的啊！）",
  ui_story_5040_50400302_180_dialog_content = "（如果是愛梅洛前輩，她也會這麼做嗎？）",
  ui_story_5040_50400401_1_dialog_content = "<color=#e8d9bb>亞度尼斯一行人順利回報納努塞爾後——</color>",
  ui_story_5040_50400401_2_dialog_content = "這就是信使公會的羽毛章嗎？我還是第一次見。",
  ui_story_5040_50400401_3_dialog_content = "看起來確實很精緻！",
  ui_story_5040_50400401_4_dialog_content = "塔拉，妳看妳看！",
  ui_story_5040_50400401_5_dialog_content = "……幹什麼，不要跟我裝熟。",
  ui_story_5040_50400401_6_dialog_content = "羽毛章雖說不是什麼價值連城之物，但也算是有紀念意義的東西。",
  ui_story_5040_50400401_7_dialog_content = "即使在很早以前沒有公會的時候，信使也在很多地方象徵著喜事。",
  ui_story_5040_50400401_8_dialog_content = "貴族們舉辦婚禮也會請信使嗎？",
  ui_story_5040_50400401_9_dialog_content = "白夜城的貴族們更講究這些風俗，甚至有貴族不惜花大價錢請信使在婚禮上做證婚人。",
  ui_story_5040_50400401_10_dialog_content = "這也是為什麼信使公會希望用其他活動來代替這項傳統。",
  ui_story_5040_50400401_11_dialog_content = "尤其是在白夜城。冠月節起源於此，節日習俗更加深入人心。",
  ui_story_5040_50400401_12_dialog_content = "真奇怪，沙漠人從來不過這些亂七八糟的節日。",
  ui_story_5040_50400401_13_dialog_content = "有儀式感不好嗎？多浪漫啊。",
  ui_story_5040_50400401_14_dialog_content = "在白夜城這種把人分為三六九等的地方，儀式是統治階級控制下層的手段。",
  ui_story_5040_50400401_15_dialog_content = "所以才顯得尤其重要。",
  ui_story_5040_50400401_16_dialog_content = "好深奧啊……",
  ui_story_5040_50400401_17_dialog_content = "耶利亞總是說些我聽不懂的話。",
  ui_story_5040_50400401_18_dialog_content = "那我們接下來要不要……",
  ui_story_5040_50400401_19_dialog_content = "耶利亞，我們去哪裡走走吧，我想去散散心。",
  ui_story_5040_50400401_20_dialog_content = "那我也一起……",
  ui_story_5040_50400401_21_dialog_content = "PlayerName，你們兩個和我們分頭行動吧，我想清靜清靜。",
  ui_story_5040_50400401_22_dialog_content = "我是都可以啦。",
  ui_story_5040_50400401_23_dialog_content = "……",
  ui_story_5040_50400401_24_dialog_content = "唉……",
  ui_story_5040_50400401_25_dialog_content = "演戲演累了嗎？",
  ui_story_5040_50400401_26_dialog_content = "我不知道自己這樣做對不對，亞度尼斯好像真的相信我失憶了。",
  ui_story_5040_50400401_27_dialog_content = "我很迷惘，一起賣郵票的時候，感覺他還是我認識的他，細心溫柔。",
  ui_story_5040_50400401_28_dialog_content = "但這也解決不了我們兩個之間的問題，一旦遇到大事，他就又會變得膽小怯懦。",
  ui_story_5040_50400401_29_dialog_content = "可能我們兩個本來就是完全不同的人，根本不應該在一起。",
  ui_story_5040_50400401_30_dialog_content = "只是因為我還喜歡他，所以內心不想承認這個事實吧。",
  ui_story_5040_50400401_31_dialog_content = "我們能選擇自己成為什麼樣的人，但無法控制別人的想法。",
  ui_story_5040_50400401_32_dialog_content = "妳既然選擇和一個人建立親密關係，就要承擔它所帶來的後果。",
  ui_story_5040_50400401_33_dialog_content = "感情愈深，失去的時候也就愈痛。",
  ui_story_5040_50400401_34_dialog_content = "……妳也有過這種感情嗎？",
  ui_story_5040_50400401_35_dialog_content = "當然沒有了，明知會讓自己受傷的事，何必去做？",
  ui_story_5040_50400401_36_dialog_content = "可是，他也帶來了很多快樂，我和他在一起時，多數時候都很開心。",
  ui_story_5040_50400401_37_dialog_content = "因為某種安全感的缺乏，導致的情感投射而已，本質也不過就是價值的交換。",
  ui_story_5040_50400401_38_dialog_content = "妳現在覺得對方提供的價值不如妳的預期了，不就是這樣嗎？",
  ui_story_5040_50400401_39_dialog_content = "我……",
  ui_story_5040_50400401_40_dialog_content = "我不知道，我不想把我們之間的感情做這麼現實的理解。",
  ui_story_5040_50400401_41_dialog_content = "隨妳了。",
  ui_story_5040_50400401_42_dialog_content = "不過總需要經歷過，才知道自己想要什麼，既然事態已經如此，妳也不用著急。",
  ui_story_5040_50400401_43_dialog_content = "這畢竟是妳自己的事，別人說什麼都不重要。",
  ui_story_5040_50400401_44_dialog_content = "妳就慢慢摸索，依照自己的心意來做決定吧。",
  ui_story_5040_50400401_45_dialog_content = "……",
  ui_story_5040_50400401_46_dialog_content = "這裡就是影鎮，氣氛是不是和白夜城完全不同？",
  ui_story_5040_50400401_47_dialog_content = "嗯……",
  ui_story_5040_50400401_48_dialog_content = "你看，白夜城在正上方呢。",
  ui_story_5040_50400401_49_dialog_content = "對影鎮人來說，這種節日恐怕是做商品促銷的絕佳理由吧。",
  ui_story_5040_50400401_50_dialog_content = "雖然奇怪的人很多，不過這裡也有很多好玩的東西。",
  ui_story_5040_50400401_51_dialog_content = "你有沒有特別感興趣的？",
  ui_story_5040_50400401_52_dialog_content = "……",
  ui_story_5040_50400401_53_dialog_content = "（完了，他好像完全提不起勁。）",
  ui_story_5040_50400401_54_dialog_content = "唉，我真不知道自己應該怎麼做了。",
  ui_story_5040_50400401_55_dialog_content = "好像怎麼做都不對，哪怕只有一點點回應也好……好讓我知道接著該怎麼辦啊。",
  ui_story_5040_50400401_56_dialog_content = "這……",
  ui_story_5040_50400401_57_dialog_content = "我們以前無話不談，聊到彼此不瞭解的世界都很興奮……現在為什麼會變成這樣？",
  ui_story_5040_50400401_58_dialog_content = "PlayerName，你堂堂空裔，身邊應該有很多女孩子吧，你理解這種感覺嗎？",
  ui_story_5040_50400401_59_dialog_content = "沒……沒那麼多女孩子。",
  ui_story_5040_50400401_60_dialog_content = "不過我覺得如果感情足夠深厚，是可以為了對方跨越困難的。",
  ui_story_5040_50400401_61_dialog_content = "我和我的兩個好朋友，也是一路經歷了許多困難，甚至是出生入死的場面。",
  ui_story_5040_50400401_62_dialog_content = "大家在經歷中逐漸信任彼此，願意為對方付出，也不怕受到傷害。",
  ui_story_5040_50400401_63_dialog_content = "我想你和塔拉，一定也是這樣的。",
  ui_story_5040_50400401_64_dialog_content = "我……我當然願意為她付出，為她拼命也沒問題。",
  ui_story_5040_50400401_65_dialog_content = "只是我的性格優柔寡斷，許多事情不能馬上做決定。可能她覺得我不像個男人吧。",
  ui_story_5040_50400401_66_dialog_content = "話不能這麼講，每個人的性格都不同，沒人可規定男人的性格就必須該怎麼樣。",
  ui_story_5040_50400401_67_dialog_content = "你們兩個能在一起，肯定因為你有吸引她的地方，誰也不是完美的。",
  ui_story_5040_50400401_68_dialog_content = "嗚哇～她要是像你這麼想就好了！",
  ui_story_5040_50400401_69_dialog_content = "好啦好啦，不哭。",
  ui_story_5040_50400401_70_dialog_content = "喔唷唷～",
  ui_story_5040_50400401_71_dialog_content = "這是什麼絕美畫面？",
  ui_story_5040_50400401_72_dialog_content = "我有靈感了，銀城！",
  ui_story_5040_50400401_73_dialog_content = "被世俗所困，無法在陽光下相見的兩人——",
  ui_story_5040_50400401_74_dialog_content = "他倆不是光明正大的相擁嗎？",
  ui_story_5040_50400401_75_dialog_content = "即使是戀人們最重視的冠月節，也只能在影鎮見不得人的地方偷偷私會——",
  ui_story_5040_50400401_76_dialog_content = "這不都是人嗎？",
  ui_story_5040_50400401_77_dialog_content = "我想為這些族群貢獻我微薄的力量，順便尋找一點點新商機！你覺得是不是很棒！",
  ui_story_5040_50400401_78_dialog_content = "嗯，我覺得棒。",
  ui_story_5040_50400401_79_dialog_content = "喂，這裡面有什麼誤……",
  ui_story_5040_50400401_80_dialog_content = "小哥，我很欣賞你，敢問姓名？",
  ui_story_5040_50400401_81_dialog_content = "我……我嗎？我叫亞度尼斯。",
  ui_story_5040_50400401_82_dialog_content = "亞度尼斯老弟，我覺得你氣質不凡，很明顯和你身邊的男士有相當的差距。",
  ui_story_5040_50400401_83_dialog_content = "為什麼突然人身攻擊？？",
  ui_story_5040_50400401_84_dialog_content = "你應該是為了愛情奮不顧身的那類人，我深深的感受到了。",
  ui_story_5040_50400401_85_dialog_content = "我和我的棒棒糖都感受到了。",
  ui_story_5040_50400401_86_dialog_content = "明人不說暗話，冠月節期間我們買進了一批非常罕見的畫作，其中一幅畫非常適合你。",
  ui_story_5040_50400401_87_dialog_content = "這幅畫作描述的是一對不被允許在一起的戀人，彼此相愛的故事。",
  ui_story_5040_50400401_88_dialog_content = "現正進行冠月節促銷，只要這個價就能擁有！",
  ui_story_5040_50400401_89_dialog_content = "啊，我……這……",
  ui_story_5040_50400401_90_dialog_content = "我懂，你的意思就是想要它，對不對？",
  ui_story_5040_50400401_91_dialog_content = "我覺得是這個意思。",
  ui_story_5040_50400401_92_dialog_content = "我……",
  ui_story_5040_50400401_93_dialog_content = "喂，你們兩個！適可而止！",
  ui_story_5040_50400401_94_dialog_content = "不要欺騙第一次來影鎮的人！",
  ui_story_5040_50400401_95_dialog_content = "PlayerName，君子愛財取之有道，我們只是進行合理的商業談判而已。",
  ui_story_5040_50400401_96_dialog_content = "你們這明顯不合理啊！",
  ui_story_5040_50400401_97_dialog_content = "我很想反駁你，但我好像聽見了什麼聲音。",
  ui_story_5040_50400401_98_dialog_content = "<size=45>呀啊啊！！</size>",
  ui_story_5040_50400401_99_dialog_content = "怎麼了？！",
  ui_story_5040_50400401_100_dialog_content = "有……有暗鬼！",
  ui_story_5040_50400401_101_dialog_content = "這裡哪來的暗鬼？",
  ui_story_5040_50400401_102_dialog_content = "<size=45>嘎——</size>",
  ui_story_5040_50400401_103_dialog_content = "怎麼這麼煩人，打擾我做生意。",
  ui_story_5040_50400401_104_dialog_content = "暗、暗鬼！",
  ui_story_5040_50400401_105_dialog_content = "亞度尼斯，你躲起來！我們先想辦法把這幾隻暗鬼解決。",
  ui_story_5040_50400402_1_dialog_content = "真是的，那兩個人，遇到事情跑得可真快。",
  ui_story_5040_50400402_2_dialog_content = "亞度尼斯，你沒事吧？",
  ui_story_5040_50400402_3_dialog_content = "我、我沒事。",
  ui_story_5040_50400402_4_dialog_content = "抱歉，沒幫上忙……我看見暗鬼腿都軟了。",
  ui_story_5040_50400402_5_dialog_content = "沒事沒事，又不是所有人都習慣和牠們戰鬥。",
  ui_story_5040_50400402_6_dialog_content = "好在蜂和銀城也走了，真難纏啊。",
  ui_story_5040_50400402_7_dialog_content = "這種人喜歡挑軟柿子捏，下次你得果斷拒絕他們才行。",
  ui_story_5040_50400402_8_dialog_content = "唉，我總是這樣。",
  ui_story_5040_50400402_9_dialog_content = "這不是之前賣冠月節郵票的那位嗎？",
  ui_story_5040_50400402_10_dialog_content = "嗯？",
  ui_story_5040_50400402_11_dialog_content = "是說亞度尼斯嗎？之前和他一起的是塔拉，還有信使公會的長老耶利亞。",
  ui_story_5040_50400402_12_dialog_content = "原來是叫這個名字啊。",
  ui_story_5040_50400402_13_dialog_content = "這位是……？",
  ui_story_5040_50400402_14_dialog_content = "你好呀，我是蒂娜，白夜城審判庭的審判官。之前忘記自我介紹，失禮了。",
  ui_story_5040_50400402_15_dialog_content = "你好，我是PlayerName。",
  ui_story_5040_50400402_16_dialog_content = "上午的時候，我曾向那邊的幾位詢問去年冠月節郵票的事。",
  ui_story_5040_50400402_17_dialog_content = "托那位信使的福，我在影鎮找到了。",
  ui_story_5040_50400402_18_dialog_content = "真的嗎？太好了，那是耶利亞提供的情報，我也沒怎麼幫上妳。",
  ui_story_5040_50400402_19_dialog_content = "不過能找到去年的郵票，妳的朋友和他的戀人一定會很開心的。",
  ui_story_5040_50400402_20_dialog_content = "我找到後把郵票交給他，他看起來開心得不得了。",
  ui_story_5040_50400402_21_dialog_content = "一邊捧著郵票一邊感謝我，然後頭也不回的衝進屋裡，開始給戀人寫信呢。",
  ui_story_5040_50400402_22_dialog_content = "那位商人手中還有很多珍貴物品，我正要找她物色其他東西呢，沒想到碰到你們了。",
  ui_story_5040_50400402_23_dialog_content = "不過，這位先生，你臉色不太好，是發生什麼事了嗎？",
  ui_story_5040_50400402_24_dialog_content = "我……其實……",
  ui_story_5040_50400402_25_dialog_content = "嗯～原來是這樣，怪不得上午感覺你們兩人之間有點奇怪。",
  ui_story_5040_50400402_26_dialog_content = "所以你們之後準備去啟光嗎？如果這樣的話，要不要我拜託朋友的戀人，幫你們問問解藥的事？",
  ui_story_5040_50400402_27_dialog_content = "欸？",
  ui_story_5040_50400402_28_dialog_content = "實不相瞞，那位女士正在迦南城的黑傘實驗室工作。",
  ui_story_5040_50400402_29_dialog_content = "如果是關於藥劑，她或許知道些什麼。找她的話，你報我的名字就好。",
  ui_story_5040_50400402_30_dialog_content = "雖然不知道有沒有用，不過也算是我能做的一點小事了。",
  ui_story_5040_50400402_31_dialog_content = "非常感謝，很有用！",
  ui_story_5040_50400402_32_dialog_content = "我們到了那邊就馬上去問問！",
  ui_story_5040_50400402_33_dialog_content = "太好了，亞度尼斯，又多了一些希望呢！",
  ui_story_5040_50400402_34_dialog_content = "那祝你們一切順利。",
  ui_story_5040_50400402_35_dialog_content = "哈欠——有些睏呢，看起來是時候回去休息了。",
  ui_story_5040_50400402_36_dialog_content = "看來你的熱心還是有回報的，等我們到了迦南城就去看看吧。",
  ui_story_5040_50400402_37_dialog_content = "嗯！謝謝你，PlayerName。",
  ui_story_5040_50400402_38_dialog_content = "<color=#e8d9bb>當天晚上——</color>",
  ui_story_5040_50400402_39_dialog_content = "呼，這裡也一無所獲嗎？",
  ui_story_5040_50400402_40_dialog_content = "我……在……努力……",
  ui_story_5040_50400402_41_dialog_content = "我不是在給妳壓力，妳慢慢想就好。",
  ui_story_5040_50400402_42_dialog_content = "不過影鎮也繞了大半天，該回去了。",
  ui_story_5040_50400402_43_dialog_content = "白夜城的夜晚會更安全些。",
  ui_story_5040_50400402_44_dialog_content = "影鎮……白……夜……城……",
  ui_story_5040_50400402_45_dialog_content = "白……夜……",
  ui_story_5040_50400402_46_dialog_content = "怎麼了？妳怎麼盯著白夜城出神？",
  ui_story_5040_50400402_47_dialog_content = "是想起什麼了嗎？",
  ui_story_5040_50400402_48_dialog_content = "白夜……城……很……遠……",
  ui_story_5040_50400402_49_dialog_content = "我……為了……誰……來……",
  ui_story_5040_50400402_50_dialog_content = "我和誰……約定……在……白夜……城？",
  ui_story_5040_50400402_51_dialog_content = "但是……他……沒……來……",
  ui_story_5040_50400402_52_dialog_content = "什麼？妳曾經從別的地方去過白夜城嗎？",
  ui_story_5040_50400402_53_dialog_content = "嗯……有……這種……感覺……",
  ui_story_5040_50400402_54_dialog_content = "也就是說，妳不是白夜城的人。那妳是從哪裡來的，還記得嗎？",
  ui_story_5040_50400402_55_dialog_content = "好像……很遠……",
  ui_story_5040_50400402_56_dialog_content = "嗯……很遠嗎。",
  ui_story_5040_50400402_57_dialog_content = "好啦，別勉強自己了，既然肯定不是白夜城的話，我們再去別的地方看看。",
  ui_story_5040_50400402_58_dialog_content = "PlayerName他們明天好像也要出發去迦南城了，我們就跟著一起吧。",
  ui_story_5040_50400402_59_dialog_content = "到那邊的信使公會再看看，說不定會有新發現。",
  ui_story_5040_50400402_60_dialog_content = "好……",
  ui_story_5040_50400402_61_dialog_content = "<color=#e8d9bb>翌日——</color>",
  ui_story_5040_50400402_62_dialog_content = "好了，大家都準備好了嗎？不要忘了東西啊。",
  ui_story_5040_50400402_63_dialog_content = "呵呵，很久沒去啟光了，不知道那邊的小鳥們怎麼樣了。",
  ui_story_5040_50400402_64_dialog_content = "還請您一定不要給她們添太多麻煩。",
  ui_story_5040_50400402_65_dialog_content = "啟光是高度軍事化的地方，塔拉以前跟我講過，我早就想親眼看看了。",
  ui_story_5040_50400402_66_dialog_content = "我對他們的新式卡車很有興趣。",
  ui_story_5040_50400402_67_dialog_content = "那麼，出發！",
  ui_story_5040_50400502_1_dialog_content = "哇……這就是迦南城嗎！",
  ui_story_5040_50400502_2_dialog_content = "我也只來過一次而已。",
  ui_story_5040_50400502_3_dialog_content = "怎麼說呢，迦南城好像一直沒怎麼變。",
  ui_story_5040_50400502_4_dialog_content = "PlayerName經常來啟光嗎？",
  ui_story_5040_50400502_5_dialog_content = "那倒也沒有，只是我有位熟識的好友來自啟光，我們一起來過幾次。",
  ui_story_5040_50400502_6_dialog_content = "不過她最近也在休假，大概是碰不到了。",
  ui_story_5040_50400502_7_dialog_content = "迦南城不過冠月節嗎？街上完全沒有什麼節日氣氛。",
  ui_story_5040_50400502_8_dialog_content = "當然過冠月節，而且這節日還很深入人心呢。",
  ui_story_5040_50400502_9_dialog_content = "只是不同地方人們的生活大相徑庭，啟光不像白夜城，不太講究排場。",
  ui_story_5040_50400502_10_dialog_content = "大家比較務實，也很低調。大部分女性在這一天，會親手製作肉桂卷送給心上人。",
  ui_story_5040_50400502_11_dialog_content = "男性則會在袖口內畫一顆心，然後寫上心上人的名字。",
  ui_story_5040_50400502_12_dialog_content = "聽起來滿可愛。",
  ui_story_5040_50400502_13_dialog_content = "是啊，感覺很浪漫！我也寫一個吧！",
  ui_story_5040_50400502_14_dialog_content = "喂……",
  ui_story_5040_50400502_15_dialog_content = "說起來，耶利亞還真是什麼都知道。",
  ui_story_5040_50400502_16_dialog_content = "聽說耶利亞長老以前去過很多地方，不過很少聽她提起呢。",
  ui_story_5040_50400502_17_dialog_content = "都是過去的事情，不值一提，不過那邊那位，如果我沒認錯的話……",
  ui_story_5040_50400502_18_dialog_content = "？！！",
  ui_story_5040_50400502_19_dialog_content = "應該是啟光的小鳥吧。",
  ui_story_5040_50400502_20_dialog_content = "多孚？這個時候妳不是應該在送信嗎？",
  ui_story_5040_50400502_21_dialog_content = "唔，是在送啊，過節了也不會咕咕。",
  ui_story_5040_50400502_22_dialog_content = "我只是按照自己的步調在送信而已。",
  ui_story_5040_50400502_23_dialog_content = "這句話我非常懷疑……",
  ui_story_5040_50400502_24_dialog_content = "啟光的前輩嗎？倒是有所耳聞，雖然都是負面的。",
  ui_story_5040_50400502_25_dialog_content = "怎麼能這麼說，我也是有好好工作的，誰讓過節前的包裹多得像山。",
  ui_story_5040_50400502_26_dialog_content = "根本不可能送完，好麻煩咕。",
  ui_story_5040_50400502_27_dialog_content = "所以妳果然是在摸魚吧。",
  ui_story_5040_50400502_28_dialog_content = "不過先不說這個，多孚知道冠月節羽毛章的事情嗎？",
  ui_story_5040_50400502_29_dialog_content = "羽毛章？就在我身上啊。",
  ui_story_5040_50400502_30_dialog_content = "欸？！",
  ui_story_5040_50400502_31_dialog_content = "公會的前輩也都忙著四處送信不在公會，所以先給我保管了。",
  ui_story_5040_50400502_32_dialog_content = "聽起來像是因為妳在摸魚，所以對方不得不加班。",
  ui_story_5040_50400502_33_dialog_content = "你問這個幹嘛咕？",
  ui_story_5040_50400502_34_dialog_content = "其實我們是想來蓋羽毛章的情侶，不知道啟光的信使公會，蓋章需要做什麼？",
  ui_story_5040_50400502_35_dialog_content = "啊……這樣啊。",
  ui_story_5040_50400502_36_dialog_content = "這個容易啊，幫我把剩下的包裹派發一下就行了。",
  ui_story_5040_50400502_37_dialog_content = "……妳這樣是合乎規定的嗎？",
  ui_story_5040_50400502_38_dialog_content = "反正現在印章在我這，規則由我說了算。",
  ui_story_5040_50400502_39_dialog_content = "雖然有些對不住，不過如果你們願意幫忙的話就太感謝了。",
  ui_story_5040_50400502_40_dialog_content = "沒問題！交給我們吧！",
  ui_story_5040_50400502_41_dialog_content = "<color=#e8d9bb>一刻鐘後——</color>",
  ui_story_5040_50400502_42_dialog_content = "……",
  ui_story_5040_50400502_43_dialog_content = "……",
  ui_story_5040_50400502_44_dialog_content = "……",
  ui_story_5040_50400502_45_dialog_content = "確實還不少呢。",
  ui_story_5040_50400502_46_dialog_content = "喂，這已經不是不少的問題了吧！怎麼會積了這麼多包裹啊！",
  ui_story_5040_50400502_47_dialog_content = "我們兩人三天不吃不喝不眠不休也送不完吧……",
  ui_story_5040_50400502_48_dialog_content = "對不起……我沒想到會有這麼多。",
  ui_story_5040_50400502_49_dialog_content = "唉，沒辦法了，大家一起送吧。",
  ui_story_5040_50400502_50_dialog_content = "我也來幫忙，順便路上也帶小黑四處轉轉。",
  ui_story_5040_50400502_51_dialog_content = "抱歉，明明是我們倆的事，結果又給你們另外添了麻煩。",
  ui_story_5040_50400502_52_dialog_content = "我們來負責最多的部分吧，我還算擅長體力勞動。",
  ui_story_5040_50400502_53_dialog_content = "我會邊看書邊為你們加油的。",
  ui_story_5040_50400502_54_dialog_content = "耶利亞長老……不過這樣也好，以免出現更多不必要的麻煩……",
  ui_story_5040_50400502_55_dialog_content = "好！那就馬上動起來吧！",
  ui_story_5040_50400502_56_dialog_content = "哇啊……！",
  ui_story_5040_50400502_57_dialog_content = "喂，太慢了吧，亞度尼斯！",
  ui_story_5040_50400502_58_dialog_content = "對……對不起，這樓梯好陡。",
  ui_story_5040_50400502_59_dialog_content = "倒是小心點啊！",
  ui_story_5040_50400502_60_dialog_content = "你把手裡的包裹分別歸類一下，這附近的你送，遠的我來吧。",
  ui_story_5040_50400502_61_dialog_content = "那怎麼行，這也太多了。",
  ui_story_5040_50400502_62_dialog_content = "我習慣跑來跑去了，這樣效率反而高一點。",
  ui_story_5040_50400502_63_dialog_content = "好……好吧。",
  ui_story_5040_50400502_64_dialog_content = "薇、薇薇安！妳的包裹！",
  ui_story_5040_50400502_65_dialog_content = "這不是PlayerName嗎？薇絲今天沒和……",
  ui_story_5040_50400502_66_dialog_content = "知道的！那包裹送到了！我先走了！",
  ui_story_5040_50400502_67_dialog_content = "怎麼是你跑來送呢？",
  ui_story_5040_50400502_68_dialog_content = "……多孚，妳的績效完了。",
  ui_story_5040_50400502_69_dialog_content = "您好，請妥善保存您的信件～",
  ui_story_5040_50400502_70_dialog_content = "好，那這層就送完了。",
  ui_story_5040_50400502_71_dialog_content = "凱雅……厲害……",
  ui_story_5040_50400502_72_dialog_content = "嘿嘿，這本來也是我的工作嘛。",
  ui_story_5040_50400502_73_dialog_content = "如果妳路上看到什麼有印象的東西，要馬上告訴我啊。",
  ui_story_5040_50400502_74_dialog_content = "<color=#e8d9bb>幾個小時後——</color>",
  ui_story_5040_50400502_75_dialog_content = "我……已經不行了。",
  ui_story_5040_50400502_76_dialog_content = "呼……呼……PlayerName已經送完了嗎？",
  ui_story_5040_50400502_77_dialog_content = "是的……終於……",
  ui_story_5040_50400502_78_dialog_content = "確實跑了不少地方，不過你們倆的體力也太差了吧。",
  ui_story_5040_50400502_79_dialog_content = "辛苦了，看來順利完成任務了呢。",
  ui_story_5040_50400502_80_dialog_content = "凱雅還沒回來嗎？",
  ui_story_5040_50400502_81_dialog_content = "不用擔心她，她應該早就送完了，畢竟北境的小鳥效率很高呢。",
  ui_story_5040_50400502_82_dialog_content = "現在可能是在帶著那隻黑色的小鳥，在外面逛街吧。",
  ui_story_5040_50400502_83_dialog_content = "嘿嘿，不愧是PlayerName。",
  ui_story_5040_50400502_84_dialog_content = "多孚？！妳一直在附近閒逛嗎？",
  ui_story_5040_50400502_85_dialog_content = "不是閒逛，我也是有在工作的。",
  ui_story_5040_50400502_86_dialog_content = "我們順利完成任務了，可以給我們蓋章了嗎？",
  ui_story_5040_50400502_87_dialog_content = "沒問題，來吧，新鮮的羽毛章！",
  ui_story_5040_50400502_88_dialog_content = "當當！",
  ui_story_5040_50400502_89_dialog_content = "啊哈，這下啟光的羽毛章也有了！",
  ui_story_5040_50400502_90_dialog_content = "雖然不知道到底有什麼意義。",
  ui_story_5040_50400502_91_dialog_content = "別這麼說，我們不是已經漸漸熟識起來了嗎？",
  ui_story_5040_50400502_92_dialog_content = "誰……誰跟你熟起來了。",
  ui_story_5040_50400502_93_dialog_content = "不過現在章也蓋完了，下一步去哪裡？",
  ui_story_5040_50400502_94_dialog_content = "好不容易來一次迦南城，大家一起嚐嚐在地美食，然後去放映廳看個電影吧。",
  ui_story_5040_50400502_95_dialog_content = "感覺這樣比較有節日氣氛！",
  ui_story_5040_50400502_96_dialog_content = "啟光的食物什麼時候都能吃吧。",
  ui_story_5040_50400502_97_dialog_content = "我送信時聽說地下城輸送了一批最新的動能槍，我想去整備場參觀一下。",
  ui_story_5040_50400502_98_dialog_content = "冠月節去整備場？也太不浪漫了。",
  ui_story_5040_50400502_99_dialog_content = "你不想去的話，我們就分頭行動好了。",
  ui_story_5040_50400502_100_dialog_content = "我……",
  ui_story_5040_50400502_101_dialog_content = "兩位稍安勿躁，在這之前，應該有更重要的事吧？",
  ui_story_5040_50400502_102_dialog_content = "還是說，兩位已經忘了來這裡的目的？",
  ui_story_5040_50400502_103_dialog_content = "是喔，關於塔拉失憶的事情，之前說要去黑傘實驗室問問看。",
  ui_story_5040_50400502_104_dialog_content = "啊……是。",
  ui_story_5040_50400502_105_dialog_content = "……",
  ui_story_5040_50400502_106_dialog_content = "事不宜遲，趁著天色尚早，不如先辦正事。",
  ui_story_5040_50400601_1_dialog_content = "（真是好久沒來了。）",
  ui_story_5040_50400601_2_dialog_content = "事情就是這樣的，麻煩妳了。",
  ui_story_5040_50400601_3_dialog_content = "我已經聽他說了，真的很感謝蒂娜小姐，也很感謝各位！",
  ui_story_5040_50400601_4_dialog_content = "啟光和白夜城的關係本來就有些尷尬，我們兩人也是受到很多阻礙。",
  ui_story_5040_50400601_5_dialog_content = "但還是有支持我們的人，像是蒂娜小姐。",
  ui_story_5040_50400601_6_dialog_content = "她明明是貴族，卻一直支持著我們的戀情。",
  ui_story_5040_50400601_7_dialog_content = "聽說她的身體需要大量的睡眠來支撐，即使如此還是幫我們尋找郵票。",
  ui_story_5040_50400601_8_dialog_content = "嗯，蒂娜小姐確實是有些不可思議的人呢。",
  ui_story_5040_50400601_9_dialog_content = "她總是彬彬有禮的，非常溫柔。",
  ui_story_5040_50400601_10_dialog_content = "但她似乎也有自己的煩惱呢，聽說審判庭的工作也很「微妙」。",
  ui_story_5040_50400601_11_dialog_content = "不知道下一次見面是什麼時候？我也想多了解一點關於蒂娜小姐的事呢。",
  ui_story_5040_50400601_12_dialog_content = "不過聽她的描述，感覺妳和妳的戀人也不容易。",
  ui_story_5040_50400601_13_dialog_content = "就是啊。幹嘛不兩人一走了之？",
  ui_story_5040_50400601_14_dialog_content = "我們都有自己必須要做的事，首先是自己，其次才是戀人。",
  ui_story_5040_50400601_15_dialog_content = "我和他都是很有責任感的人，也是因此才互相吸引吧。",
  ui_story_5040_50400601_16_dialog_content = "兩個人如果真心對待彼此，距離和外力都不是難題，畢竟心是連在一起的。",
  ui_story_5040_50400601_17_dialog_content = "心……連在一起？",
  ui_story_5040_50400601_18_dialog_content = "我也是這麼認為的，真的有愛的話，其他問題反而不是問題了。",
  ui_story_5040_50400601_19_dialog_content = "啊哈哈，我們談正事吧。這位小姐叫塔拉是嗎？我大概明白妳的問題了。",
  ui_story_5040_50400601_20_dialog_content = "只是我目前是以實習的形式在這裡工作，具體作法我去問一下我的同事，請稍等。",
  ui_story_5040_50400601_21_dialog_content = "麻煩妳了！",
  ui_story_5040_50400601_22_dialog_content = "<size=33>耶利亞，我裝病的事情不會露餡吧？</size>",
  ui_story_5040_50400601_23_dialog_content = "演不下去的話承認不就好了？",
  ui_story_5040_50400601_24_dialog_content = "<size=33>那怎麼行！我以後怎麼在大家面前做人！</size>",
  ui_story_5040_50400601_25_dialog_content = "妳都想出了這種主意，還怕丟人？",
  ui_story_5040_50400601_26_dialog_content = "<size=33>不行，總之到時候如果出了問題，幫我打一下圓場啊。</size>",
  ui_story_5040_50400601_27_dialog_content = "……",
  ui_story_5040_50400601_28_dialog_content = "（她果然是裝失憶啊，不過我就裝作不知道吧。）",
  ui_story_5040_50400601_29_dialog_content = "耶利亞，妳們在說什麼呢？",
  ui_story_5040_50400601_30_dialog_content = "沒什麼！只是在說這個科研室看著挺厲害的。",
  ui_story_5040_50400601_31_dialog_content = "那是當然，負責人彌加德是位很厲害又深不可測的人。",
  ui_story_5040_50400601_32_dialog_content = "塔拉，妳怎麼在發抖？",
  ui_story_5040_50400601_33_dialog_content = "她只是有點冷。",
  ui_story_5040_50400601_34_dialog_content = "嗯？這裡也不冷啊。",
  ui_story_5040_50400601_35_dialog_content = "各位，請跟我來吧。我向你們引薦實驗室的前輩。",
  ui_story_5040_50400601_36_dialog_content = "麻煩妳了。",
  ui_story_5040_50400601_37_dialog_content = "尤拉前輩，這位就是我剛剛提到的塔拉小姐，她目前失去記憶了。",
  ui_story_5040_50400601_38_dialog_content = "麻煩您了。非常感謝。",
  ui_story_5040_50400601_39_dialog_content = "喔～聽說幾位幫了我的同事，作為回禮這也是應該的，不必客氣。",
  ui_story_5040_50400601_40_dialog_content = "塔拉小姐，可以讓我近距離看一下嗎？",
  ui_story_5040_50400601_41_dialog_content = "好……好的。",
  ui_story_5040_50400601_42_dialog_content = "可惜今天彌加德不在，這方面我確實不是專家，但也略懂一二。",
  ui_story_5040_50400601_43_dialog_content = "（呼，太好了。）",
  ui_story_5040_50400601_44_dialog_content = "嗯……初步看起來沒什麼問題，流程上我們就先測試一下身體基本情況吧。",
  ui_story_5040_50400601_45_dialog_content = "測試身體情況是指？",
  ui_story_5040_50400601_46_dialog_content = "（怎麼感覺他笑得好嚇人……）",
  ui_story_5040_50400601_47_dialog_content = "別緊張，只是靠一些小小的刺激，伸展一下肌肉而已。",
  ui_story_5040_50400601_48_dialog_content = "嘎——！",
  ui_story_5040_50400601_49_dialog_content = "不、不是吧……",
  ui_story_5040_50400602_1_dialog_content = "呼！怎麼不早說是要用暗鬼做測試啊。",
  ui_story_5040_50400602_2_dialog_content = "喂！這種測試要提前說一聲啊！",
  ui_story_5040_50400602_3_dialog_content = "哎呀，不好意思，不過我以為這對各位來說不算什麼呢。",
  ui_story_5040_50400602_4_dialog_content = "畢竟你們的組合著實有趣，有北境來的、沙漠人、亞人信使……甚至還有空裔。",
  ui_story_5040_50400602_5_dialog_content = "這些不重要啦，我們是來幫塔拉看病的。",
  ui_story_5040_50400602_6_dialog_content = "我有什麼問題嗎？",
  ui_story_5040_50400602_7_dialog_content = "這樣看，也看不出妳的身體有什麼異常。",
  ui_story_5040_50400602_8_dialog_content = "那測試也做完了，現在還能怎麼辦呢？",
  ui_story_5040_50400602_9_dialog_content = "嗯，關於她生病的契機，還有更多資訊嗎？",
  ui_story_5040_50400602_10_dialog_content = "讓我想想，製作萬能藥水的靈媒說，這個藥是用珍貴稀有的原料做的。",
  ui_story_5040_50400602_11_dialog_content = "好像是紅油沙漠的什麼粉色大沙蟲，說是難得一見的稀有物種。",
  ui_story_5040_50400602_12_dialog_content = "你說……粉色沙蟲？",
  ui_story_5040_50400602_13_dialog_content = "是啊。",
  ui_story_5040_50400602_14_dialog_content = "尤拉，你知道這個東西嗎？",
  ui_story_5040_50400602_15_dialog_content = "……",
  ui_story_5040_50400602_16_dialog_content = "這種沙蟲竟然又出現在人們的眼前了嗎……",
  ui_story_5040_50400602_17_dialog_content = "<size=33>這怎麼可能？不應該啊！</size>",
  ui_story_5040_50400602_18_dialog_content = "<size=33>塔拉？</size>",
  ui_story_5040_50400602_19_dialog_content = "<size=33>粉色沙蟲的鱗片明明早就在我手裡，靈媒怎麼會有的？！</size>",
  ui_story_5040_50400602_20_dialog_content = "<size=33>竟然真的有這種沙蟲，鱗片難道只有一枚嗎？</size>",
  ui_story_5040_50400602_21_dialog_content = "<size=33>據我瞭解，這隻沙蟲應該只有一枚鱗片流通到市面上，怎麼會突然冒出其他的？</size>",
  ui_story_5040_50400602_22_dialog_content = "我是專攻植物方面的專家，曾經尋找某一種孢子的時候，聽彌加德跟我提過一次。",
  ui_story_5040_50400602_23_dialog_content = "那種孢子幾乎沒有人研究過，只在書籍上有記載。它寄生在一種外形為粉色的沙蟲的鱗片上。",
  ui_story_5040_50400602_24_dialog_content = "彌加德曾經提到過這種沙蟲，聽說有人在紅油沙漠目擊過，但極少有人真正見過。",
  ui_story_5040_50400602_25_dialog_content = "牠比普通沙蟲更加兇暴，無人能靠近，鱗片是十分稀有且珍貴的材料，聽說只有一枚流通到市面。",
  ui_story_5040_50400602_26_dialog_content = "如果各位能得到這種鱗片的話，我可以嘗試研製解藥。",
  ui_story_5040_50400602_27_dialog_content = "但除此之外的方法，我暫時也沒有頭緒，十分抱歉。",
  ui_story_5040_50400602_28_dialog_content = "……",
  ui_story_5040_50400602_29_dialog_content = "……",
  ui_story_5040_50400602_30_dialog_content = "嗯，這樣我們的目標就明確多了。",
  ui_story_5040_50400602_31_dialog_content = "耶利亞？",
  ui_story_5040_50400602_32_dialog_content = "既然之後也要去沙漠，那我就把紅油扳手分部的考驗內容定為打倒粉色沙蟲、取得鱗片。",
  ui_story_5040_50400602_33_dialog_content = "喂，妳認真的嗎？",
  ui_story_5040_50400602_34_dialog_content = "壓根就沒幾個人見過那什麼沙蟲，我在沙漠這麼多年都沒聽說過。妳難道聽說過？",
  ui_story_5040_50400602_35_dialog_content = "我也沒聽說過。",
  ui_story_5040_50400602_36_dialog_content = "那妳為什麼要安排這種考驗！",
  ui_story_5040_50400602_37_dialog_content = "如果只有這種方法能讓塔拉恢復記憶，那我願意試試。",
  ui_story_5040_50400602_38_dialog_content = "欸？",
  ui_story_5040_50400602_39_dialog_content = "亞度尼斯？你瘋了嗎？",
  ui_story_5040_50400602_40_dialog_content = "其實我也很絕望……我知道自己能力差，又膽小，家裡的蟲子都怕得要死，何況是傳說中的大沙蟲。",
  ui_story_5040_50400602_41_dialog_content = "但是塔拉的病因我而起，我不能讓她一直這樣。",
  ui_story_5040_50400602_42_dialog_content = "我也知道她一直因為我的軟弱而生氣，我想改變自己。",
  ui_story_5040_50400602_43_dialog_content = "就這件事來說，我不能逃避。",
  ui_story_5040_50400602_44_dialog_content = "太讓人感動了吧。",
  ui_story_5040_50400602_45_dialog_content = "亞度尼斯！其實我……！",
  ui_story_5040_50400602_46_dialog_content = "嗯，言辭感人，所以現在你覺得自己能打倒沙蟲了嗎？",
  ui_story_5040_50400602_47_dialog_content = "這當然也不是一蹴而就的！幫幫我吧，我需要鍛鍊自己！",
  ui_story_5040_50400602_48_dialog_content = "哪怕從面對暗鬼開始也行，我要讓自己變得更強大！",
  ui_story_5040_50400602_49_dialog_content = "你能戰鬥嗎？",
  ui_story_5040_50400602_50_dialog_content = "我記得你父親說，你曾經和諾維亞學習過光能術？",
  ui_story_5040_50400602_51_dialog_content = "是，我小時候曾經溜到圖書館看書，諾維亞老師常常指導我。",
  ui_story_5040_50400602_52_dialog_content = "我的光能術不算強大，但也有一些基礎。",
  ui_story_5040_50400602_53_dialog_content = "嗯～",
  ui_story_5040_50400602_54_dialog_content = "耶利亞，妳的表情讓我想到一些可怕的事情。",
  ui_story_5040_50400602_55_dialog_content = "放心，大家暫時是同舟共濟，我不會為難他的。",
  ui_story_5040_50400602_56_dialog_content = "那簡單，既然你也說了，可以從面對暗鬼開始……",
  ui_story_5040_50400602_57_dialog_content = "要……要直接讓我和暗鬼戰鬥嗎？",
  ui_story_5040_50400602_58_dialog_content = "讓你獨自面對暗鬼也太殘酷了，呵呵，我只是想到了一個方法。",
  ui_story_5040_50400602_59_dialog_content = "讓她做你的對手說不定很合適。",
  ui_story_5040_50400701_1_dialog_content = "耶利亞長老，特意叫我們來外面，有什麼事嗎？",
  ui_story_5040_50400701_2_dialog_content = "耶利亞，妳說的不會是……",
  ui_story_5040_50400701_3_dialog_content = "嗷……？",
  ui_story_5040_50400701_4_dialog_content = "嗯嗯～你不覺得很合適嗎？凱雅這位黑色的小鳥親戚，無論氣質舉止都很像暗鬼呢。",
  ui_story_5040_50400701_5_dialog_content = "用來做亞度尼斯的戰鬥練習對象，不是正合適嗎？",
  ui_story_5040_50400701_6_dialog_content = "怎麼說呢，雖然小黑確實皮膚黑得不太像光靈，但拿人家當暗鬼是不是有點過分？",
  ui_story_5040_50400701_7_dialog_content = "（不過說實話，這個小黑應該和暗鬼有些關係。）",
  ui_story_5040_50400701_8_dialog_content = "（但她既然是凱雅帶來的，目前為止也沒做什麼奇怪的事，先靜觀其變吧。）",
  ui_story_5040_50400701_9_dialog_content = "戰……鬥……？",
  ui_story_5040_50400701_10_dialog_content = "小黑不會戰鬥，萬一被傷到怎麼辦？",
  ui_story_5040_50400701_11_dialog_content = "放輕鬆放輕鬆，不是真刀實槍，只是幫亞度尼斯壯壯膽罷了。",
  ui_story_5040_50400701_12_dialog_content = "當事人自己覺得呢？",
  ui_story_5040_50400701_13_dialog_content = "唔，雖然這樣有些無禮……但如果小黑願意幫忙的話，我會非常感激的。",
  ui_story_5040_50400701_14_dialog_content = "以我現在的情況，如果直接去面對真正的暗鬼，可能也是兇多吉少。",
  ui_story_5040_50400701_15_dialog_content = "而且我很少使用光能術，也不是很熟練。在外面總是靠塔拉保護我。",
  ui_story_5040_50400701_16_dialog_content = "每個人擅長的事情不一樣，你也不用非得勉強就是了。",
  ui_story_5040_50400701_17_dialog_content = "保護你也並沒有成為我的負擔啊。",
  ui_story_5040_50400701_18_dialog_content = "塔拉？",
  ui_story_5040_50400701_19_dialog_content = "不行，無論如何，我都要超越原來的自己。",
  ui_story_5040_50400701_20_dialog_content = "拜託了，凱雅、小黑！幫幫我吧！",
  ui_story_5040_50400701_21_dialog_content = "呃，小黑，妳可以嗎？",
  ui_story_5040_50400701_22_dialog_content = "如果……能……幫忙……",
  ui_story_5040_50400701_23_dialog_content = "我……可……可以！",
  ui_story_5040_50400701_24_dialog_content = "妳不用勉強哦，只是做個模擬練習。",
  ui_story_5040_50400701_25_dialog_content = "不……勉強……",
  ui_story_5040_50400701_26_dialog_content = "幫……忙……開心……",
  ui_story_5040_50400701_27_dialog_content = "太感謝了！小黑！",
  ui_story_5040_50400701_28_dialog_content = "嘎——嘎——",
  ui_story_5040_50400701_29_dialog_content = "是我幻聽了嗎？我怎麼真的覺得有暗鬼的聲音。",
  ui_story_5040_50400701_30_dialog_content = "欸？！",
  ui_story_5040_50400701_31_dialog_content = "<size=45>嘎——嗷——！</size>",
  ui_story_5040_50400701_32_dialog_content = "小心！有暗鬼！",
  ui_story_5040_50400701_33_dialog_content = "怎、怎麼會！從哪裡來的！",
  ui_story_5040_50400701_34_dialog_content = "說來也真是奇怪，好像妳和黑色的小鳥總會吸引暗鬼呢。",
  ui_story_5040_50400701_35_dialog_content = "還是說，只是巧合？",
  ui_story_5040_50400701_36_dialog_content = "唔！",
  ui_story_5040_50400701_37_dialog_content = "（是被小黑吸引來的嗎？）",
  ui_story_5040_50400701_38_dialog_content = "暗……鬼……？",
  ui_story_5040_50400701_39_dialog_content = "不要分心，先集中把這幾隻害蟲解決掉吧。",
  ui_story_5040_50400701_40_dialog_content = "亞度尼斯，小心些，躲在我後面！",
  ui_story_5040_50400701_41_dialog_content = "我、我知道了。",
  ui_story_5040_50400702_1_dialog_content = "總算解決掉了，大家都沒事吧？",
  ui_story_5040_50400702_2_dialog_content = "沒事沒事，這幾隻暗鬼還不至於會造成什麼傷害。",
  ui_story_5040_50400702_3_dialog_content = "我……我也還好。",
  ui_story_5040_50400702_4_dialog_content = "你們是司空見慣，那邊的兩位可就不一定了。",
  ui_story_5040_50400702_5_dialog_content = "唔！",
  ui_story_5040_50400702_6_dialog_content = "害……害怕……",
  ui_story_5040_50400702_7_dialog_content = "（讓這樣的兩人互相訓練膽量，真的沒問題嗎？）",
  ui_story_5040_50400702_8_dialog_content = "兩位需要稍作休息，還是我們直接開始？",
  ui_story_5040_50400702_9_dialog_content = "我……我不用休息。",
  ui_story_5040_50400702_10_dialog_content = "不……不用……！",
  ui_story_5040_50400702_11_dialog_content = "不要勉強啊，小黑。",
  ui_story_5040_50400702_12_dialog_content = "既然都這麼有勇氣，那就直接開始吧。",
  ui_story_5040_50400702_13_dialog_content = "<color=#e8d9bb>一刻鐘後——</color>",
  ui_story_5040_50400702_14_dialog_content = "……",
  ui_story_5040_50400702_15_dialog_content = "……",
  ui_story_5040_50400702_16_dialog_content = "那個，準備什麼時候開始呢？已經站一刻鐘了。",
  ui_story_5040_50400702_17_dialog_content = "我、我要上了啊！",
  ui_story_5040_50400702_18_dialog_content = "……！！",
  ui_story_5040_50400702_19_dialog_content = "看起來完全沒有要戰鬥的架勢就是了。",
  ui_story_5040_50400702_20_dialog_content = "我這次真的要上了！",
  ui_story_5040_50400702_21_dialog_content = "好……好的……",
  ui_story_5040_50400702_22_dialog_content = "<color=#e8d9bb>一小時後——</color>",
  ui_story_5040_50400702_23_dialog_content = "這一次，絕對絕對要上了！",
  ui_story_5040_50400702_24_dialog_content = "看、看好了啊！",
  ui_story_5040_50400702_25_dialog_content = "（好睏啊，感覺可以先去睡一下。）",
  ui_story_5040_50400702_26_dialog_content = "亞度尼斯，其實我覺得真的不用勉強。",
  ui_story_5040_50400702_27_dialog_content = "小黑加油！",
  ui_story_5040_50400702_28_dialog_content = "……",
  ui_story_5040_50400702_29_dialog_content = "難道真刀實槍時候，暗鬼就在你眼前，你也要虛晃一個鐘頭才開始進攻嗎？",
  ui_story_5040_50400702_30_dialog_content = "你是為了心愛的人，才需要和暗鬼戰鬥的吧？",
  ui_story_5040_50400702_31_dialog_content = "如果塔拉此時無法戰鬥，就在暗鬼眼皮底下，你還能這麼猶豫嗎？",
  ui_story_5040_50400702_32_dialog_content = "那等待你們的是什麼結果，就不用我多說了吧？",
  ui_story_5040_50400702_33_dialog_content = "我……我……",
  ui_story_5040_50400702_34_dialog_content = "還是說，她受傷也無所謂？你還是過不了自己猶豫懦弱的那一關？",
  ui_story_5040_50400702_35_dialog_content = "不，不是的！",
  ui_story_5040_50400702_36_dialog_content = "因為膽怯踏不出那一步，就要對方以性命為賭注，誰願意和這種人在一起呢？",
  ui_story_5040_50400702_37_dialog_content = "<size=33>喂，這激將法也太過分了。</size>",
  ui_story_5040_50400702_38_dialog_content = "<size=33>聽著好可憐，小黑，妳也幫幫他。</size>",
  ui_story_5040_50400702_39_dialog_content = "<size=45>嘎！嘎嗷——！</size>",
  ui_story_5040_50400702_40_dialog_content = "<size=55>哇啊啊啊啊！！！</size>",
  ui_story_5040_50400702_41_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5040_50400702_42_dialog_content = "呼啊……呼啊……",
  ui_story_5040_50400702_43_dialog_content = "呃……",
  ui_story_5040_50400702_44_dialog_content = "小、小黑沒事吧！",
  ui_story_5040_50400702_45_dialog_content = "沒……有……事……",
  ui_story_5040_50400702_46_dialog_content = "竟然下得了手了？",
  ui_story_5040_50400702_47_dialog_content = "有進展啊，亞度尼斯！至少不是一直躲在後面了！",
  ui_story_5040_50400702_48_dialog_content = "雖然是一種完全不構成傷害的進攻方式，但正如空裔小哥所說，有所進步。",
  ui_story_5040_50400702_49_dialog_content = "實戰中應該完全打不中對方就是了。",
  ui_story_5040_50400702_50_dialog_content = "有進步就是最重要的！超越自己最困難了！",
  ui_story_5040_50400702_51_dialog_content = "塔拉，謝謝！",
  ui_story_5040_50400702_52_dialog_content = "嗚嗚，謝謝大家，還有小黑！",
  ui_story_5040_50400702_53_dialog_content = "不用……",
  ui_story_5040_50400702_54_dialog_content = "可以，照這個架勢可以繼續訓練。",
  ui_story_5040_50400702_55_dialog_content = "耶利亞，今天就算了吧。天快要暗下來了，大家也都累了。",
  ui_story_5040_50400702_56_dialog_content = "我們就讓亞度尼斯循序漸進的訓練，今天先回城裡吧。",
  ui_story_5040_50400702_57_dialog_content = "嗯，既然空裔小哥這麼說了，那也好。",
  ui_story_5040_50400702_58_dialog_content = "呃……",
  ui_story_5040_50400702_59_dialog_content = "咦？怎麼了？哪裡不舒服嗎？",
  ui_story_5040_50400702_60_dialog_content = "沒……沒有……",
  ui_story_5040_50400702_61_dialog_content = "感覺……想起……",
  ui_story_5040_50400702_62_dialog_content = "欸？？",
  ui_story_5040_50400702_63_dialog_content = "沙漠……沙漠……",
  ui_story_5040_50400702_64_dialog_content = "沙漠？紅油沙漠嗎？",
  ui_story_5040_50400702_65_dialog_content = "不……知道……但是……",
  ui_story_5040_50400702_66_dialog_content = "想起了……沙漠……",
  ui_story_5040_50400702_67_dialog_content = "難道是剛剛亞度尼斯那一下子，刺激了妳的記憶？",
  ui_story_5040_50400702_68_dialog_content = "如果是紅油沙漠的話，正好下一站就要去。",
  ui_story_5040_50400702_69_dialog_content = "……",
  ui_story_5040_50400702_70_dialog_content = "大家看起來都累了，我們今天就解散休息吧。",
  ui_story_5040_50400702_71_dialog_content = "都是我的原因，不知道怎麼感謝各位。",
  ui_story_5040_50400702_72_dialog_content = "本來這是我們兩個的問題，讓你們一路陪著跑來跑去的。",
  ui_story_5040_50400702_73_dialog_content = "塔拉，我們去給大家買些啟光的特產當零食吧，眼下也做不了什麼別的。",
  ui_story_5040_50400702_74_dialog_content = "啊哈哈，不用那麼客氣。",
  ui_story_5040_50400702_75_dialog_content = "（啟光的特產真的能當零食吃嗎？）",
  ui_story_5040_50400702_76_dialog_content = "同意。那走吧！趁還不太晚。",
  ui_story_5040_50400702_77_dialog_content = "我……想去……",
  ui_story_5040_50400702_78_dialog_content = "小凱雅，有些事情我想單獨問問妳，方便嗎？",
  ui_story_5040_50400702_79_dialog_content = "欸？耶利亞長老怎麼突然……當然可以。",
  ui_story_5040_50400702_80_dialog_content = "不過小黑……",
  ui_story_5040_50400702_81_dialog_content = "PlayerName在呢，讓他們一起回去就好。",
  ui_story_5040_50400702_82_dialog_content = "還是說，黑色的小鳥有什麼不可見人的祕密，怕被發現嗎？",
  ui_story_5040_50400702_83_dialog_content = "當然沒有！",
  ui_story_5040_50400702_84_dialog_content = "那辛苦PlayerName了，麻煩帶小黑一起回去吧。",
  ui_story_5040_50400702_85_dialog_content = "小事，沒問題。",
  ui_story_5040_50400702_86_dialog_content = "那個……",
  ui_story_5040_50400702_87_dialog_content = "怎麼了嗎？",
  ui_story_5040_50400702_88_dialog_content = "想……繞路……",
  ui_story_5040_50400702_89_dialog_content = "繞路？",
  ui_story_5040_50400702_90_dialog_content = "妳還有什麼想去的地方是嗎？",
  ui_story_5040_50400702_91_dialog_content = "我、之前……撿到……一封信……",
  ui_story_5040_50400702_92_dialog_content = "想……還給……失主。",
  ui_story_5040_50400702_93_dialog_content = "信？在哪裡撿到的，不是應該還給信使公會嗎？",
  ui_story_5040_50400702_94_dialog_content = "在……和他……訓練、之後。",
  ui_story_5040_50400702_95_dialog_content = "啊，那應該是在城外？可能是信使送信時不小心掉的吧。",
  ui_story_5040_50400702_96_dialog_content = "不直接給信使公會，沒問題嗎？",
  ui_story_5040_50400702_97_dialog_content = "有、地址……上面。",
  ui_story_5040_50400702_98_dialog_content = "不然……對方……會、等很久。",
  ui_story_5040_50400702_99_dialog_content = "也是，畢竟快到冠月節了。妳是想讓對方能快點收到吧。",
  ui_story_5040_50400702_100_dialog_content = "多孚要是有妳一半的責任心就好了。",
  ui_story_5040_50400702_101_dialog_content = "走吧，我陪妳去，看看這個上面寫的地址是哪裡。",
  ui_story_5040_50400702_102_dialog_content = "（不過這信看起來紙已經發黃了，感覺不像最近寄出的。）",
  ui_story_5040_50400702_103_dialog_content = "<color=#e8d9bb>咚咚咚——</color>",
  ui_story_5040_50400702_104_dialog_content = "應該……是……這裡。",
  ui_story_5040_50400702_105_dialog_content = "嗯，地址是沒錯。",
  ui_story_5040_50400702_106_dialog_content = "請問你們是？",
  ui_story_5040_50400702_107_dialog_content = "打擾了，我們在路上見到一封信，上面寫的是這個地址。",
  ui_story_5040_50400702_108_dialog_content = "欸？我們家的嗎？我看看。",
  ui_story_5040_50400702_109_dialog_content = "這、這是……！",
  ui_story_5040_50400702_110_dialog_content = "是這裡沒錯吧？",
  ui_story_5040_50400702_111_dialog_content = "兩位從哪裡找到這封信的？！",
  ui_story_5040_50400702_112_dialog_content = "是我這位朋友撿到的，在城外。",
  ui_story_5040_50400702_113_dialog_content = "幫、上……忙了嗎？",
  ui_story_5040_50400702_114_dialog_content = "我……我不知道該怎麼說。",
  ui_story_5040_50400702_115_dialog_content = "這是給我祖母的信。",
  ui_story_5040_50400702_116_dialog_content = "給祖母的？",
  ui_story_5040_50400702_117_dialog_content = "祖母去世前一直掛念著這封信，但到她去世時也沒有收到。",
  ui_story_5040_50400702_118_dialog_content = "是她的初戀，聽說他們隔著啟光到白夜城的距離，最後也沒能在一起。",
  ui_story_5040_50400702_119_dialog_content = "我祖父很早就去世了，祖母和她的初戀在很多年後又聯繫上了彼此。",
  ui_story_5040_50400702_120_dialog_content = "並以摯友的身分維持著書信聯繫。他們約定好了，只要信還在，人就還在。",
  ui_story_5040_50400702_121_dialog_content = "有一天，他不再來信了，祖母很快也病倒了。",
  ui_story_5040_50400702_122_dialog_content = "沒想到……",
  ui_story_5040_50400702_123_dialog_content = "唉，真是造化弄人。",
  ui_story_5040_50400702_124_dialog_content = "竟然還有這樣的故事。",
  ui_story_5040_50400702_125_dialog_content = "小黑，妳還真是不知不覺中做了個大好事。",
  ui_story_5040_50400702_126_dialog_content = "真的很感謝！這封信我不拆，就直接放在祖母的墓碑旁，與她作伴吧。",
  ui_story_5040_50400702_127_dialog_content = "……",
  ui_story_5040_50400702_128_dialog_content = "這也是冠月節的旨意吧，謝天謝地，希望他要說的話還能傳遞過去。",
  ui_story_5040_50400702_129_dialog_content = "愛……嗎。",
  ui_story_5040_50400702_130_dialog_content = "是啊，有時候我也不明白，愛到底有多大的魔力。",
  ui_story_5040_50400702_131_dialog_content = "能救人，也能害人。",
  ui_story_5040_50400702_132_dialog_content = "總之，今天不知該怎麼感謝兩位了。",
  ui_story_5040_50400702_133_dialog_content = "不用客氣，要謝就謝這位。",
  ui_story_5040_50400702_134_dialog_content = "不用……",
  ui_story_5040_50400702_135_dialog_content = "那如果沒什麼事，我們也早點回去吧。",
  ui_story_5040_50400702_136_dialog_content = "嗯……",
  ui_story_5040_50400702_137_dialog_content = "<color=#e8d9bb>與此同時，另一側——</color>",
  ui_story_5040_50400702_138_dialog_content = "耶利亞長老，找我有什麼事嗎？",
  ui_story_5040_50400702_139_dialog_content = "……",
  ui_story_5040_50400702_140_dialog_content = "北境的小鳥，我很好奇，妳這位親戚是從哪裡來的呢？",
  ui_story_5040_50400702_141_dialog_content = "！！",
  ui_story_5040_50400702_142_dialog_content = "是說……小黑嗎？",
  ui_story_5040_50400702_143_dialog_content = "還會有其他人嗎？",
  ui_story_5040_50400702_144_dialog_content = "這……",
  ui_story_5040_50400702_145_dialog_content = "（好強的壓迫感！）",
  ui_story_5040_50400702_146_dialog_content = "我這人認為拐彎抹角很無趣，所以不妨趁這個機會問問妳。",
  ui_story_5040_50400702_147_dialog_content = "她不是光靈吧？",
  ui_story_5040_50400702_148_dialog_content = "……！",
  ui_story_5040_50400702_149_dialog_content = "說得更直白點，應該是會說通用語的暗鬼。",
  ui_story_5040_50400702_150_dialog_content = "耶利亞長老……",
  ui_story_5040_50400702_151_dialog_content = "嗯～～小凱雅雖然做信使沒多久，想不到膽子比我想像中的要大啊。",
  ui_story_5040_50400702_152_dialog_content = "還真是小看妳了。",
  ui_story_5040_50400702_153_dialog_content = "耶利亞長老！我知道這麼做毫無理由，但是……求您先不要說出去。",
  ui_story_5040_50400702_154_dialog_content = "我有什麼要替妳保密的理由嗎？為什麼要做這個人情呢？",
  ui_story_5040_50400702_155_dialog_content = "沒有，您沒有幫我的理由。我也沒有資格讓您幫我。",
  ui_story_5040_50400702_156_dialog_content = "我只是在懇求您。",
  ui_story_5040_50400702_157_dialog_content = "……",
  ui_story_5040_50400702_158_dialog_content = "她也失去了記憶，求我幫她。",
  ui_story_5040_50400702_159_dialog_content = "幫她對我沒有好處，甚至很危險。光靈暗鬼的關係一向殘酷，這我自己也知道。",
  ui_story_5040_50400702_160_dialog_content = "我因為想幫人們傳遞心意而選擇成為信使，就是這麼簡單的理由，對她也一樣。",
  ui_story_5040_50400702_161_dialog_content = "因為看到她的無助而不假思索的答應幫助她，是我天真、衝動之下的選擇。",
  ui_story_5040_50400702_162_dialog_content = "我順應自己的心意做了這件事，當然也會為此承擔責任，甚至是……付出代價。",
  ui_story_5040_50400702_163_dialog_content = "如果說，我要傷害她，妳也會擋在她身前嗎？",
  ui_story_5040_50400702_164_dialog_content = "我會的，耶利亞長老。",
  ui_story_5040_50400702_165_dialog_content = "凱雅是信使，做事一向有始有終。我會妥善處理這件事的。",
  ui_story_5040_50400702_166_dialog_content = "……",
  ui_story_5040_50400702_167_dialog_content = "妳比我想像中的還要有意思，雖然覺得有些幼稚，但我不討厭認真的人。",
  ui_story_5040_50400702_168_dialog_content = "那我就靜觀其變吧，祝妳好運。",
  ui_story_5040_50400702_169_dialog_content = "這意思是……要幫我嗎？",
  ui_story_5040_50400702_170_dialog_content = "謝謝妳！耶利亞長老。",
  ui_story_5040_50400702_171_dialog_content = "無論怎樣，我一定會負責到底的。請放心吧！",
  ui_story_5040_50400801_1_dialog_content = "小黑，托妳的福，在迦南城做了件好事。我們也快回去休息吧。",
  ui_story_5040_50400801_2_dialog_content = "好……",
  ui_story_5040_50400801_3_dialog_content = "妳沒事吧？感覺這一路妳的臉色都不太好。",
  ui_story_5040_50400801_4_dialog_content = "臉……色？",
  ui_story_5040_50400801_5_dialog_content = "是啊，這麼說不太好，可是總覺得妳臉色有點發黑？",
  ui_story_5040_50400801_6_dialog_content = "是不是缺乏營養？還是身體出了什麼問題？",
  ui_story_5040_50400801_7_dialog_content = "我想……應該……不……",
  ui_story_5040_50400801_8_dialog_content = "嘎——！",
  ui_story_5040_50400801_9_dialog_content = "嘎嗷！！",
  ui_story_5040_50400801_10_dialog_content = "什麼！暗鬼？！",
  ui_story_5040_50400801_11_dialog_content = "我還是第一次在迦南城裡遇到暗鬼啊！",
  ui_story_5040_50400801_12_dialog_content = "呀啊啊！！救命！",
  ui_story_5040_50400801_13_dialog_content = "啊！抓、抓住……我！",
  ui_story_5040_50400801_14_dialog_content = "別、別怕……",
  ui_story_5040_50400801_15_dialog_content = "小黑妳帶著孩子退後，小心！",
  ui_story_5040_50400802_1_dialog_content = "小黑，你們沒事吧！",
  ui_story_5040_50400802_2_dialog_content = "沒、沒事……",
  ui_story_5040_50400802_3_dialog_content = "哇啊啊啊！妳、妳長得好恐怖！",
  ui_story_5040_50400802_4_dialog_content = "我……",
  ui_story_5040_50400802_5_dialog_content = "童言無忌，妳別太在意。",
  ui_story_5040_50400802_6_dialog_content = "只是迦南城裡怎麼會出現暗鬼呢？",
  ui_story_5040_50400802_7_dialog_content = "呼，各位，幫大忙了！",
  ui_story_5040_50400802_8_dialog_content = "尤拉？",
  ui_story_5040_50400802_9_dialog_content = "這是彌加德用來做實驗的暗鬼，不知怎麼回事突然發狂跑出來了。",
  ui_story_5040_50400802_10_dialog_content = "沒造成傷亡真是太好了，多謝兩位。",
  ui_story_5040_50400802_11_dialog_content = "實驗用的暗鬼？是之前用來測試我們的那種嗎？",
  ui_story_5040_50400802_12_dialog_content = "正是，彌加德抓了許多種類的暗鬼，雖然做什麼實驗我並不清楚，不過……",
  ui_story_5040_50400802_13_dialog_content = "感覺抓來的暗鬼們，消耗速度很快呢。",
  ui_story_5040_50400802_14_dialog_content = "！！！",
  ui_story_5040_50400802_15_dialog_content = "實驗用的要小心一點啊！跑到大街上傷了人怎麼辦？",
  ui_story_5040_50400802_16_dialog_content = "嗯，以前沒有發生過這種情況，說不定你們身上有什麼特殊的吸引力喔。",
  ui_story_5040_50400802_17_dialog_content = "說起來，小黑，妳要不要讓彌加德幫忙看看？研究室的藥物很齊全的。",
  ui_story_5040_50400802_18_dialog_content = "妳身體不舒服的話，也可以讓她給妳找些藥。",
  ui_story_5040_50400802_19_dialog_content = "不……不用！！",
  ui_story_5040_50400802_20_dialog_content = "突然……想起……有、有事！",
  ui_story_5040_50400802_21_dialog_content = "我……先去……找凱雅了！",
  ui_story_5040_50400802_22_dialog_content = "欸？！",
  ui_story_5040_50400802_23_dialog_content = "呵呵，你這位朋友感覺很奇妙呢。",
  ui_story_5040_50400802_24_dialog_content = "（天色不早了，小黑他們應該已經回去了，我也準備回去吧。）",
  ui_story_5040_50400802_25_dialog_content = "凱……雅！！！",
  ui_story_5040_50400802_26_dialog_content = "小黑？妳怎麼到這裡來了？不是和PlayerName一起回去了嗎？",
  ui_story_5040_50400802_27_dialog_content = "想……和……凱雅……一起。",
  ui_story_5040_50400802_28_dialog_content = "這樣啊，那我們一起走吧。",
  ui_story_5040_50400802_29_dialog_content = "<color=#e8d9bb>咕嚕——</color>",
  ui_story_5040_50400802_30_dialog_content = "有……什麼……聲音。",
  ui_story_5040_50400802_31_dialog_content = "啊，我的肚子叫了。抱歉抱歉。",
  ui_story_5040_50400802_32_dialog_content = "一直沒有吃東西，有點餓了。",
  ui_story_5040_50400802_33_dialog_content = "我……也……餓。",
  ui_story_5040_50400802_34_dialog_content = "妳也餓了？我們先找地方吃點東西再回去，好嗎？",
  ui_story_5040_50400802_35_dialog_content = "不……長得……不能見人……",
  ui_story_5040_50400802_36_dialog_content = "小黑？",
  ui_story_5040_50400802_37_dialog_content = "別這麼說，小黑只是長得和普通光靈不太像，但小黑心地很善良的！",
  ui_story_5040_50400802_38_dialog_content = "那我去買兩個麵包，我們回去吃，好不好？",
  ui_story_5040_50400802_39_dialog_content = "好……",
  ui_story_5040_50400802_40_dialog_content = "說起來，小黑對啟光是不是沒有什麼其他印象？",
  ui_story_5040_50400802_41_dialog_content = "沒……",
  ui_story_5040_50400802_42_dialog_content = "沒事，妳不是想起沙漠了嗎？我們下一站去紅油沙漠再看看。",
  ui_story_5040_50400802_43_dialog_content = "別擔心。",
  ui_story_5040_50400802_44_dialog_content = "謝謝……",
  ui_story_5040_50400802_45_dialog_content = "對了！我剛才看到車站對面有個人商人在賣手工橘子麵包，你就在這裡等我吧。",
  ui_story_5040_50400802_46_dialog_content = "我很快就回來，妳不要亂跑哦。",
  ui_story_5040_50400802_47_dialog_content = "……！",
  ui_story_5040_50400802_48_dialog_content = "這……個……語氣……",
  ui_story_5040_50400802_49_dialog_content = "我很快就回來，妳乖乖在這裡等我喔。",
  ui_story_5040_50400802_50_dialog_content = "不要亂跑，我買完就來找妳。",
  ui_story_5040_50400802_51_dialog_content = "好久啊，愛德華，怎麼還不回來呢。",
  ui_story_5040_50400802_52_dialog_content = "為什麼……不來找我？",
  ui_story_5040_50400802_53_dialog_content = "為什麼不回來？我哪裡不夠好嗎？",
  ui_story_5040_50400802_54_dialog_content = "<size=45>回來啊！！</size>",
  ui_story_5040_50400802_55_dialog_content = "絕望嗎？離鄉背井無依無靠？接受這個種子吧，它會讓妳不再畏懼任何事。",
  ui_story_5040_50400802_56_dialog_content = "不會再有弱小者的痛苦，妳會變得比自己想像中更強大。",
  ui_story_5040_50400802_57_dialog_content = "啊啊啊啊！！！",
  ui_story_5040_50400802_58_dialog_content = "真幸運，因為是冠月節還買到了肉桂卷，小黑肯定會喜歡的。",
  ui_story_5040_50400802_59_dialog_content = "小黑，小……",
  ui_story_5040_50400802_60_dialog_content = "呀啊啊！姐姐，有暗鬼！",
  ui_story_5040_50400802_61_dialog_content = "有暗鬼倒在城裡了！",
  ui_story_5040_50400802_62_dialog_content = "等等，這是暗鬼？還是別的什麼東西？",
  ui_story_5040_50400802_63_dialog_content = "要不要叫軍團的人來看看？",
  ui_story_5040_50400802_64_dialog_content = "！！！",
  ui_story_5040_50400802_65_dialog_content = "讓一讓！",
  ui_story_5040_50400802_66_dialog_content = "小黑！小黑！妳怎麼了！",
  ui_story_5040_50400802_67_dialog_content = "啊……",
  ui_story_5040_50400802_68_dialog_content = "小黑，快，我們走！",
  ui_story_5040_50400802_69_dialog_content = "喂，妳等一等！妳們是什麼人？！",
  ui_story_5040_50400802_70_dialog_content = "呼……呼……",
  ui_story_5040_50400802_71_dialog_content = "別出聲！",
  ui_story_5040_50400802_72_dialog_content = "……唔。",
  ui_story_5040_50400802_73_dialog_content = "要是被他們發現就糟糕了！",
  ui_story_5040_50400802_74_dialog_content = "您有沒有在附近看見長相奇怪的暗鬼？還跟著一個小姑娘。",
  ui_story_5040_50400802_75_dialog_content = "這可不是小事啊。我看到他們好像往地上逃跑了。要不要叫士兵追上去看看？",
  ui_story_5040_50400802_76_dialog_content = "什麼？竟然跑這麼快？我們走！",
  ui_story_5040_50400802_77_dialog_content = "耶利亞長老……謝謝。",
  ui_story_5040_50400802_78_dialog_content = "他們好像離開了。小黑，妳有沒有受傷？！我看看。",
  ui_story_5040_50400802_79_dialog_content = "沒……事。",
  ui_story_5040_50400802_80_dialog_content = "對……不起……讓妳……擔心……",
  ui_story_5040_50400802_81_dialog_content = "說什麼呢，萬一妳受傷了，我會很後悔丟下妳一個人去買東西的。",
  ui_story_5040_50400802_82_dialog_content = "……凱雅。",
  ui_story_5040_50400802_83_dialog_content = "我……想起來了。",
  ui_story_5040_50400802_84_dialog_content = "想起來？想起什麼了？",
  ui_story_5040_50400802_85_dialog_content = "有人……和妳……說過……一樣的話……",
  ui_story_5040_50400802_86_dialog_content = "但是他……再也沒……回來。",
  ui_story_5040_50400802_87_dialog_content = "我去很遠的……地方……去找他。",
  ui_story_5040_50400802_88_dialog_content = "他……曾經、說……喜歡我。",
  ui_story_5040_50400802_89_dialog_content = "但是……最後……丟下我。",
  ui_story_5040_50400802_90_dialog_content = "我……離開家……很害怕、無助。",
  ui_story_5040_50400802_91_dialog_content = "那個人……給我……種子。",
  ui_story_5040_50400802_92_dialog_content = "說……可以……變得強大。",
  ui_story_5040_50400802_93_dialog_content = "妳果然是光靈！",
  ui_story_5040_50400802_94_dialog_content = "怎麼會遇到這種事？！",
  ui_story_5040_50400802_95_dialog_content = "那個……魔藥……讓我……恢復……意識。",
  ui_story_5040_50400802_96_dialog_content = "我……什麼都……忘了、什麼都……不相信。",
  ui_story_5040_50400802_97_dialog_content = "只想……回家。",
  ui_story_5040_50400802_98_dialog_content = "小黑……",
  ui_story_5040_50400802_99_dialog_content = "我一定會帶妳回家的，我保證。",
  ui_story_5040_50400802_100_dialog_content = "我們明天就啟程去紅油沙漠，那裡說不定就是妳的家。",
  ui_story_5040_50400802_101_dialog_content = "謝謝……凱雅。",
  ui_story_5040_50400802_102_dialog_content = "我……最近……感覺……意識、模糊。",
  ui_story_5040_50400802_103_dialog_content = "可能……意識……維持、不了……太久。",
  ui_story_5040_50400802_104_dialog_content = "如果……失去……意識、妳就……",
  ui_story_5040_50400802_105_dialog_content = "別說了！在這之前一定帶妳回家，說不定我們還有其他維持意識的方法！",
  ui_story_5040_50400802_106_dialog_content = "不是還有沙蟲嗎？我們一定還有別的辦法。",
  ui_story_5040_50400802_107_dialog_content = "凱雅……",
  ui_story_5040_50400802_108_dialog_content = "我們明天就出發，一刻也不耽誤！",
  ui_story_5040_50400802_109_dialog_content = "妳一定能回家的。",
  ui_story_5040_50400901_1_dialog_content = "我們到了，隨便坐吧。",
  ui_story_5040_50400901_2_dialog_content = "這裡就是信使公會紅油扳手分部嗎？",
  ui_story_5040_50400901_3_dialog_content = "雖然外牆還是破破爛爛的樣子，但是裡面卻這麼華麗，和想像中的完全不一樣。",
  ui_story_5040_50400901_X3_dialog_content = "是啊，更別提位置還這麼難找！",
  ui_story_5040_50400901_X4_dialog_content = "紅油扳手營地裡的建築本來就蓋得夠任性了，路也不好找……",
  ui_story_5040_50400901_X5_dialog_content = "這個地方竟然要在那些小巷裡走上十多分鐘才能到達！",
  ui_story_5040_50400901_X6_dialog_content = "我第一次來的時候迷路了好久才找到。",
  ui_story_5040_50400901_X7_dialog_content = "那說明你的方向感還不錯！",
  ui_story_5040_50400901_X8_dialog_content = "我第一次來的時候因為太久沒找到，差點就放棄了呢。",
  ui_story_5040_50400901_4_dialog_content = "不過這些裝飾就算是第二次看，還是會覺得出人預料。",
  ui_story_5040_50400901_5_dialog_content = "不僅裝飾得很華麗，裡面堆滿了精緻的裝飾品，我的眼睛都要被晃花了。",
  ui_story_5040_50400901_6_dialog_content = "完全不像是紅油扳手的風格！",
  ui_story_5040_50400901_7_dialog_content = "難道你覺得，我像是什麼粗俗的遊匪嗎？",
  ui_story_5040_50400901_8_dialog_content = "不，我不是那個意思……",
  ui_story_5040_50400901_9_dialog_content = "好了，還是不逗你們玩了～",
  ui_story_5040_50400901_10_dialog_content = "耶利亞長老，我想帶小黑在這裡看看——",
  ui_story_5040_50400901_11_dialog_content = "沒問題，想看哪裡都沒問題～",
  ui_story_5040_50400901_12_dialog_content = "欸？",
  ui_story_5040_50400901_13_dialog_content = "但是，看完以後要記得把一切歸位。",
  ui_story_5040_50400901_14_dialog_content = "嗯！我知道了！",
  ui_story_5040_50400901_15_dialog_content = "小黑，我們走吧！",
  ui_story_5040_50400901_16_dialog_content = "我也要去準備車子和武器了。",
  ui_story_5040_50400901_17_dialog_content = "再過一會就要到晚上了，今晚你們就先在這裡休息吧。",
  ui_story_5040_50400901_18_dialog_content = "準備車子？用巨像趕路不是更快嗎？",
  ui_story_5040_50400901_X18_dialog_content = "而且巨像這麼大，看起來比車子安全多了……",
  ui_story_5040_50400901_19_dialog_content = "沙蟲是一種在地表和地底活動的生物。",
  ui_story_5040_50400901_20_dialog_content = "牠們很狡猾，能夠憑藉地底的洞穴快速移動和躲藏。",
  ui_story_5040_50400901_21_dialog_content = "如果不在第一時間纏住牠們，牠們就會迅速逃跑。",
  ui_story_5040_50400901_X21_dialog_content = "咦？！",
  ui_story_5040_50400901_X22_dialog_content = "耶利亞說的沒錯。",
  ui_story_5040_50400901_22_dialog_content = "巨像雖然又快又穩，但搭乘巨像就沒辦法在發現沙蟲的第一時間展開攻擊。",
  ui_story_5040_50400901_X23_dialog_content = "我就差點因此吃過虧呢！",
  ui_story_5040_50400901_23_dialog_content = "原來如此……",
  ui_story_5040_50400901_24_dialog_content = "關於這片沙漠，你還有很多要學的呢。",
  ui_story_5040_50400901_25_dialog_content = "我先走了。明天一早，我們就出發去找沙蟲。",
  ui_story_5040_50400901_26_dialog_content = "<color=#e8d9bb>咕嚕——</color>",
  ui_story_5040_50400901_27_dialog_content = "呃！",
  ui_story_5040_50400901_28_dialog_content = "奔波了一天，都沒怎麼顧得上吃飯。",
  ui_story_5040_50400901_29_dialog_content = "<color=#e8d9bb>咕嚕嚕——</color>",
  ui_story_5040_50400901_30_dialog_content = "我也有點餓了。",
  ui_story_5040_50400901_31_dialog_content = "既然到了紅油沙漠，就讓我來給你們準備一份紅油扳手風格的大餐吧！",
  ui_story_5040_50400901_32_dialog_content = "我去外面升起篝火，給你們做些燒烤吃。",
  ui_story_5040_50400901_33_dialog_content = "我也一起幫忙！",
  ui_story_5040_50400901_34_dialog_content = "就剩我一個了。",
  ui_story_5040_50400901_35_dialog_content = "我還是別去打擾塔拉和亞度尼斯他們了，凱雅和小黑似乎也不需要我幫忙。",
  ui_story_5040_50400901_36_dialog_content = "話說回來，沙蟲的體型應該非常巨大才對吧！只靠我們這麼點人，真的沒問題嗎？",
  ui_story_5040_50400901_37_dialog_content = "雖然耶利亞看起來非常強，塔拉也很能打，但還是讓人擔心……",
  ui_story_5040_50400901_38_dialog_content = "稍微去問一下耶利亞，看看要不要找些幫手來吧。",
  ui_story_5040_50400901_39_dialog_content = "哦？你是因為擔心，所以才來的嗎，空裔小哥？",
  ui_story_5040_50400901_40_dialog_content = "請、請別用那種稱呼叫我。",
  ui_story_5040_50400901_41_dialog_content = "放心吧，這片沙漠對我而言就像是自家的花園。",
  ui_story_5040_50400901_42_dialog_content = "我已經檢查好了車的狀態，也準備了足夠的補給，你們只需要照顧好自己就可以了。",
  ui_story_5040_50400901_43_dialog_content = "可沙蟲是一種很危險的生物，我還是擔心，以我們的人手，沒辦法對付它。",
  ui_story_5040_50400901_44_dialog_content = "要不要多找些人來幫忙，比如醒山和青瞳他們？",
  ui_story_5040_50400901_45_dialog_content = "不需要。",
  ui_story_5040_50400901_46_dialog_content = "但是——",
  ui_story_5040_50400901_47_dialog_content = "我不需要任何人幫忙。",
  ui_story_5040_50400901_48_dialog_content = "只有我一個人就足夠了，敵人不過是一隻沙蟲，三兩下就能解決。",
  ui_story_5040_50400901_49_dialog_content = "如果你沒別的事，就請回吧。",
  ui_story_5040_50400901_50_dialog_content = "我還有別的事情要忙，也不需要來自小朋友的關心。",
  ui_story_5040_50400901_51_dialog_content = "……",
  ui_story_5040_50400901_52_dialog_content = "好吧。",
  ui_story_5040_50400901_S52_dialog_content = "我還是回臨空者號上吧。",
  ui_story_5040_50400901_53_dialog_content = "哎……竟然就這麼被耶利亞趕走了。",
  ui_story_5040_50400901_54_dialog_content = "算了，既然她不想讓我管，我就不管她！",
  ui_story_5040_50400901_55_dialog_content = "……",
  ui_story_5040_50400901_X55_dialog_content = "（這一路，耶利亞似乎都是一副事不關己看樂子的樣子。）",
  ui_story_5040_50400901_X56_dialog_content = "（就算她是信使公會的長老，我也還是沒辦法信任她。）",
  ui_story_5040_50400901_X57_dialog_content = "（為了保險起見，還是發送終端訊息給紅油扳手的大家試試吧。）",
  ui_story_5040_50400901_X58_dialog_content = "（希望有人在附近，能夠做出回應……）",
  ui_story_5040_50400901_56_dialog_content = "<color=#e8d9bb>滴——</color>",
  ui_story_5040_50400901_57_dialog_content = "這裡是歐緹，PlayerName，收到請回覆。",
  ui_story_5040_50400901_58_dialog_content = "歐緹！是妳！",
  ui_story_5040_50400901_59_dialog_content = "PlayerName收到！太好了，沒想到真的有人回應！",
  ui_story_5040_50400901_60_dialog_content = "有什麼事嗎？",
  ui_story_5040_50400901_61_dialog_content = "歐緹，妳知道關於一隻粉色沙蟲的情報嗎？",
  ui_story_5040_50400901_62_dialog_content = "粉色的……沙蟲？唔，好像有點耳熟。",
  ui_story_5040_50400901_63_dialog_content = "我想起來了，大概一個月前，醒山老大好像遇到過一隻粉色的沙蟲。",
  ui_story_5040_50400901_64_dialog_content = "誰都沒見過那種顏色的沙蟲，所以他們決定狩獵那傢伙，結果讓牠給跑了。",
  ui_story_5040_50400901_65_dialog_content = "具體情況我也不是很清楚，我把老大叫過來，你直接問他吧。",
  ui_story_5040_50400901_66_dialog_content = "好，那就麻煩妳了！",
  ui_story_5040_50400901_67_dialog_content = "唷，PlayerName，是你啊。",
  ui_story_5040_50400901_68_dialog_content = "我聽歐緹說，你在打聽一隻粉色的沙蟲？",
  ui_story_5040_50400901_69_dialog_content = "沒錯！你知道什麼嗎？",
  ui_story_5040_50400901_70_dialog_content = "這我可太知道了，那傢伙是為數不多能從我手底下活著逃走的沙蟲。",
  ui_story_5040_50400901_71_dialog_content = "一個月前我還想狩獵牠來著，結果只打下來一枚鱗片，就讓牠給跑了。",
  ui_story_5040_50400901_72_dialog_content = "嘶——還真可惜，光是那一枚鱗片就賣了個大價錢，要是能獵到一整隻，可就賺翻了。",
  ui_story_5040_50400901_73_dialog_content = "畢竟誰都沒見過粉色的沙蟲，說不定這世界上僅此一隻，物以稀為貴嘛！",
  ui_story_5040_50400901_74_dialog_content = "不過，你怎麼也在找粉色的沙蟲？難道你和耶利亞在一起？",
  ui_story_5040_50400901_75_dialog_content = "你怎麼知道？！",
  ui_story_5040_50400901_76_dialog_content = "因為耶利亞的言靈在紅油沙漠的幾個沙蟲棲息地之間到處亂飛！",
  ui_story_5040_50400901_77_dialog_content = "這個時候在找沙蟲，也只可能是在找那隻粉色的大傢伙了。",
  ui_story_5040_50400901_78_dialog_content = "那麼高強度地使用光能術，簡直就是在亂來。",
  ui_story_5040_50400901_79_dialog_content = "那你知道那隻粉色的沙蟲在哪裡嗎？",
  ui_story_5040_50400901_80_dialog_content = "當然知道了，不過我可不會免費給你情報，小子，你打算用什麼換？",
  ui_story_5040_50400901_81_dialog_content = "這個……我……",
  ui_story_5040_50400901_82_dialog_content = "哈哈哈，瞧你那嚇得瑟瑟發抖的樣子，怎麼，擔心我宰你不成？",
  ui_story_5040_50400901_83_dialog_content = "下次來紅油扳手的時候，記得給伊芙帶點巧克力過來吧。",
  ui_story_5040_50400901_84_dialog_content = "她聽說影鎮為了冠那個什麼節，新推出了一款限時售賣的巧克力，一直想要。",
  ui_story_5040_50400901_85_dialog_content = "正好你能坐著巨像到處跑，就幫她帶一份那個巧克力過來吧。",
  ui_story_5040_50400901_86_dialog_content = "當然沒問題！",
  ui_story_5040_50400901_87_dialog_content = "那就說定了。",
  ui_story_5040_50400901_88_dialog_content = "之前我和那傢伙打架的時候，發現那傢伙很狡猾，到處躲藏。",
  ui_story_5040_50400901_89_dialog_content = "不過，牠逃跑之前狠狠挨了我一扳手，左側身上的鱗片都碎了。",
  ui_story_5040_50400901_90_dialog_content = "我之前追了牠好幾天，結果跟丟了，最後一次看見牠是在沙漠深處靠近綠洲的那片區域。",
  ui_story_5040_50400901_91_dialog_content = "不過具體在哪裡，我就不知道了。",
  ui_story_5040_50400901_92_dialog_content = "你們要是想對付牠的話，可以到那附近找找。",
  ui_story_5040_50400901_93_dialog_content = "我知道了！謝謝你，醒山。",
  ui_story_5040_50400901_94_dialog_content = "有耶利亞在，對付那傢伙應該不是難事。不過要小心，牠相當狡猾。",
  ui_story_5040_50400901_95_dialog_content = "你怎麼那麼確定，難道你跟耶利亞很熟嗎？",
  ui_story_5040_50400901_96_dialog_content = "不熟，那傢伙總是獨來獨往的，從來不和別人多說半句話。",
  ui_story_5040_50400901_97_dialog_content = "但是，能在紅油沙漠一個人生活這件事，本來就是實力的證明。",
  ui_story_5040_50400901_98_dialog_content = "更何況，她可是沙漠裡為數不多的信使，我們平時受到了不少照顧。",
  ui_story_5040_50400901_99_dialog_content = "你就放心大膽地跟著她吧，準沒錯！",
  ui_story_5040_50400901_100_dialog_content = "是這樣嗎……",
  ui_story_5040_50400901_101_dialog_content = "我知道了！",
  ui_story_5040_50400901_102_dialog_content = "就聊到這裡吧，不然伊芙又要說我不好好休息了。",
  ui_story_5040_50400901_103_dialog_content = "嗯，回頭見！",
  ui_story_5040_50400901_104_dialog_content = "現在還是不要去找耶利亞比較好，先把這些消息告訴塔拉和亞度尼斯他們吧。",
  ui_story_5040_50400901_105_dialog_content = "正好我也餓了，去看看今天吃什麼吧！",
  ui_story_5040_50400901_106_dialog_content = "<color=#e8d9bb>與此同時，信使公會紅油扳手分部中</color>",
  ui_story_5040_50400901_107_dialog_content = "積壓的全部信件應該都在這裡了。",
  ui_story_5040_50400901_108_dialog_content = "紅油沙漠那麼寬廣，紅油扳手又都是一群到處亂跑的傢伙，所以無主的信件也很多。",
  ui_story_5040_50400901_109_dialog_content = "大概又要花很久才能找到想要的東西了。",
  ui_story_5040_50400901_110_dialog_content = "小黑，會，幫忙。",
  ui_story_5040_50400901_111_dialog_content = "我們一起努力吧！先打開看看，具體有多少信件。",
  ui_story_5040_50400901_112_dialog_content = "信，好多！",
  ui_story_5040_50400901_113_dialog_content = "等等，這些信上面，好像還貼了小標籤。",
  ui_story_5040_50400901_114_dialog_content = "「失蹤人員信件」、「收件人不明的信件」、「拒收信件」……",
  ui_story_5040_50400901_115_dialog_content = "竟然每一種都分開了不同類別放好了？！",
  ui_story_5040_50400901_116_dialog_content = "凱雅，看，那個。",
  ui_story_5040_50400901_117_dialog_content = "這個標籤是「同種郵票」？！",
  ui_story_5040_50400901_118_dialog_content = "下面還標注了一行小字，「懷疑寄件人是同一人」。",
  ui_story_5040_50400901_119_dialog_content = "這上面的郵票，和小黑你的郵票一樣。",
  ui_story_5040_50400901_120_dialog_content = "這些，是，我的……",
  ui_story_5040_50400901_121_dialog_content = "竟然這麼快就找到目標，真是太好了。",
  ui_story_5040_50400901_122_dialog_content = "讓我們來看看這些信件吧。",
  ui_story_5040_50400901_123_dialog_content = "好。",
  ui_story_5040_50400901_124_dialog_content = "「謝謝你願意與我通信，認識你很高興。」",
  ui_story_5040_50400901_125_dialog_content = "「沙漠是炎熱的地方，大家都住得很遠，需要依靠信使才能通信。」",
  ui_story_5040_50400901_126_dialog_content = "「如果能與你同行，我也願意走出沙漠。」",
  ui_story_5040_50400901_127_dialog_content = "這些信看起來像是妳和那傢伙最初認識的時候寫的。",
  ui_story_5040_50400901_128_dialog_content = "每一封的收件地址都不太一樣，也沒有寫寄件人的位置。",
  ui_story_5040_50400901_129_dialog_content = "難道妳的家在沙漠裡嗎？",
  ui_story_5040_50400901_130_dialog_content = "唔……",
  ui_story_5040_50400901_131_dialog_content = "呃！！！",
  ui_story_5040_50400901_132_dialog_content = "小黑？！",
  ui_story_5040_50400901_133_dialog_content = "我……想起來……",
  ui_story_5040_50400901_134_dialog_content = "我的家，沙漠，深處……",
  ui_story_5040_50400901_135_dialog_content = "但是，在哪裡，不記得……",
  ui_story_5040_50400901_136_dialog_content = "沒關係，這已經是很有用的線索了，之後只要問問沙漠裡的居民就好了！",
  ui_story_5040_50400901_137_dialog_content = "妳還是不要勉強自己去想了，先好好休息。",
  ui_story_5040_50400901_138_dialog_content = "既然接受了妳的委託，作為信使的我，就一定會負起這份責任。",
  ui_story_5040_50400901_139_dialog_content = "嗯……",
  ui_story_5040_50400901_140_dialog_content = "小黑，妳怎麼了？看起來沒什麼精神的樣子。",
  ui_story_5040_50400901_141_dialog_content = "塔拉，亞度尼斯……他們，感情很好……",
  ui_story_5040_50400901_142_dialog_content = "互相、珍惜、互相、幫助……",
  ui_story_5040_50400901_143_dialog_content = "我，羡慕……",
  ui_story_5040_50400901_144_dialog_content = "（小黑她，之前沒有被自己愛的人善待過，愛也沒有得到回應。）",
  ui_story_5040_50400901_145_dialog_content = "（現在看到那兩個人的那麼幸福，她的心裡一定很不好受吧……）",
  ui_story_5040_50400901_146_dialog_content = "不用難過，那個對妳不好的傢伙已經成為過去了！",
  ui_story_5040_50400901_147_dialog_content = "按照前輩告訴我的經驗，不善待他人的傢伙都不會有什麼好下場的！",
  ui_story_5040_50400901_148_dialog_content = "至於亞度尼斯和塔拉，如果妳介意的話，那我帶妳離開這裡，我們單獨行動吧？",
  ui_story_5040_50400901_149_dialog_content = "不，不要……",
  ui_story_5040_50400901_150_dialog_content = "他們，讓我想起，溫暖的事情。",
  ui_story_5040_50400901_151_dialog_content = "家人、朋友，還有愛……",
  ui_story_5040_50400901_152_dialog_content = "那是我一直渴求的，溫暖的感覺……",
  ui_story_5040_50400901_153_dialog_content = "這份溫暖，很珍貴，所以我，祝福他們。",
  ui_story_5040_50400901_154_dialog_content = "嗯……",
  ui_story_5040_50400901_155_dialog_content = "<color=#e8d9bb>咕嚕嚕——</color>",
  ui_story_5040_50400901_156_dialog_content = "餓……",
  ui_story_5040_50400901_157_dialog_content = "我也有點餓了，我們去吃晚飯吧！",
  ui_story_5040_50400901_158_dialog_content = "（沒想到已經這麼晚了，也不知道塔拉她們的晚飯準備得怎麼樣了。）",
  ui_story_5040_50400901_159_dialog_content = "哈啾——！",
  ui_story_5040_50400901_160_dialog_content = "（這、這股刺激的辛辣味是——紅油燒烤！）",
  ui_story_5040_50400901_161_dialog_content = "咦？凱雅，小黑，妳們剛才不是去參觀了嗎？",
  ui_story_5040_50400901_162_dialog_content = "我們已經都看完了，正好肚子餓了，所以就來看看晚飯準備得怎麼樣！",
  ui_story_5040_50400901_163_dialog_content = "嗯……",
  ui_story_5040_50400901_164_dialog_content = "（沒想到那麼多積壓的郵件都已經被分門別類地整理好了。）",
  ui_story_5040_50400901_165_dialog_content = "（甚至還按照郵件的差異把可能屬於同一個人的郵件放在了一起！）",
  ui_story_5040_50400901_166_dialog_content = "（多虧這樣，我和小黑才能很快找到郵件。）",
  ui_story_5040_50400901_167_dialog_content = "（這些應該都是耶利亞長老的努力吧。）",
  ui_story_5040_50400901_168_dialog_content = "嗯？這裡還真熱鬧。",
  ui_story_5040_50400901_169_dialog_content = "這味道……呵呵，你們紅油扳手的傢伙們，只會製作這種辛辣燒烤嗎？",
  ui_story_5040_50400901_170_dialog_content = "來了這裡，當然要入鄉隨俗了。",
  ui_story_5040_50400901_171_dialog_content = "耶利亞，妳忙完了？",
  ui_story_5040_50400901_172_dialog_content = "嗯，車輛和裝備都已經準備好了，我也查到了沙蟲的活動範圍。",
  ui_story_5040_50400901_173_dialog_content = "那傢伙被人打傷了，正在向沙漠深處移動。",
  ui_story_5040_50400901_174_dialog_content = "（耶利亞說的和醒山一致，應該沒有問題。）",
  ui_story_5040_50400901_175_dialog_content = "（我還是不說了，以免耶利亞又不高興……）",
  ui_story_5040_50400901_176_dialog_content = "來得正好！烤蜥蜴乾已經準備得差不多了，嚐嚐看吧！",
  ui_story_5040_50400901_177_dialog_content = "這真的是烤串嗎？已經被辣椒裹得看不出原樣了。",
  ui_story_5040_50400901_178_dialog_content = "這叫「爆辣蜥蜴乾」，是只有最勇敢的人才敢品嚐的頂級紅油燒烤。",
  ui_story_5040_50400901_179_dialog_content = "呃，真的要吃嗎？",
  ui_story_5040_50400901_180_dialog_content = "那上面的辣醬那麼多，只是聞一下鼻子就能感覺到痛。",
  ui_story_5040_50400901_181_dialog_content = "你到底要不要吃？",
  ui_story_5040_50400901_182_dialog_content = "吃，當然吃！",
  ui_story_5040_50400901_183_dialog_content = "別勉強，亞度尼斯。",
  ui_story_5040_50400901_184_dialog_content = "嚼嚼嚼——",
  ui_story_5040_50400901_185_dialog_content = "……",
  ui_story_5040_50400901_186_dialog_content = "一、一整個都吃下去了？",
  ui_story_5040_50400901_187_dialog_content = "……！",
  ui_story_5040_50400901_188_dialog_content = "<color=#e8d9bb>撲通！</color>",
  ui_story_5040_50400901_189_dialog_content = "亞度尼斯？！",
  ui_story_5040_50400901_190_dialog_content = "哈哈哈，真不得了，他的臉都漲成紫色了。",
  ui_story_5040_50400901_191_dialog_content = "辣……",
  ui_story_5040_50400901_192_dialog_content = "<size=45>好辣——！！！</size>",
  ui_story_5040_50400901_193_dialog_content = "嗚哇，他看起來要暈過去了！",
  ui_story_5040_50400901_194_dialog_content = "快去給他拿牛奶！我聽說喝牛奶可以解辣！",
  ui_story_5040_50400901_195_dialog_content = "我去找！",
  ui_story_5040_50400901_196_dialog_content = "……",
  ui_story_5040_50400901_197_dialog_content = "（她怎麼走了？跟上去看看吧。）",
  ui_story_5040_50400901_198_dialog_content = "我找到牛奶了！",
  ui_story_5040_50400901_199_dialog_content = "亞度尼斯，快把這個喝下去！",
  ui_story_5040_50400901_200_dialog_content = "咕咚咕咚——",
  ui_story_5040_50400901_201_dialog_content = "哈……哈……我還活著嗎……",
  ui_story_5040_50400901_202_dialog_content = "你剛才吃了一整根蜥蜴乾烤串以後，就直挺挺地倒下了。",
  ui_story_5040_50400901_203_dialog_content = "是嗎？",
  ui_story_5040_50400901_204_dialog_content = "呃，我的胃好痛，像是生吞了一塊燃燒的木炭……",
  ui_story_5040_50400901_205_dialog_content = "<size=45><anim type=Shake>嘔——！</anim></size>",
  ui_story_5040_50400901_206_dialog_content = "亞度尼斯！！！",
  ui_story_5040_50400901_207_dialog_content = "<color=#e8d9bb>與此同時，另一邊</color>",
  ui_story_5040_50400901_208_dialog_content = "妳的小男朋友正在那邊吐得昏天黑地，妳就不打算去幫幫他嗎？",
  ui_story_5040_50400901_209_dialog_content = "還是說，妳又有了什麼新的主意？",
  ui_story_5040_50400901_210_dialog_content = "等亞度尼斯恢復，就把他送回北境吧。",
  ui_story_5040_50400901_211_dialog_content = "我已經累了，不想再這麼鬧下去了。",
  ui_story_5040_50400901_212_dialog_content = "他和我本來也不是應該走到一起的人，我們不合適。",
  ui_story_5040_50400901_213_dialog_content = "哦？",
  ui_story_5040_50400901_214_dialog_content = "我原本以為，只要兩個人在一起，不管什麼困難都能克服。",
  ui_story_5040_50400901_215_dialog_content = "所以我總是希望讓他嘗試紅油沙漠的生活方式，就比如剛才的燒烤……",
  ui_story_5040_50400901_216_dialog_content = "但我沒想到，我喜歡的東西，卻會對他造成傷害。",
  ui_story_5040_50400901_217_dialog_content = "而他也總是為了迎合我而勉強自己，不停受傷。",
  ui_story_5040_50400901_218_dialog_content = "我覺得這不是愛。",
  ui_story_5040_50400901_X218_dialog_content = "唉……果然戀愛中的鳥兒因為一件小事得出什麼樣的結論都不奇怪。",
  ui_story_5040_50400901_X219_dialog_content = "為什麼你會這麼想？",
  ui_story_5040_50400901_219_dialog_content = "我和他，不管是生活習慣還是性格都天差地別，或許他的父母才是正確的。",
  ui_story_5040_50400901_220_dialog_content = "北境的小鳥沒有輕薄的羽毛，也不知道怎麼挖地找水，來到紅油沙漠當然沒辦法活下去。",
  ui_story_5040_50400901_221_dialog_content = "……",
  ui_story_5040_50400901_222_dialog_content = "這並不是有勇氣就能克服的困難，而是生理差異決定的事情。",
  ui_story_5040_50400901_223_dialog_content = "對於沙漠的鳥兒來說，這是日常，但對於北境的鳥兒來說，這就是危險。",
  ui_story_5040_50400901_224_dialog_content = "但是……",
  ui_story_5040_50400901_225_dialog_content = "但是什麼？",
  ui_story_5040_50400901_226_dialog_content = "明明那隻小鳥吃不了辣，卻還要去吃那串燒烤，最後被辣得倒下。",
  ui_story_5040_50400901_227_dialog_content = "他想要給你看的，難道不正是他鼓起勇氣，咬下第一口的那個瞬間嗎？",
  ui_story_5040_50400901_228_dialog_content = "雙方都能接受的生活方式，慢慢去找不就好了？",
  ui_story_5040_50400901_229_dialog_content = "而且又不是非要限定於紅油沙漠的生活方式這一種。",
  ui_story_5040_50400901_230_dialog_content = "……！",
  ui_story_5040_50400901_231_dialog_content = "好了，我想說的也沒有別的。",
  ui_story_5040_50400901_232_dialog_content = "你們在不在一起無所謂，但既然來到了我這裡，就當是來散心吧。",
  ui_story_5040_50400901_233_dialog_content = "開心地玩一玩，不要壞了大家的興致。",
  ui_story_5040_50400901_234_dialog_content = "……",
  ui_story_5040_50400901_235_dialog_content = "嗯。",
  ui_story_5040_50400901_236_dialog_content = "我回去了。",
  ui_story_5040_50400901_237_dialog_content = "哎呀呀，還真是一隻有趣的小鳥兒。",
  ui_story_5040_50400901_238_dialog_content = "他們的故事又會走向何方呢，真是讓人好奇。",
  ui_story_5040_50400901_239_dialog_content = "……呵呵，我這是怎麼了。",
  ui_story_5040_50400901_240_dialog_content = "竟然會對這種事情產生興趣。",
  ui_story_5040_50401001_1_dialog_content = "喲，你們來了？",
  ui_story_5040_50401001_2_dialog_content = "今天說好了要出門找沙蟲，所以我特地早起了。",
  ui_story_5040_50401001_3_dialog_content = "除了沒人敢吃那些燒烤，最後不得已去臨空者號上重新做了吃的以外……",
  ui_story_5040_50401001_4_dialog_content = "你們真是不懂得品味美食。不過不用擔心，我已經把所有的燒烤都吃了。",
  ui_story_5040_50401001_5_dialog_content = "一點也沒有浪費！",
  ui_story_5040_50401001_6_dialog_content = "不浪費糧食，我很贊同。",
  ui_story_5040_50401001_7_dialog_content = "說起來，大家昨晚睡得好嗎？有沒有水土不服？",
  ui_story_5040_50401001_8_dialog_content = "我可是睡了個好覺呢。",
  ui_story_5040_50401001_9_dialog_content = "沙漠的夜晚有些冷，但多虧耶利亞長老準備的厚被子，我和小黑都睡了個好覺。",
  ui_story_5040_50401001_10_dialog_content = "謝謝，耶利亞。",
  ui_story_5040_50401001_11_dialog_content = "呵呵，不用謝，黑色的小鳥兒。",
  ui_story_5040_50401001_12_dialog_content = "我……呃……",
  ui_story_5040_50401001_13_dialog_content = "我的胃，痛了一晚上……",
  ui_story_5040_50401001_14_dialog_content = "（我昨天半夜聽到好幾次衝向廁所的腳步聲，難道是亞度尼斯發出來的嗎？）",
  ui_story_5040_50401001_15_dialog_content = "你要不要休息一下？",
  ui_story_5040_50401001_16_dialog_content = "不，不用！",
  ui_story_5040_50401001_17_dialog_content = "我沒事的，可以和你們一起行動！",
  ui_story_5040_50401001_18_dialog_content = "……",
  ui_story_5040_50401001_19_dialog_content = "（從昨晚吃完飯以後，塔拉的表情就一直怪怪的，難道她有什麼心事？）",
  ui_story_5040_50401001_20_dialog_content = "那我們上車吧，塔拉坐副駕駛，你們幾個就在後排湊合一下吧。",
  ui_story_5040_50401001_21_dialog_content = "<color=#e8d9bb>一段時間後</color>",
  ui_story_5040_50401001_22_dialog_content = "這裡已經接近沙漠深處沙蟲出沒的區域了。",
  ui_story_5040_50401001_23_dialog_content = "我們就在這裡進行最後的休整吧。",
  ui_story_5040_50401001_24_dialog_content = "我已經和小黑一起，把帳篷、炊具和食材都從車上搬下來了。",
  ui_story_5040_50401001_25_dialog_content = "隨時可以開始煮飯！",
  ui_story_5040_50401001_26_dialog_content = "真是辛苦了。",
  ui_story_5040_50401001_27_dialog_content = "既然行李都卸了下來，那大家就都回車上去吧。",
  ui_story_5040_50401001_28_dialog_content = "欸？為什麼？不是要休息嗎？",
  ui_story_5040_50401001_29_dialog_content = "在休息之前，還有一件事要做。",
  ui_story_5040_50401001_30_dialog_content = "前面的沙丘起伏更大，可是兜風散心的絕佳場地。",
  ui_story_5040_50401001_31_dialog_content = "起伏大和散心有什麼關係？",
  ui_story_5040_50401001_32_dialog_content = "等一下妳就知道了，北境的小鳥兒。",
  ui_story_5040_50401001_X32_dialog_content = "好了，快上車吧。",
  ui_story_5040_50401001_X33_dialog_content = "可是，這……",
  ui_story_5040_50401001_X34_dialog_content = "好了好了，別說那些有的沒的了，上車吧！",
  ui_story_5040_50401001_X35_dialog_content = "空裔小哥也一起來吧。",
  ui_story_5040_50401001_X36_dialog_content = "<color=#e8d9bb>車上</color>",
  ui_story_5040_50401001_X37_dialog_content = "大家都坐穩了嗎？",
  ui_story_5040_50401001_X38_dialog_content = "耶利亞，妳、妳要到底做什麼？",
  ui_story_5040_50401001_X39_dialog_content = "當然是……做些能讓塔拉開心的事情了。",
  ui_story_5040_50401001_X40_dialog_content = "我有種不好的預感，能讓我先下車嗎！",
  ui_story_5040_50401001_X41_dialog_content = "我去給大家準備午飯——",
  ui_story_5040_50401001_X42_dialog_content = "這可不行，空裔小哥是必不可少的。",
  ui_story_5040_50401001_33_option_content = "必不可少？！",
  ui_story_5040_50401001_34_dialog_content = "當然了，你可是我們重要的導航。",
  ui_story_5040_50401001_35_option_content = "我還是算了！",
  ui_story_5040_50401001_36_dialog_content = "可不要臨陣脫逃啊，空裔小哥。",
  ui_story_5040_50401001_37_dialog_content = "記得系好安全帶哦。",
  ui_story_5040_50401001_38_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5040_50401001_39_dialog_content = "唔啊？！",
  ui_story_5040_50401001_40_dialog_content = "這、這也太快了？！",
  ui_story_5040_50401001_41_dialog_content = "哈哈哈！好痛快！",
  ui_story_5040_50401001_42_dialog_content = "耶利亞，再開快一點，再快一點！",
  ui_story_5040_50401001_43_dialog_content = "救命！車子要飛起來了！",
  ui_story_5040_50401001_44_dialog_content = "這就是……飛行的……感覺嗎？",
  ui_story_5040_50401001_X44_dialog_content = "不行！別再快了，太、太危險了！",
  ui_story_5040_50401001_X45_dialog_content = "我的胃……又翻騰了起來……",
  ui_story_5040_50401001_45_dialog_content = "只有飛得更快、向著更猛烈的風暴衝擊，才能體會到飛翔的快樂啊！",
  ui_story_5040_50401001_46_dialog_content = "吼——！！！",
  ui_story_5040_50401001_47_dialog_content = "小心！有暗鬼被車的聲音吸引過來了！",
  ui_story_5040_50401001_48_dialog_content = "空裔小哥，到你發揮作用的時候了～",
  ui_story_5040_50401001_49_dialog_content = "啊？！",
  ui_story_5040_50401001_50_dialog_content = "不管是用眼睛還是用感應能力，好好告訴我暗鬼會從哪個方向進攻過來吧。",
  ui_story_5040_50401001_51_dialog_content = "在這麼快的車上？！妳這簡直就是強人所難！",
  ui_story_5040_50401001_52_dialog_content = "吼！",
  ui_story_5040_50401001_53_dialog_content = "啊！左後方，來了！",
  ui_story_5040_50401001_54_dialog_content = "好。",
  ui_story_5040_50401001_55_dialog_content = "<color=#e8d9bb>吱——</color>",
  ui_story_5040_50401001_56_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_5040_50401001_57_dialog_content = "暗鬼直接被車身撞飛了？！",
  ui_story_5040_50401001_58_dialog_content = "我要，不行了……嘔！",
  ui_story_5040_50401001_59_dialog_content = "可別吐在我車上啊，北境的小鳥兒。",
  ui_story_5040_50401001_60_dialog_content = "你看，塔拉的心情可是難得地好起來了。",
  ui_story_5040_50401001_61_dialog_content = "是、是嗎？我要，忍住……為了塔拉……",
  ui_story_5040_50401001_62_dialog_content = "……",
  ui_story_5040_50401001_63_dialog_content = "吼！！！",
  ui_story_5040_50401001_64_dialog_content = "又來了，正前方出現暗鬼！",
  ui_story_5040_50401001_65_dialog_content = "就讓牠感受一下這份速度與熾烈的熱情吧。",
  ui_story_5040_50401001_66_dialog_content = "全速前進！",
  ui_story_5040_50401001_67_dialog_content = "哈哈哈，果然痛快！",
  ui_story_5040_50401001_68_dialog_content = "不行了，我又要……嘔！",
  ui_story_5040_50401001_69_dialog_content = "哎呀，才這麼點路就暈車了？看來北境的小鳥還要慢慢適應沙漠環境呢。",
  ui_story_5040_50401001_70_dialog_content = "不過，也只有被沙漠裡的風吹拂著的時候，屬於沙漠的鳥兒才能自由飛翔。",
  ui_story_5040_50401001_71_dialog_content = "是啊……",
  ui_story_5040_50401001_72_dialog_content = "我決定了。",
  ui_story_5040_50401001_73_dialog_content = "終於下定決心了？",
  ui_story_5040_50401001_74_dialog_content = "嗯，亞度尼斯，其實我——",
  ui_story_5040_50401001_75_dialog_content = "欸……？",
  ui_story_5040_50401001_76_dialog_content = "<color=#e8d9bb>轟隆隆……</color>",
  ui_story_5040_50401001_77_dialog_content = "耶利亞長老，有暗鬼！",
  ui_story_5040_50401001_78_dialog_content = "好多暗鬼向著這邊衝過來了！",
  ui_story_5040_50401001_79_dialog_content = "這些黑漆漆的傢伙還真是沒情調。",
  ui_story_5040_50401001_80_dialog_content = "誰讓耶利亞妳剛才飆車太大聲了，這些暗鬼一定是被聲音引過來的！",
  ui_story_5040_50401001_81_dialog_content = "小鳥兒們，真情流露的話就等一下再說吧。",
  ui_story_5040_50401001_82_dialog_content = "現在先把這些傢伙都收拾掉，然後好好吃一頓午飯。",
  ui_story_5040_50401001_83_dialog_content = "唉……",
  ui_story_5040_50401001_84_dialog_content = "我、我也來幫忙！",
  ui_story_5040_50401002_1_dialog_content = "暗鬼還是趴著的比較可愛一些。",
  ui_story_5040_50401002_2_dialog_content = "嘎嗷——",
  ui_story_5040_50401002_3_dialog_content = "怕……",
  ui_story_5040_50401002_4_dialog_content = "不怕不怕，她不會……呃，我是說，暗鬼已經都被消滅了！",
  ui_story_5040_50401002_5_dialog_content = "不是，怕耶利亞……",
  ui_story_5040_50401002_6_dialog_content = "耶利亞，好人，保護大家……",
  ui_story_5040_50401002_7_dialog_content = "但是暗鬼到處破壞，把我們準備的食材都弄得一團糟了。",
  ui_story_5040_50401002_8_dialog_content = "本來還想做影鎮風格的點心，結果食物被糟蹋成這樣，全都沒法用了！",
  ui_story_5040_50401002_9_dialog_content = "哎呀，這可怎麼是好呢？",
  ui_story_5040_50401002_10_dialog_content = "（耶利亞剛才好像看了亞度尼斯一眼？）",
  ui_story_5040_50401002_11_dialog_content = "我有辦法。",
  ui_story_5040_50401002_12_dialog_content = "欸？",
  ui_story_5040_50401002_13_dialog_content = "這些食材只要清理一下，還能繼續用。",
  ui_story_5040_50401002_14_dialog_content = "只不過可能沒法用來做點心了，但是做燉菜還是沒問題的！",
  ui_story_5040_50401002_15_dialog_content = "就交給我吧！",
  ui_story_5040_50401002_16_dialog_content = "（亞度尼斯飛快地忙碌了起來？！）",
  ui_story_5040_50401002_17_dialog_content = "首先把被弄爛的部分削掉，保留能用的部分。",
  ui_story_5040_50401002_18_dialog_content = "然後把這些食材切成適口的小塊，放進沸騰的水裡煮。",
  ui_story_5040_50401002_19_dialog_content = "塔拉，可以把那個遞給我嗎？",
  ui_story_5040_50401002_20_dialog_content = "給。",
  ui_story_5040_50401002_21_dialog_content = "謝謝，這個時候要加一些鹽……",
  ui_story_5040_50401002_22_dialog_content = "好香！",
  ui_story_5040_50401002_23_dialog_content = "給，塔拉，這碗是妳的。我已經把妳不吃的胡蘿蔔都挑出去了。",
  ui_story_5040_50401002_24_dialog_content = "謝謝……",
  ui_story_5040_50401002_25_dialog_content = "請給我也盛一碗！還有小黑的份！",
  ui_story_5040_50401002_26_dialog_content = "好好好，稍等一下，我這就給你盛。",
  ui_story_5040_50401002_27_dialog_content = "給你，我把碗都拿來了。",
  ui_story_5040_50401002_28_dialog_content = "嗯，這頓午飯可真不錯！",
  ui_story_5040_50401002_29_dialog_content = "雖然在沙漠裡吃燉菜有點熱，但是看在它這麼美味的份上，我就不計較了！",
  ui_story_5040_50401002_30_dialog_content = "妳覺得好吃就好！",
  ui_story_5040_50401002_31_dialog_content = "這些碗就交給我來清洗吧。",
  ui_story_5040_50401002_32_dialog_content = "好，那我也在附近稍微巡邏一下，防止暗鬼再冒出來。",
  ui_story_5040_50401002_33_dialog_content = "等一下，妳剛才是不是想說什麼來著？",
  ui_story_5040_50401002_34_dialog_content = "暗鬼一來搗亂，差點就忘記了。",
  ui_story_5040_50401002_35_dialog_content = "……不，沒什麼。我去巡邏了。",
  ui_story_5040_50401002_36_dialog_content = "我和小黑也去附近轉一轉，看看風景！",
  ui_story_5040_50401002_37_dialog_content = "（真奇怪，塔拉好像有什麼事瞞著我。）",
  ui_story_5040_50401002_38_dialog_content = "（對了，剛才就算我沒說想要什麼，塔拉就已經將鹽罐遞給了我。）",
  ui_story_5040_50401002_39_dialog_content = "（她的記憶開始恢復了？）",
  ui_story_5040_50401002_40_dialog_content = "（這麼說來，她一路上似乎也有很多奇怪的地方。）",
  ui_story_5040_50401002_41_dialog_content = "（剛才她支支吾吾的樣子，也很像是之前做錯事準備道歉時的表情。）",
  ui_story_5040_50401002_42_dialog_content = "（太奇怪了，難道……她根本沒有失憶？）",
  ui_story_5040_50401002_43_dialog_content = "（但她為什麼要這麼做呢？讓我想一想……）",
  ui_story_5040_50401002_44_dialog_content = "（塔拉假裝失憶，讓我不得不走出北境，這一切難道都是為了讓我鼓起勇氣才做的？）",
  ui_story_5040_50401002_45_dialog_content = "（塔拉，我會證明給妳看的，一定會！）",
  ui_story_5040_50401002_46_dialog_content = "亞度尼斯，你在發呆嗎？",
  ui_story_5040_50401002_47_dialog_content = "沒有沒有！有什麼事嗎，PlayerName？",
  ui_story_5040_50401002_48_dialog_content = "需要我幫忙嗎？",
  ui_story_5040_50401002_49_dialog_content = "不用，我自己就能收拾好！",
  ui_story_5040_50401002_50_dialog_content = "你去忙別的吧。",
  ui_story_5040_50401002_51_dialog_content = "好吧。",
  ui_story_5040_50401002_52_dialog_content = "（一個人待著真無聊，如果這個時候薇絲和卡蓮在就好了，我們還能一起聊天。）",
  ui_story_5040_50401002_53_dialog_content = "（耶利亞好像也是一個人，她不會覺得無聊嗎？）",
  ui_story_5040_50401002_54_dialog_content = "（她應該沒在生氣了吧？我還是過去問一下好了。）",
  ui_story_5040_50401002_55_dialog_content = "呼，稍微有些睏倦了，不過……",
  ui_story_5040_50401002_56_dialog_content = "塔拉、亞度尼斯，呵呵，這兩隻小鳥還真有意思。",
  ui_story_5040_50401002_57_dialog_content = "耶利亞！",
  ui_story_5040_50401002_58_dialog_content = "嗯？這不是空裔小哥嗎，怎麼到這邊來了？",
  ui_story_5040_50401002_59_dialog_content = "難道是因為你的小夥伴不在，所以感覺到寂寞了嗎？",
  ui_story_5040_50401002_60_dialog_content = "才、才不是呢！",
  ui_story_5040_50401002_61_dialog_content = "還是說，你覺得我形單影隻的樣子，很可憐，所以過來了？",
  ui_story_5040_50401002_62_dialog_content = "也不是……",
  ui_story_5040_50401002_63_dialog_content = "我有事想問妳。",
  ui_story_5040_50401002_64_dialog_content = "哦？",
  ui_story_5040_50401002_65_option_content = "你是不是在說謊？",
  ui_story_5040_50401002_66_dialog_content = "這話怎麼說？",
  ui_story_5040_50401002_67_dialog_content = "早上的時候，妳說自己昨晚睡了個好覺。",
  ui_story_5040_50401002_68_dialog_content = "但這和我聽說的不符！",
  ui_story_5040_50401002_69_option_content = "妳是不是在逞強？",
  ui_story_5040_50401002_70_dialog_content = "逞強？呵呵，空裔小哥是怎麼得出這個結論的？",
  ui_story_5040_50401002_71_dialog_content = "我聽說，妳昨天驅使自己的言靈在整片沙漠裡找了一天沙蟲。",
  ui_story_5040_50401002_72_dialog_content = "……",
  ui_story_5040_50401002_73_dialog_content = "就算這樣又如何？",
  ui_story_5040_50401002_74_dialog_content = "那樣太亂來了！",
  ui_story_5040_50401002_75_dialog_content = "高強度地用了那麼久光能術，今天又很早起來沒有好好休息，直到剛才還在戰鬥。",
  ui_story_5040_50401002_76_dialog_content = "妳是在透支自己！",
  ui_story_5040_50401002_77_dialog_content = "就算這樣又如何？",
  ui_story_5040_50401002_78_dialog_content = "我只是想說，你不用這麼勉強自己，偶爾依靠一下別人也沒關係。",
  ui_story_5040_50401002_79_dialog_content = "就算不依靠別人，我也能一個人在沙漠中過得很好。",
  ui_story_5040_50401002_80_dialog_content = "我能獨自找到沙蟲的蹤跡，也能完成信使公會的工作，為整個沙漠裡的人送信。",
  ui_story_5040_50401002_81_dialog_content = "你又有什麼資格來質疑我？",
  ui_story_5040_50401002_82_dialog_content = "我不是這個意思！",
  ui_story_5040_50401002_83_dialog_content = "我知道，我作為空裔，沒有強大的光能術，面對暗鬼也毫無還手之力。",
  ui_story_5040_50401002_84_dialog_content = "所以這一路走來，很多時候都是在依靠夥伴們的力量。",
  ui_story_5040_50401002_85_dialog_content = "但也正是因為弱小讓我意識到了，在這個世界上，只靠自己是活不下去的。",
  ui_story_5040_50401002_86_dialog_content = "哦？",
  ui_story_5040_50401002_87_dialog_content = "一個人就算再強大，也總會遇到超過自己能力的問題。",
  ui_story_5040_50401002_88_dialog_content = "其中一部分或許能靠自己的成長或者拼命努力扛過去……",
  ui_story_5040_50401002_89_dialog_content = "但是總有些問題，讓你來不及成長或者超越了努力的極限。",
  ui_story_5040_50401002_90_dialog_content = "尤其是對弱小的空裔而言，我的經歷裡，充滿了這樣的問題。",
  ui_story_5040_50401002_91_dialog_content = "你是想說，依靠別人不是丟臉的事情？",
  ui_story_5040_50401002_92_dialog_content = "呵呵，空裔小哥還真是天真。",
  ui_story_5040_50401002_93_dialog_content = "這樣的事情，或許一次兩次可以，但是次數多了，欠下的人情就會變成債務。",
  ui_story_5040_50401002_94_dialog_content = "這些債務會變成束縛鳥兒的枷鎖，讓鳥兒再也無法自由飛翔。",
  ui_story_5040_50401002_95_dialog_content = "身負那麼多人情債的你，應該也能理解這種想法吧？",
  ui_story_5040_50401002_96_option_content = "能",
  ui_story_5040_50401002_97_dialog_content = "確實，每次欠下人情都會覺得不好意思。",
  ui_story_5040_50401002_98_dialog_content = "沒錯，我不喜歡這種感覺，也不想與別人有什麼交集。",
  ui_story_5040_50401002_99_dialog_content = "自己一個人自由自在地活著，難道不好嗎？",
  ui_story_5040_50401002_100_dialog_content = "自由地生活當然很好，可以做自己想做的事情，不用考慮太多。",
  ui_story_5040_50401002_101_dialog_content = "但是人與人之間的交集，並不是冷冰冰的債務。",
  ui_story_5040_50401002_102_option_content = "不能",
  ui_story_5040_50401002_103_dialog_content = "我確實接受過很多人的幫助，但我並不認為那是什麼負擔。",
  ui_story_5040_50401002_104_dialog_content = "……！",
  ui_story_5040_50401002_105_dialog_content = "每個人都有自己擅長和不擅長的事情，而人們之間是能夠互補的。",
  ui_story_5040_50401002_106_dialog_content = "就像我的同伴們擅長光能術，而我能看見光的軌跡，我們可以並肩作戰，一起對付暗鬼。",
  ui_story_5040_50401002_107_dialog_content = "我不知道妳曾經經歷了什麼，才讓妳這麼抗拒與人交流。",
  ui_story_5040_50401002_108_dialog_content = "但是人與人之間的關係是相互的，我接受了別人的幫助，也會盡自己所能幫助別人。",
  ui_story_5040_50401002_109_dialog_content = "……",
  ui_story_5040_50401002_110_dialog_content = "呵呵，原來你是這樣想的啊。",
  ui_story_5040_50401002_111_dialog_content = "看來你和你的小夥伴們，也和那兩隻小鳥兒一樣呢。",
  ui_story_5040_50401002_112_dialog_content = "欸？！",
  ui_story_5040_50401002_113_dialog_content = "我、我們只是普通的朋友！才沒有——",
  ui_story_5040_50401002_114_dialog_content = "哎呀？你的小腦瓜想到哪裡去了？我可還什麼都沒說哦。",
  ui_story_5040_50401002_115_dialog_content = "妳……",
  ui_story_5040_50401002_116_dialog_content = "你看，他們兩個，很互補吧？",
  ui_story_5040_50401002_117_dialog_content = "我回來了，附近暫時沒有發現暗鬼的蹤跡。",
  ui_story_5040_50401002_118_dialog_content = "辛苦了！給，喝點水休息一下吧。",
  ui_story_5040_50401002_119_dialog_content = "確實呢……",
  ui_story_5040_50401002_120_dialog_content = "塔拉外向又開朗，在野外生存和對付暗鬼的經驗很豐富。",
  ui_story_5040_50401002_121_dialog_content = "亞度尼斯則是負責後勤，也有足夠的耐心去面對塔拉不擅長的繁瑣工作。",
  ui_story_5040_50401002_122_dialog_content = "是啊，沒想到竟然有人能和紅油扳手的傢伙合得來。",
  ui_story_5040_50401002_123_dialog_content = "耶利亞很討厭紅油扳手嗎？",
  ui_story_5040_50401002_124_dialog_content = "討厭？呵呵，或許吧。",
  ui_story_5040_50401002_125_dialog_content = "在我看來，他們不過是一群盲目又無腦的流匪。",
  ui_story_5040_50401002_126_dialog_content = "除了找樂子以外，他們對什麼都不關心。",
  ui_story_5040_50401002_127_dialog_content = "但妳用言靈滿沙漠找沙蟲這件事，是醒山告訴我的。",
  ui_story_5040_50401002_128_dialog_content = "什麼？",
  ui_story_5040_50401002_129_dialog_content = "昨天被你趕出去後，我聯繫了醒山，向他詢問粉紅沙蟲的事情。",
  ui_story_5040_50401002_130_dialog_content = "他告訴我說，紅油扳手的成員看見妳在用言靈尋找沙蟲。",
  ui_story_5040_50401002_131_dialog_content = "大家都很擔心妳，也都在關心著妳。",
  ui_story_5040_50401002_132_dialog_content = "那只不過是因為我是沙漠中為數不多的信使，能夠為他們傳遞需要的情報罷了。",
  ui_story_5040_50401002_133_dialog_content = "不是這樣的！",
  ui_story_5040_50401002_134_dialog_content = "好了，休息得差不多了。",
  ui_story_5040_50401002_135_dialog_content = "喂，耶利亞！",
  ui_story_5040_50401002_136_dialog_content = "收拾一下，要出發了。",
  ui_story_5040_50401002_137_dialog_content = "耶利亞可真是的，就這麼把人扔在這裡……",
  ui_story_5040_50401002_138_dialog_content = "她一直都是這樣，用逃避和逞強的方式，假裝自己沒問題嗎？",
  ui_story_5040_50401101_1_dialog_content = "收拾得怎麼樣了，小鳥兒們？",
  ui_story_5040_50401101_2_dialog_content = "已經全都收拾好了，隨時可以出發。",
  ui_story_5040_50401101_3_dialog_content = "我也準備好了。",
  ui_story_5040_50401101_4_dialog_content = "我檢查了所有的行李，沒有遺失，篝火也已經徹底熄滅了。",
  ui_story_5040_50401101_5_dialog_content = "凱雅還真是細心！",
  ui_story_5040_50401101_6_dialog_content = "謝謝，這都是愛梅洛前輩教得好。",
  ui_story_5040_50401101_7_dialog_content = "愛梅洛？那是誰啊？",
  ui_story_5040_50401101_8_dialog_content = "那是我在信使公會的前輩，不過現在已經退休了。",
  ui_story_5040_50401101_9_dialog_content = "在我成為信使以前，都是愛梅洛前輩在給我的家鄉法爾村以及附近的村莊送信的。",
  ui_story_5040_50401101_10_dialog_content = "因為我的家鄉實在是太偏僻，幾乎和外界沒有往來。",
  ui_story_5040_50401101_11_dialog_content = "唯一認識外界的方法，就是愛梅洛前輩為村裡人送來的一封封信件。",
  ui_story_5040_50401101_12_dialog_content = "那位前輩一定是一位很負責的人吧？",
  ui_story_5040_50401101_13_dialog_content = "當然了！正是受了愛梅洛前輩的影響，我才決定要成為信使的！",
  ui_story_5040_50401101_14_dialog_content = "因為知道地處偏遠的人們與外界聯繫有多困難，所以我才想要成為能讓他們認識外面世界的人。",
  ui_story_5040_50401101_15_dialog_content = "真了不起啊！",
  ui_story_5040_50401101_16_dialog_content = "嘿嘿，我還差得遠呢。",
  ui_story_5040_50401101_17_dialog_content = "就算有愛梅洛前輩給我的筆記，我也經常把事情搞砸……",
  ui_story_5040_50401101_18_dialog_content = "明明我按部就班地照著筆記上寫的方法做了，卻總會在最後發現情況超出預期。",
  ui_story_5040_50401101_19_dialog_content = "也不至於那麼嚴格地按照筆記來啦，很多時候都是要隨機應變的。",
  ui_story_5040_50401101_20_dialog_content = "唉，我最不擅長的就是隨機應變了。",
  ui_story_5040_50401101_21_dialog_content = "嗷——",
  ui_story_5040_50401101_22_dialog_content = "你們沒有聽見，遠處好像有什麼聲音？",
  ui_story_5040_50401101_23_dialog_content = "那是……",
  ui_story_5040_50401101_24_dialog_content = "嘎嗷——！！！",
  ui_story_5040_50401101_25_dialog_content = "有暗鬼來了，大家小心！",
  ui_story_5040_50401101_26_dialog_content = "好多暗鬼？！",
  ui_story_5040_50401101_27_dialog_content = "嘖，這群傢伙又是從哪裡冒出來的？！",
  ui_story_5040_50401101_28_dialog_content = "竟然又出現了暗鬼，真奇怪……",
  ui_story_5040_50401101_29_dialog_content = "還是先對付眼前這群傢伙吧，可要好好加油啊，各位。",
  ui_story_5040_50401102_1_dialog_content = "嘎嗷——",
  ui_story_5040_50401102_2_dialog_content = "真奇怪，這些暗鬼並沒有戀戰，反而都跑了？",
  ui_story_5040_50401102_3_dialog_content = "按照常理講，這個地方一般不屬於暗鬼經常出沒的區域。",
  ui_story_5040_50401102_4_dialog_content = "但是現在我們卻接連遇到了兩群暗鬼，這不正常。",
  ui_story_5040_50401102_5_dialog_content = "牠們，逃跑……",
  ui_story_5040_50401102_6_dialog_content = "妳說什麼？",
  ui_story_5040_50401102_7_dialog_content = "小黑說，牠們好像是在逃跑，在躲避什麼？",
  ui_story_5040_50401102_8_dialog_content = "<color=#e8d9bb>轟……</color>",
  ui_story_5040_50401102_9_dialog_content = "地面在震動？",
  ui_story_5040_50401102_10_dialog_content = "各位，快散開，有什麼東西要來了！",
  ui_story_5040_50401102_11_dialog_content = "塔拉，小心！",
  ui_story_5040_50401102_12_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_5040_50401102_13_dialog_content = "<size=50>吼——！！！</size>",
  ui_story_5040_50401102_14_dialog_content = "哇？！真、真的是粉色的沙蟲？！",
  ui_story_5040_50401102_15_dialog_content = "不是說這傢伙往沙漠深處去了嗎？這裡離沙漠深處應該還遠吧！",
  ui_story_5040_50401102_16_dialog_content = "也有另一種可能，就是牠出於某種理由，需要儘快進食。",
  ui_story_5040_50401102_17_dialog_content = "難道說，牠剛才是想捕食那些暗鬼？",
  ui_story_5040_50401102_18_dialog_content = "答對了。不過，現在牠把我們當成食物了。",
  ui_story_5040_50401102_19_dialog_content = "<size=50>吼！</size>",
  ui_story_5040_50401102_20_dialog_content = "嗯？就這麼著急嗎，大傢伙？",
  ui_story_5040_50401102_21_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5040_50401102_22_dialog_content = "好硬？！",
  ui_story_5040_50401102_23_dialog_content = "呵呵，看來這些粉色的鱗片可不像它們看起來那樣無害。",
  ui_story_5040_50401102_24_dialog_content = "但是，鱗片再堅硬，牠也只不過是一隻沙蟲。",
  ui_story_5040_50401102_25_dialog_content = "去吧，言靈們！",
  ui_story_5040_50401102_26_dialog_content = "吼——",
  ui_story_5040_50401102_27_dialog_content = "太好了，有效果！",
  ui_story_5040_50401102_28_dialog_content = "我也來幫忙！",
  ui_story_5040_50401102_29_dialog_content = "塔拉，妳站得太靠前了，危險！",
  ui_story_5040_50401102_30_dialog_content = "不行，站得太遠會減損子彈的威力，那樣就打不穿這隻沙蟲的鱗片了。",
  ui_story_5040_50401102_31_dialog_content = "不過是一隻只會使用蠻力的蟲子，根本不用怕！",
  ui_story_5040_50401102_32_dialog_content = "吼……吼……！",
  ui_story_5040_50401102_33_dialog_content = "下一擊——是腦袋！",
  ui_story_5040_50401102_34_dialog_content = "吼！",
  ui_story_5040_50401102_35_dialog_content = "呀？！",
  ui_story_5040_50401102_36_dialog_content = "那只沙蟲竟然準確地咬住了塔拉的槍？！牠是故意瞄準的嗎？！",
  ui_story_5040_50401102_37_dialog_content = "放開！",
  ui_story_5040_50401102_38_dialog_content = "沙蟲竟然能有這種意識？這不對勁……",
  ui_story_5040_50401102_39_dialog_content = "以我們現在的力量，沒辦法迅速擊敗牠。",
  ui_story_5040_50401102_40_dialog_content = "牠想拖延下去，耗盡我們的體力！",
  ui_story_5040_50401102_41_dialog_content = "不能讓牠得逞。幻惑魔典，展現你的力量吧！",
  ui_story_5040_50401102_42_dialog_content = "吼——！",
  ui_story_5040_50401102_43_dialog_content = "沙蟲不見了？！",
  ui_story_5040_50401102_44_dialog_content = "牠躲進沙子裡了，小心腳下！",
  ui_story_5040_50401102_45_dialog_content = "<size=50>吼！！！</size>",
  ui_story_5040_50401102_46_dialog_content = "<color=#e8d9bb>唰——啪！</color>",
  ui_story_5040_50401102_47_dialog_content = "啊——！",
  ui_story_5040_50401102_48_dialog_content = "塔拉被甩到遠處的沙丘上了！",
  ui_story_5040_50401102_49_dialog_content = "塔拉！！！",
  ui_story_5040_50401102_50_dialog_content = "我沒事！",
  ui_story_5040_50401102_51_dialog_content = "這裡都是柔軟的沙子，沙蟲可以鑽進沙中偷襲。",
  ui_story_5040_50401102_52_dialog_content = "各位，先上車！",
  ui_story_5040_50401102_53_dialog_content = "我們撤到戈壁上去！那裡的地面是岩石，沙蟲沒辦法偷襲！",
  ui_story_5040_50401102_54_dialog_content = "知道了，小黑，我們走，先到車上去！",
  ui_story_5040_50401102_55_dialog_content = "亞度尼斯，快撤！",
  ui_story_5040_50401102_56_dialog_content = "好……塔拉！小心！",
  ui_story_5040_50401102_57_dialog_content = "吼——",
  ui_story_5040_50401102_58_dialog_content = "呃——！",
  ui_story_5040_50401102_59_dialog_content = "塔拉！",
  ui_story_5040_50401102_60_dialog_content = "嘶——",
  ui_story_5040_50401102_61_dialog_content = "糟了，塔拉的腿受傷了！",
  ui_story_5040_50401102_62_dialog_content = "吼！",
  ui_story_5040_50401102_63_dialog_content = "（該死，距離太遠了，該怎麼阻止牠……）",
  ui_story_5040_50401102_64_dialog_content = "離塔拉遠點，你這個醜陋的毛毛蟲！",
  ui_story_5040_50401102_65_dialog_content = "吼——",
  ui_story_5040_50401102_66_dialog_content = "看這邊！毛毛蟲！我在這裡呢！",
  ui_story_5040_50401102_67_dialog_content = "亞度尼斯引開了沙蟲的注意力！",
  ui_story_5040_50401102_68_dialog_content = "他那麼輕的攻擊，竟然也能奏效？！",
  ui_story_5040_50401102_69_dialog_content = "你看，沙蟲身上被亞度尼斯攻擊的地方，好像有一些未癒合的傷口？",
  ui_story_5040_50401102_70_dialog_content = "那一定是之前醒山和牠戰鬥時在牠身上留下的傷！",
  ui_story_5040_50401102_71_dialog_content = "吼！",
  ui_story_5040_50401102_72_dialog_content = "哇啊！！！",
  ui_story_5040_50401102_73_dialog_content = "沙蟲的注意力被亞度尼斯吸引了，正在遠離塔拉！",
  ui_story_5040_50401102_74_dialog_content = "耶利亞，好機會！",
  ui_story_5040_50401102_75_dialog_content = "呵呵，我明白了。",
  ui_story_5040_50401102_76_dialog_content = "去吧，鶴鷹！瞄準牠的傷口！",
  ui_story_5040_50401102_77_dialog_content = "吼……吼！",
  ui_story_5040_50401102_78_dialog_content = "趁現在！",
  ui_story_5040_50401102_79_dialog_content = "塔拉，妳沒事吧？",
  ui_story_5040_50401102_80_dialog_content = "我沒事，快去幫亞度尼斯！",
  ui_story_5040_50401102_81_dialog_content = "好！",
  ui_story_5040_50401102_82_dialog_content = "我也，幫忙！",
  ui_story_5040_50401102_83_dialog_content = "<color=#e8d9bb>錚！</color>",
  ui_story_5040_50401102_84_dialog_content = "吼！！！",
  ui_story_5040_50401102_85_dialog_content = "得、得救了！",
  ui_story_5040_50401102_86_dialog_content = "站在我們後面，小心別被打到了！",
  ui_story_5040_50401102_87_dialog_content = "吼！",
  ui_story_5040_50401102_88_dialog_content = "<color=#e8d9bb>轟隆！！！</color>",
  ui_story_5040_50401102_89_dialog_content = "嗚哇？！怎麼突然刮起沙暴了？",
  ui_story_5040_50401102_90_dialog_content = "這不是沙暴，這是那隻沙蟲故意掀起的沙塵。",
  ui_story_5040_50401102_91_dialog_content = "牠想透過這種方法迷惑我們的視線，隱藏起自己的弱點。",
  ui_story_5040_50401102_92_dialog_content = "糟了，我看不到凱雅他們的位置了！",
  ui_story_5040_50401102_93_dialog_content = "塔拉！妳在哪裡？！",
  ui_story_5040_50401102_94_dialog_content = "亞度尼斯，這邊！",
  ui_story_5040_50401102_95_dialog_content = "我們馬上過去！",
  ui_story_5040_50401102_96_dialog_content = "<color=#e8d9bb>轟隆！</color>",
  ui_story_5040_50401102_97_dialog_content = "啊！！！",
  ui_story_5040_50401102_98_dialog_content = "亞度尼斯？！",
  ui_story_5040_50401102_99_dialog_content = "我去把他們拉回來！",
  ui_story_5040_50401102_100_dialog_content = "<size=50>吼——！！！</size>",
  ui_story_5040_50401102_101_dialog_content = "呃！",
  ui_story_5040_50401102_102_dialog_content = "耶利亞，沙蟲要跑了！",
  ui_story_5040_50401102_103_dialog_content = "別想跑！",
  ui_story_5040_50401102_104_dialog_content = "<size=50>吼！！！</size>",
  ui_story_5040_50401102_105_dialog_content = "呃！！！",
  ui_story_5040_50401102_106_dialog_content = "PlayerName？！",
  ui_story_5040_50401102_107_dialog_content = "好痛……",
  ui_story_5040_50401201_1_dialog_content = "PlayerName，醒醒！",
  ui_story_5040_50401201_2_dialog_content = "呃，好痛！",
  ui_story_5040_50401201_3_dialog_content = "噗咳咳！我的嘴裡怎麼都是沙子！",
  ui_story_5040_50401201_4_dialog_content = "呼，你沒事就好，有沒有受傷？",
  ui_story_5040_50401201_5_dialog_content = "咳咳咳……我還好，除了頭頂有點痛以外，應該沒什麼事。",
  ui_story_5040_50401201_6_dialog_content = "剛才你以倒栽蔥的姿勢被沙蟲撞飛進沙子裡的時候，我還以為你要受重傷了。",
  ui_story_5040_50401201_7_dialog_content = "我和塔拉費了好大力氣才把你從沙子裡拔出來，可要好好感謝我們啊，空裔小哥。",
  ui_story_5040_50401201_8_dialog_content = "謝謝妳們……",
  ui_story_5040_50401201_9_dialog_content = "其他人呢？沒事吧？",
  ui_story_5040_50401201_10_dialog_content = "我們看到你露在外面的腳就先來救你了。",
  ui_story_5040_50401201_11_dialog_content = "剛才的沙暴太猛烈，不僅讓沙蟲逃了，也把我們和亞度尼斯他們衝散了。",
  ui_story_5040_50401201_12_dialog_content = "我也試試用感應能力幫忙！",
  ui_story_5040_50401201_13_option_content = "感應！",
  ui_story_5040_50401201_14_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5040_50401201_15_dialog_content = "附近感應不到他們的蹤跡……",
  ui_story_5040_50401201_16_dialog_content = "沒關係，我已經讓我的言靈去找了。不出意外的話，很快就能有消息。",
  ui_story_5040_50401201_17_dialog_content = "就算他們被埋在沙子裡，鶴鷹也能察覺到地面的微小振動，從而找到他們。",
  ui_story_5040_50401201_18_dialog_content = "亞度尼斯，千萬不要有事啊。",
  ui_story_5040_50401201_19_dialog_content = "啾——！",
  ui_story_5040_50401201_20_dialog_content = "我的鳥兒帶回消息了。",
  ui_story_5040_50401201_21_dialog_content = "怎麼樣，找到他們了嗎？",
  ui_story_5040_50401201_22_dialog_content = "啾——",
  ui_story_5040_50401201_23_dialog_content = "……什麼？附近都沒有？",
  ui_story_5040_50401201_24_dialog_content = "再去找，這次擴大搜尋範圍，不要顧慮光能的消耗。",
  ui_story_5040_50401201_25_dialog_content = "去吧！",
  ui_story_5040_50401201_26_dialog_content = "啾——！",
  ui_story_5040_50401201_27_dialog_content = "我也去附近找找。",
  ui_story_5040_50401201_28_dialog_content = "可是妳腿上還有傷！",
  ui_story_5040_50401201_29_dialog_content = "我沒辦法就這麼在這裡等！",
  ui_story_5040_50401201_30_dialog_content = "魯莽只會白費力氣，鷹的眼睛都看不到的東西，以妳的眼力更無法發現。",
  ui_story_5040_50401201_31_dialog_content = "還是好好在這裡休息吧，免得傷勢加重。",
  ui_story_5040_50401201_32_dialog_content = "……",
  ui_story_5040_50401201_33_dialog_content = "如果我沒有假裝失憶，亞度尼斯是不是就不會陷入危險了？",
  ui_story_5040_50401201_34_dialog_content = "唉……說實話，我早就透過感應能力察覺到你可能在裝。",
  ui_story_5040_50401201_35_dialog_content = "但我那時以為你可能有你的難處，所以才沒有拆穿你。",
  ui_story_5040_50401201_36_dialog_content = "是……",
  ui_story_5040_50401201_37_dialog_content = "現在想想，放任你假裝失憶，反而導致現在這種危險的情況！",
  ui_story_5040_50401201_38_dialog_content = "怎麼可以這樣？妳到底在想什麼啊？！",
  ui_story_5040_50401201_39_dialog_content = "我以為這樣能讓亞度尼斯克服對外界的恐懼。",
  ui_story_5040_50401201_40_dialog_content = "他一直對離開北境的生活心存憂慮，我希望能用這場考驗推他一把。",
  ui_story_5040_50401201_41_option_content = "這太亂來了！",
  ui_story_5040_50401201_42_dialog_content = "如果只是把我攪進來也就算了，但是亞度尼斯不是妳最在乎的人嗎？",
  ui_story_5040_50401201_43_dialog_content = "以考驗的名義讓自己最在乎的人置身於危險之中，這算什麼啊！",
  ui_story_5040_50401201_44_dialog_content = "現在甚至連凱雅和小黑都失蹤了，這可不是鬧著玩的！",
  ui_story_5040_50401201_45_dialog_content = "抱歉……",
  ui_story_5040_50401201_46_option_content = "……我理解妳",
  ui_story_5040_50401201_47_dialog_content = "有的時候，我也認為自己沒有足夠的勇氣去做某件事，需要被人推一把。",
  ui_story_5040_50401201_48_dialog_content = "妳的心意是對的，但我還是不太認同妳的方法。",
  ui_story_5040_50401201_49_dialog_content = "如果妳的朋友沒有勇氣直面挑戰，妳應該做的是陪伴在他們身邊。",
  ui_story_5040_50401201_50_dialog_content = "用妳的行動和言語讓他們鼓起勇氣，與他們一同面對困難。",
  ui_story_5040_50401201_51_dialog_content = "這是我的不對，是我太魯莽了……",
  ui_story_5040_50401201_52_dialog_content = "我本來以為，那只是除了顏色特別以外，沒什麼奇特之處的普通沙蟲。",
  ui_story_5040_50401201_53_dialog_content = "普通的沙蟲我對付過很多，不是什麼難事，我一個人就能確保亞度尼斯的安全。",
  ui_story_5040_50401201_54_dialog_content = "但我沒有想到，那傢伙竟然這麼狡猾和強大……",
  ui_story_5040_50401201_55_dialog_content = "我也要負一部分責任。",
  ui_story_5040_50401201_56_dialog_content = "我應該想到，那只沙蟲如此顯眼，能在兇險的沙漠裡活下來，一定有牠的一技之長。",
  ui_story_5040_50401201_57_dialog_content = "總之，是我的任性讓大家陷入了危機。我會負起責任，努力補救的。",
  ui_story_5040_50401201_58_dialog_content = "唉，先找到他們再說吧。",
  ui_story_5040_50401201_59_dialog_content = "希望他們平安無事……",
  ui_story_5040_50401201_60_dialog_content = "（凱雅她們行蹤未卜，令人擔憂。）",
  ui_story_5040_50401201_61_dialog_content = "（萬一連耶利亞的言靈都找不到他們該怎麼辦呢……）",
  ui_story_5040_50401201_62_dialog_content = "我的小鳥回來了。",
  ui_story_5040_50401201_63_dialog_content = "嗯？在哪裡？",
  ui_story_5040_50401201_64_dialog_content = "鶴鷹，這裡！",
  ui_story_5040_50401201_65_dialog_content = "啾——！",
  ui_story_5040_50401201_66_dialog_content = "吼……",
  ui_story_5040_50401201_67_dialog_content = "嗯？看起來還有些額外贈品呢……",
  ui_story_5040_50401201_68_dialog_content = "先解決掉牠們吧！",
  ui_story_5040_50401201_69_dialog_content = "請讓我也來幫忙，區區腿傷……對生長於紅油沙漠的我來說，沒什麼大不了的！",
  ui_story_5040_50401202_1_dialog_content = "咳，咳咳！",
  ui_story_5040_50401202_2_dialog_content = "哎呀，沒想到竟然有些吃力了。",
  ui_story_5040_50401202_3_dialog_content = "這些暗鬼也是為了躲避沙蟲才逃到這裡的嗎？",
  ui_story_5040_50401202_4_dialog_content = "不，牠們並沒有驚慌，不像是來逃難的……",
  ui_story_5040_50401202_5_dialog_content = "呵呵，或許是他們看到了鶴鷹在消耗光能高強度地搜尋，認為現在來偷襲就有機可乘吧。",
  ui_story_5040_50401202_6_dialog_content = "那麼，找到什麼了嗎，我的小鳥？",
  ui_story_5040_50401202_7_dialog_content = "啾！",
  ui_story_5040_50401202_8_dialog_content = "還是沒有嗎……",
  ui_story_5040_50401202_9_dialog_content = "附近沒有沙蟲的蹤跡，牠很可能是利用自己在地下挖出的洞穴逃跑了。",
  ui_story_5040_50401202_10_dialog_content = "如果是那樣的話，亞度尼斯和凱雅他們也很有可能被沙蟲一起卷走了……",
  ui_story_5040_50401202_11_dialog_content = "那他們的情況可就危險了！",
  ui_story_5040_50401202_12_dialog_content = "那隻沙蟲不是他們單獨能對付得了的，地下洞穴錯綜複雜，也容易迷路。",
  ui_story_5040_50401202_13_dialog_content = "得趕快找到他們才行！",
  ui_story_5040_50401202_14_dialog_content = "別擔心，我可以再擴大搜尋範圍，讓鶴鷹搜尋整片沙漠。",
  ui_story_5040_50401202_15_dialog_content = "鶴……咳咳咳，鶴鷹！",
  ui_story_5040_50401202_16_dialog_content = "耶利亞，停下！",
  ui_story_5040_50401202_17_dialog_content = "妳的臉色這麼糟糕，說明妳已經快累倒了！",
  ui_story_5040_50401202_18_dialog_content = "呵呵，可別小看我，空裔小哥，我還沒那麼脆弱。",
  ui_story_5040_50401202_19_dialog_content = "這麼多年以來，不管遇到什麼困難，我都一個人撐過去了。",
  ui_story_5040_50401202_20_dialog_content = "所以這次一定也……",
  ui_story_5040_50401202_21_dialog_content = "向附近的紅油扳手們求助吧。",
  ui_story_5040_50401202_22_dialog_content = "什麼？",
  ui_story_5040_50401202_23_dialog_content = "我們回到臨空者號上去，用通訊裝置向醒山他們求助，拜託紅油扳手的大家幫忙。",
  ui_story_5040_50401202_24_dialog_content = "既然一個人無法找到，那就發動這片沙漠的所有人，一起來找他們吧！",
  ui_story_5040_50401202_25_dialog_content = "妳是信使公會的長老，以妳的身分發出請求的話，大家一定會幫忙的！",
  ui_story_5040_50401202_26_dialog_content = "以我的身分？呵呵，空裔小哥真是天真……",
  ui_story_5040_50401202_27_dialog_content = "我一直以來都是公事公辦，不曾給任何人幫助，也不欠任何人情。",
  ui_story_5040_50401202_28_dialog_content = "少了我這個態度很差的信使，換個更負責任的人來，他們說不定會更開心。",
  ui_story_5040_50401202_29_dialog_content = "妳才不是什麼可有可無的信使！",
  ui_story_5040_50401202_30_dialog_content = "對於紅油沙漠的人來說，信使就是維繫大家的橋樑。",
  ui_story_5040_50401202_31_dialog_content = "我和亞度尼斯之間，很長一段時間以來也是依靠信使公會才能與對方聯繫的。",
  ui_story_5040_50401202_32_dialog_content = "沒錯，人與人之間的關係可不僅僅是那麼簡單的事情。",
  ui_story_5040_50401202_33_dialog_content = "只憑為大家送信這一點，妳肯定就已經與大家締結了很深的聯繫了。",
  ui_story_5040_50401202_34_dialog_content = "……",
  ui_story_5040_50401202_35_dialog_content = "還真是拿你們沒辦法。",
  ui_story_5040_50401202_36_dialog_content = "那就照你說的，向別人請求幫助試試吧。",
  ui_story_5040_50401202_37_dialog_content = "不過我這種需要幫助的時候才想起別人的人，可不指望紅油扳手能有所回應。",
  ui_story_5040_50401202_38_dialog_content = "不試試看怎麼知道。",
  ui_story_5040_50401202_39_dialog_content = "我們快回到臨空者號上吧！",
  ui_story_5040_50401202_40_dialog_content = "先別著急，空裔小哥，我有比你的通訊裝置更快的辦法。",
  ui_story_5040_50401202_41_dialog_content = "欸？",
  ui_story_5040_50401202_42_dialog_content = "這能力會劇烈消耗我的光能，使用後需要積攢很久的力量才能再次發動……",
  ui_story_5040_50401202_43_dialog_content = "但用在這個時候，或許才是最合適的。",
  ui_story_5040_50401202_44_dialog_content = "喂，難道妳還藏著什麼殺手鐧沒有用嗎？",
  ui_story_5040_50401202_45_dialog_content = "這可不是什麼殺手鐧。",
  ui_story_5040_50401202_46_dialog_content = "只不過是為了能及時聯絡上我的小鳥兒們，因此保留的應急手段罷了。",
  ui_story_5040_50401202_47_dialog_content = "使用這個能力，就能透過鶴鷹讓他們幫忙，在短時間內將我的口信帶給附近的紅油扳手們。",
  ui_story_5040_50401202_48_dialog_content = "妳之前沒用過嗎？",
  ui_story_5040_50401202_49_dialog_content = "沒有，所以這是第一次。",
  ui_story_5040_50401202_50_dialog_content = "我的小鳥兒啊，就請你替我將消息傳達給人們吧。",
  ui_story_5040_50401202_51_dialog_content = "啾！",
  ui_story_5040_50401202_52_dialog_content = "去吧！",
  ui_story_5040_50401202_53_dialog_content = "啾——！",
  ui_story_5040_50401202_54_dialog_content = "美麗的小鳥兒，但願你能帶回好消息。",
  ui_story_5040_50401202_55_dialog_content = "<color=#e8d9bb>十幾分鐘後</color>",
  ui_story_5040_50401202_56_dialog_content = "還是沒有回信嗎……",
  ui_story_5040_50401202_57_dialog_content = "就算是我的小鳥兒，送達資訊也需要一點時間。",
  ui_story_5040_50401202_58_dialog_content = "看，牠回來了！",
  ui_story_5040_50401202_59_dialog_content = "真的，是耶利亞的鶴鷹！",
  ui_story_5040_50401202_60_dialog_content = "啾——！",
  ui_story_5040_50401202_61_dialog_content = "鶴鷹的爪子裡好像還抓著什麼，嗚哇，它把那些東西扔下來了？！",
  ui_story_5040_50401202_62_dialog_content = "這是……信？！",
  ui_story_5040_50401202_63_dialog_content = "真的是信！紛紛揚揚落下來的信件，好像雪花一樣……",
  ui_story_5040_50401202_64_dialog_content = "有好多信，裡面還夾著紙條？",
  ui_story_5040_50401202_65_dialog_content = "嗚哇，這張紙是什麼？怎麼上面還有塗鴉？！",
  ui_story_5040_50401202_66_dialog_content = "我看看。",
  ui_story_5040_50401202_67_dialog_content = "哦，這是紅油扳手的聯絡方式，意思是在沙漠的西北部沒有看到類似的人和沙蟲。",
  ui_story_5040_50401202_68_dialog_content = "畢竟又不是所有紅油扳手的成員都會讀書寫字，很多時候就只能靠塗鴉代替了。",
  ui_story_5040_50401202_69_dialog_content = "竟然真的收到了信件……",
  ui_story_5040_50401202_70_dialog_content = "啾！",
  ui_story_5040_50401202_71_dialog_content = "你是說，這些信裡記錄了沙漠各地紅油扳手們對粉紅沙蟲的目擊記錄？！",
  ui_story_5040_50401202_72_dialog_content = "也就是說，只要根據這些紀錄，就能找到那只沙蟲，從而有可能發現被牠卷走的大家吧？",
  ui_story_5040_50401202_73_dialog_content = "嗯……",
  ui_story_5040_50401202_74_dialog_content = "那還等什麼，我們快點看看這些信件吧！",
  ui_story_5040_50401202_75_dialog_content = "尾巴街附近沒有，赤眼谷附近也沒有。",
  ui_story_5040_50401202_76_dialog_content = "靠近啟光的方向沒有……嗯？",
  ui_story_5040_50401202_77_dialog_content = "哎呀，有了。",
  ui_story_5040_50401202_78_dialog_content = "在哪裡？！",
  ui_story_5040_50401202_79_dialog_content = "在南邊，沙漠深處的一片綠洲。",
  ui_story_5040_50401202_80_dialog_content = "那裡原本就是沙蟲活動的區域，偶爾會有紅油扳手的人去那裡狩獵沙蟲。",
  ui_story_5040_50401202_81_dialog_content = "就在剛才，一隊紅油扳手的人看見一隻粉色的沙蟲從地下鑽了出來。",
  ui_story_5040_50401202_82_dialog_content = "我們快去那裡！說不定能找到亞度尼斯的蹤跡！",
  ui_story_5040_50401202_83_dialog_content = "上車！",
  ui_story_5040_50401202_84_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_5040_50401202_85_dialog_content = "嗚啊！！！",
  ui_story_5040_50401202_86_dialog_content = "耶利亞，妳妳妳，妳開慢點！",
  ui_story_5040_50401202_87_dialog_content = "<size=45>空裔小哥——！</size>",
  ui_story_5040_50401202_88_dialog_content = "<size=45>你——說——什——麼——？</size>",
  ui_story_5040_50401202_89_option_content = "妳——開——慢——點——！",
  ui_story_5040_50401202_90_dialog_content = "你說什麼呢，現在可是真正的「時間就是生命」！",
  ui_story_5040_50401202_91_option_content = "不——要——超——速——！",
  ui_story_5040_50401202_92_dialog_content = "哈哈，空裔小哥還真幽默。",
  ui_story_5040_50401202_93_dialog_content = "沙漠裡可沒有限速這一說！",
  ui_story_5040_50401202_94_dialog_content = "吼——！",
  ui_story_5040_50401202_95_dialog_content = "有暗鬼追過來了！",
  ui_story_5040_50401202_96_dialog_content = "我們甩掉牠們！",
  ui_story_5040_50401202_97_dialog_content = "要加速了。空裔小哥，抓緊點，可別被甩出去！",
  ui_story_5040_50401202_98_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_5040_50401301_1_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5040_50401301_2_dialog_content = "啊——！",
  ui_story_5040_50401301_3_dialog_content = "漂亮的漂移，耶利亞！",
  ui_story_5040_50401301_4_dialog_content = "妳的車技就算放在紅油扳手裡，也是數一數二的了！",
  ui_story_5040_50401301_5_dialog_content = "哦？我就當妳是在誇獎我。",
  ui_story_5040_50401301_6_dialog_content = "暗鬼好像已經被遠遠地甩在後面，不見蹤影。",
  ui_story_5040_50401301_7_dialog_content = "既然甩掉了暗鬼，就也沒必要繼續像剛才那樣開了。",
  ui_story_5040_50401301_8_dialog_content = "呼，終於結束了……",
  ui_story_5040_50401301_9_dialog_content = "我們快到了嗎？",
  ui_story_5040_50401301_10_dialog_content = "還要再過一會。",
  ui_story_5040_50401301_11_dialog_content = "沙漠中都是連綿不斷的沙丘，重複的景色很容易讓人失去距離感和方向感。",
  ui_story_5040_50401301_12_dialog_content = "但是有妳在，我就放心了。",
  ui_story_5040_50401301_13_dialog_content = "之前好像也有人說過類似的話？",
  ui_story_5040_50401301_14_dialog_content = "你就放心大膽地跟著她吧，準沒錯！",
  ui_story_5040_50401301_15_dialog_content = "昨天我還對妳有所懷疑，但是現在我願意相信妳。",
  ui_story_5040_50401301_16_dialog_content = "和醒山聯絡的時候，他也對我說，可以放心地信任妳。",
  ui_story_5040_50401301_17_dialog_content = "他是這麼說的？",
  ui_story_5040_50401301_18_dialog_content = "當然，紅油扳手的大家可都相當感謝和信任妳。",
  ui_story_5040_50401301_19_dialog_content = "雖然妳說紅油扳手壞話這點讓我很不爽就是了。",
  ui_story_5040_50401301_20_dialog_content = "是嗎……呵呵，謝謝。",
  ui_story_5040_50401301_21_dialog_content = "對了，PlayerName，昨天的事抱歉了。",
  ui_story_5040_50401301_22_dialog_content = "啊？怎麼突然道歉？",
  ui_story_5040_50401301_23_dialog_content = "昨天你問我要不要找人幫忙的時候，我態度很差地讓你離開了。",
  ui_story_5040_50401301_24_dialog_content = "哦，你是說那件事啊，我完全不在意。",
  ui_story_5040_50401301_25_dialog_content = "不過我不明白，為什麼妳那麼討厭紅油扳手？",
  ui_story_5040_50401301_26_dialog_content = "對啊，耶利亞既然出生在這片沙漠，應該和紅油扳手很熟吧？",
  ui_story_5040_50401301_27_dialog_content = "難道說，有哪些不長眼的傢伙們背著老大的意思，打劫過妳的村子？",
  ui_story_5040_50401301_28_dialog_content = "不，不如說……恰恰相反。我的父母都是紅油扳手的成員，而曾經的我也是。",
  ui_story_5040_50401301_29_dialog_content = "但是，我很早就和我的父母以及紅油扳手斷了聯繫。",
  ui_story_5040_50401301_30_dialog_content = "為什麼？",
  ui_story_5040_50401301_31_dialog_content = "哦？空裔小哥對誰都是這麼刨根問底嗎？",
  ui_story_5040_50401301_32_dialog_content = "對、對不起！如果妳不想說就算了……",
  ui_story_5040_50401301_33_dialog_content = "呵呵，你還真是不經逗。",
  ui_story_5040_50401301_34_dialog_content = "也不是什麼祕密，只不過是因為我沒辦法認同他們的作風罷了。",
  ui_story_5040_50401301_35_dialog_content = "我的父母都是紅油扳手的成員，也和大多數紅油扳手的成員一樣自由不羈。",
  ui_story_5040_50401301_36_dialog_content = "自從我記事起，他們就幾乎沒管過我的生活，只教會我一些在沙漠中求生的知識。",
  ui_story_5040_50401301_37_dialog_content = "剩下的時候，我都是自己一個人生活。",
  ui_story_5040_50401301_38_dialog_content = "一個人？！",
  ui_story_5040_50401301_39_dialog_content = "很難想像嗎？",
  ui_story_5040_50401301_40_option_content = "難以想像",
  ui_story_5040_50401301_41_dialog_content = "嗯……就算是我被困在地下的那麼多年，也有臨空者號一直陪伴著我。",
  ui_story_5040_50401301_42_dialog_content = "每天的生活雖然單調，但是並不孤獨。",
  ui_story_5040_50401301_43_dialog_content = "所以，我沒辦法想像那種生活。",
  ui_story_5040_50401301_44_dialog_content = "還真是令人羡慕的人生啊，空裔小哥。",
  ui_story_5040_50401301_45_dialog_content = "臨空者號一定把你保護得很好吧？",
  ui_story_5040_50401301_46_dialog_content = "是啊，臨空者號是我重要的家人。",
  ui_story_5040_50401301_47_option_content = "不難想像",
  ui_story_5040_50401301_48_dialog_content = "被困在地底的十七年裡，只有臨空者號陪伴著我。",
  ui_story_5040_50401301_49_dialog_content = "臨空者號既是我的老師，又是我的家人。",
  ui_story_5040_50401301_50_dialog_content = "如果那時沒有他的陪伴，我肯定沒辦法成為現在的樣子",
  ui_story_5040_50401301_51_dialog_content = "看來臨空者號是一位不錯的老師。",
  ui_story_5040_50401301_52_dialog_content = "那當然了！",
  ui_story_5040_50401301_53_dialog_content = "你是幸運的，但這不代表所有人都像你一樣幸運。",
  ui_story_5040_50401301_54_dialog_content = "這片沙漠是如此廣袤，廣袤到人與人之間的距離都被拉得像隔著沙海一樣遙遠。",
  ui_story_5040_50401301_55_dialog_content = "或許我的父母在這種環境下生活慣了，就理所應當地認為我也能獨自謀生。",
  ui_story_5040_50401301_56_dialog_content = "在我小的時候，他們幾乎沒管過我，只顧自己隨心所欲地活著。",
  ui_story_5040_50401301_57_dialog_content = "紅油扳手裡，確實偶爾會出現這樣的人……",
  ui_story_5040_50401301_58_dialog_content = "他們確實是一對熱情過頭的父母，我能平安長大，靠的還是吃百家飯。",
  ui_story_5040_50401301_59_dialog_content = "紅油扳手的大家都很熱情，但我還是會羡慕那些被家人時刻關照的孩子。",
  ui_story_5040_50401301_60_dialog_content = "羡慕那些有人可以依靠、可以無憂無慮笑和哭泣的孩子。",
  ui_story_5040_50401301_61_dialog_content = "況且被大家包圍的生活固然熱鬧，但時刻與人相處，也讓我失去了只屬於自己的空間。",
  ui_story_5040_50401301_62_dialog_content = "紅油扳手的氛圍太熱鬧、太激烈，而我只想要一個安靜的環境。",
  ui_story_5040_50401301_63_dialog_content = "所以在某一天，我就決定與我的父母和紅油扳手分道揚鑣，不再是他們的一員了。",
  ui_story_5040_50401301_64_dialog_content = "我不屬於任何勢力，也不與任何人產生交集，只想當一隻自由的鳥兒。",
  ui_story_5040_50401301_65_dialog_content = "而信使公會的工作，對我來說也不過是公事公辦罷了。",
  ui_story_5040_50401301_66_dialog_content = "可妳真的是這麼想的嗎？",
  ui_story_5040_50401301_67_dialog_content = "在我第一次走進你的辦公室時，看到那麼多裝飾，我都嚇了一跳。",
  ui_story_5040_50401301_68_dialog_content = "那些裝飾品不僅到處亂放，還很少收拾，有的布滿灰塵。",
  ui_story_5040_50401301_69_dialog_content = "它們是我重要的同伴，給妳可不行。",
  ui_story_5040_50401301_70_dialog_content = "我對它們一點興趣也沒有，再說了我也不是誰都搶的那種壞人！",
  ui_story_5040_50401301_71_dialog_content = "我只是想說，妳雖然需要它們，但妳其實並不在乎它們，對吧？",
  ui_story_5040_50401301_72_dialog_content = "……",
  ui_story_5040_50401301_73_dialog_content = "妳只是需要那些並非來自紅油扳手的裝飾品，用來證明自己不是紅油扳手的人。",
  ui_story_5040_50401301_74_dialog_content = "但妳自己也不知道，如果妳不屬於紅油扳手，那還能屬於哪裡。",
  ui_story_5040_50401301_75_dialog_content = "（難怪耶利亞的辦公室裡有那麼多花裡胡哨的裝飾品……）",
  ui_story_5040_50401301_76_dialog_content = "（那或許是她為了填補內心的空缺才放上去的吧。）",
  ui_story_5040_50401301_77_dialog_content = "那在妳眼裡，我又是什麼樣子的？",
  ui_story_5040_50401301_78_dialog_content = "雖然妳總是裝成一副高深莫測的樣子，但根本上來說，妳也只是一個缺愛的傢伙而已。",
  ui_story_5040_50401301_79_dialog_content = "妳拒絕了別人的愛，也拒絕去愛別人。",
  ui_story_5040_50401301_80_dialog_content = "難道妳指望一個不知何為愛、也從未感受過愛的人，去愛其他人？",
  ui_story_5040_50401301_81_dialog_content = "我不是這個意思……",
  ui_story_5040_50401301_82_dialog_content = "那個……耶利亞，妳是不是有點自嘲過頭了？",
  ui_story_5040_50401301_83_dialog_content = "自嘲？",
  ui_story_5040_50401301_84_dialog_content = "我不覺得耶利亞是一個不知道什麼是愛的人。",
  ui_story_5040_50401301_85_dialog_content = "妳說自己不知道什麼是愛，但在這趟旅途中，妳確確實實地幫助了塔拉和亞度尼斯。",
  ui_story_5040_50401301_86_dialog_content = "在白夜城的時候，是妳親手教他們該如何賣郵票。",
  ui_story_5040_50401301_87_dialog_content = "也是因為妳，他們才能從蒂娜那裡知道啟光可能有能幫塔拉恢復記憶的人。",
  ui_story_5040_50401301_88_dialog_content = "雖然塔拉是在裝失憶，但妳確實在這其中幫了不少忙。",
  ui_story_5040_50401301_89_dialog_content = "是因為妳也不想看到他們兩個人不歡而散嗎？",
  ui_story_5040_50401301_90_dialog_content = "……",
  ui_story_5040_50401301_91_dialog_content = "我只是覺得，他們這樣跨越一整個艾斯特拉的距離、最終走到一起的情侶很少見。",
  ui_story_5040_50401301_92_dialog_content = "就像是天上飛的鳥兒與住在地洞裡的兔子相愛一樣不可思議。",
  ui_story_5040_50401301_93_dialog_content = "這種故事可不多見，我只是想多聽一會，所以才一時興起跟著他們走了。",
  ui_story_5040_50401301_94_dialog_content = "那妳完全可以只是一路跟隨而不出力吧？",
  ui_story_5040_50401301_95_dialog_content = "但是妳沒有這麼做，而是盡心竭力地幫助他們，哪怕妳自己都不承認。",
  ui_story_5040_50401301_96_dialog_content = "就算過去沒有人好好地愛過妳，但耶利亞妳這麼強大又優秀，未來一定能遇到愛妳的人！",
  ui_story_5040_50401301_97_dialog_content = "是嗎……",
  ui_story_5040_50401301_98_dialog_content = "我不過是個公事公辦的普通信使罷了。",
  ui_story_5040_50401301_99_dialog_content = "不要把自己說得無足輕重！",
  ui_story_5040_50401301_100_dialog_content = "妳是信使，是生活在沙漠中的人們不可或缺的人！",
  ui_story_5040_50401301_101_dialog_content = "妳很重要！",
  ui_story_5040_50401301_102_dialog_content = "……！",
  ui_story_5040_50401301_103_dialog_content = "沒錯！耶利亞，妳很重要！",
  ui_story_5040_50401301_104_dialog_content = "沙漠是殘酷的，想要在這樣的環境裡活下去，大家只能互相依靠、互相扶持。",
  ui_story_5040_50401301_105_dialog_content = "每個光靈都是沙海中航行的一艘小船，而小船是很容易傾覆的。",
  ui_story_5040_50401301_106_dialog_content = "小小的一艘船容易傾覆，但是如果將它們連接起來，就能穩固如山。",
  ui_story_5040_50401301_107_dialog_content = "而讓我們每個人連接起來的，就是信使公會啊！",
  ui_story_5040_50401301_108_dialog_content = "……",
  ui_story_5040_50401301_109_dialog_content = "呵呵，我終於理解，為什麼亞度尼斯願意鼓起勇氣走出北境了。",
  ui_story_5040_50401301_110_dialog_content = "欸？！",
  ui_story_5040_50401301_111_dialog_content = "為什麼啊？",
  ui_story_5040_50401301_112_dialog_content = "這就要你自己去想了，空裔小哥。",
  ui_story_5040_50401301_113_dialog_content = "妳倒是把話說清楚啊！",
  ui_story_5040_50401301_114_dialog_content = "現在可沒時間說其他的事情了。",
  ui_story_5040_50401301_115_dialog_content = "吼——！！！",
  ui_story_5040_50401301_116_dialog_content = "是暗鬼？！從哪裡冒出來的？",
  ui_story_5040_50401301_117_dialog_content = "恐怕是沙蟲鑽出的地下洞穴被暗鬼侵佔、成了暗鬼們的庇護所吧。",
  ui_story_5040_50401301_118_dialog_content = "我們離目的地很近了。",
  ui_story_5040_50401301_119_dialog_content = "一鼓作氣地解決掉牠們吧！",
  ui_story_5040_50401302_1_dialog_content = "<color=#e8d9bb>吱嘎——！</color>",
  ui_story_5040_50401302_2_dialog_content = "這裡就是沙蟲棲息的綠洲嗎？",
  ui_story_5040_50401302_3_dialog_content = "如果這裡沒有被沙蟲佔據的話，或許也能發展成一個聚落吧。",
  ui_story_5040_50401302_4_dialog_content = "但現在這裡只是一片繁茂又荒蕪的綠洲。",
  ui_story_5040_50401302_5_dialog_content = "或許維持現狀也不錯，畢竟這裡環境這麼好。",
  ui_story_5040_50401302_6_dialog_content = "那如果我說，這片美麗湖泊周圍的沙地裡，堆滿了因沙蟲攻擊而死去的動物和光靈的遺骨呢？",
  ui_story_5040_50401302_7_dialog_content = "哇？！",
  ui_story_5040_50401302_8_dialog_content = "在沙漠中，愈是美麗的東西，就會有愈致命的一面。",
  ui_story_5040_50401302_9_dialog_content = "可不要只因為它們的美麗，就忽略了暗藏的危機哦？",
  ui_story_5040_50401302_10_dialog_content = "我、我知道了……",
  ui_story_5040_50401302_11_dialog_content = "真奇怪，這附近並沒有沙蟲的氣息，連一片沙蟲的鱗片都看不見。",
  ui_story_5040_50401302_12_dialog_content = "難道沙蟲們已經搬家了？",
  ui_story_5040_50401302_13_dialog_content = "也有另一種可能——",
  ui_story_5040_50401302_14_dialog_content = "那隻粉色的沙蟲打敗了其他沙蟲，獨佔了這塊綠洲。",
  ui_story_5040_50401302_15_dialog_content = "我們趕快在附近找找那隻沙蟲的蹤影！",
  ui_story_5040_50401302_16_dialog_content = "嗯，看來又要麻煩你了，鶴鷹。",
  ui_story_5040_50401302_17_dialog_content = "啾！",
  ui_story_5040_50401302_18_dialog_content = "那我也用感應能力找找周圍。",
  ui_story_5040_50401302_19_option_content = "強制感應！",
  ui_story_5040_50401302_20_dialog_content = "（拜託了，粉色沙蟲的蹤跡也好，凱雅或者亞度尼斯的氣息也好，請讓我感應到吧……）",
  ui_story_5040_50401302_21_dialog_content = "這是……？",
  ui_story_5040_50401302_22_dialog_content = "耶利亞，塔拉！我感應到凱雅和亞度尼斯了！",
  ui_story_5040_50401302_23_dialog_content = "竟然比鶴鷹還快？",
  ui_story_5040_50401302_24_dialog_content = "他們在哪裡？！",
  ui_story_5040_50401302_25_dialog_content = "這邊！",
  ui_story_5040_50401302_26_dialog_content = "在哪裡呢？這邊明明只有一片灌木叢，別的什麼都沒有……",
  ui_story_5040_50401302_27_dialog_content = "我感應到的不會有錯，他們應該就在附近，只是好像陷入了昏迷一樣沒有回音。",
  ui_story_5040_50401302_28_dialog_content = "喂——！",
  ui_story_5040_50401302_29_dialog_content = "凱雅——！亞度尼斯——！小黑——！",
  ui_story_5040_50401302_30_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5040_50401302_31_dialog_content = "等等，那邊的灌木很奇怪。這個品種的灌木應該向上生長，但這些卻倒伏在地。",
  ui_story_5040_50401302_32_dialog_content = "這像是人為弄出的痕跡，這是……",
  ui_story_5040_50401302_33_dialog_content = "亞度尼斯？！",
  ui_story_5040_50401302_34_dialog_content = "還有凱雅！但是小黑呢？",
  ui_story_5040_50401302_35_dialog_content = "他們還有呼吸，只是昏過去了而已。",
  ui_story_5040_50401302_36_dialog_content = "亞度尼斯，醒醒！",
  ui_story_5040_50401302_37_dialog_content = "呃……我、我這是……",
  ui_story_5040_50401302_38_dialog_content = "你沒事，真是太好了！",
  ui_story_5040_50401302_39_dialog_content = "呃！輕點，塔拉，我的肋骨要斷了，也或許它已經斷了……",
  ui_story_5040_50401302_40_dialog_content = "抱歉，我只是有點太開心了，你真的沒事。",
  ui_story_5040_50401302_41_dialog_content = "你還記得自己是怎麼到這裡的嗎？小黑沒和你們在一起？",
  ui_story_5040_50401302_42_dialog_content = "讓我想一想……",
  ui_story_5040_50401302_43_dialog_content = "我只記得那時候刮著猛烈的沙暴，地面也開始下陷，粉色沙蟲向我衝了過來……",
  ui_story_5040_50401302_44_dialog_content = "我嚇壞了，為了不被流沙和狂風卷走，只能死死抱住沙蟲，抓住它的鱗片。",
  ui_story_5040_50401302_45_dialog_content = "然後我就被沙蟲帶進了一個像是地洞一樣、非常黑的地方。",
  ui_story_5040_50401302_46_dialog_content = "我大聲喊著凱雅和小黑的名字，但是沒有回應。",
  ui_story_5040_50401302_47_dialog_content = "這時沙蟲不停地撲騰，我也不敢放手，直到最後暈了過去。",
  ui_story_5040_50401302_48_dialog_content = "再遇到沙蟲，可不能像這次一樣掛在它身上。",
  ui_story_5040_50401302_49_dialog_content = "這是非常危險的行為，你能活下來，也算是你命大。",
  ui_story_5040_50401302_50_dialog_content = "我、我這不是因為沒有對付沙蟲的經驗嗎……",
  ui_story_5040_50401302_51_dialog_content = "總之，你還活著，這已經是最好的結果了。",
  ui_story_5040_50401302_52_dialog_content = "嗯，我也很慶幸。",
  ui_story_5040_50401302_53_dialog_content = "對了，還有這個！",
  ui_story_5040_50401302_54_dialog_content = "這是那隻沙蟲的鱗片？！",
  ui_story_5040_50401302_55_dialog_content = "嗯！這是我被那只沙蟲帶著到處跑的時候，偶然從牠身上拽下來的一片鱗。",
  ui_story_5040_50401302_56_dialog_content = "不過只有一片，希望它夠用。",
  ui_story_5040_50401302_57_dialog_content = "（但其實塔拉根本就沒有失憶，要不要告訴亞度尼斯呢？）",
  ui_story_5040_50401302_58_dialog_content = "亞度尼斯，其實，有一件事，我要對你承認……",
  ui_story_5040_50401302_59_dialog_content = "嗯？怎麼了，塔拉？",
  ui_story_5040_50401302_60_dialog_content = "我沒有失憶。",
  ui_story_5040_50401302_61_dialog_content = "這一切都是我假裝出來的，只是想要考驗你，希望你能鼓起勇氣走出北境……",
  ui_story_5040_50401302_62_dialog_content = "塔拉，妳不應該這樣做……",
  ui_story_5040_50401302_63_dialog_content = "對不起……",
  ui_story_5040_50401302_64_dialog_content = "我不應該擅作主張，強迫你走出北境，甚至讓你面對生命危險，你想怎麼埋怨我都可以。",
  ui_story_5040_50401302_65_dialog_content = "我不會再強迫你到不熟悉的環境中生活了，我們……以後就一直在北境居住吧。",
  ui_story_5040_50401302_66_dialog_content = "但一直居住在北境這麼交通不便的地方，妳還怎麼去各地的遺跡探險？",
  ui_story_5040_50401302_67_dialog_content = "我……我不去了。",
  ui_story_5040_50401302_68_dialog_content = "與那些遺跡相比，還是你更重要。",
  ui_story_5040_50401302_69_dialog_content = "……",
  ui_story_5040_50401302_70_dialog_content = "我生氣了。",
  ui_story_5040_50401302_71_dialog_content = "欸？！",
  ui_story_5040_50401401_1_dialog_content = "我非常、非常地生氣。",
  ui_story_5040_50401401_2_dialog_content = "對不起……",
  ui_story_5040_50401401_3_dialog_content = "比起道歉，我希望妳能好好聽我說清楚生氣的原因。",
  ui_story_5040_50401401_4_dialog_content = "過去的我十分懦弱，連北境都不敢踏出一步，更別提面對暗鬼了。",
  ui_story_5040_50401401_5_dialog_content = "為了讓這樣的我鼓起勇氣，想必妳也已經走投無路了吧。",
  ui_story_5040_50401401_6_dialog_content = "亞度尼斯……",
  ui_story_5040_50401401_7_dialog_content = "所以，你並不是因為她假裝失憶才生氣的。",
  ui_story_5040_50401401_8_dialog_content = "是的，我昨晚就已經察覺到了塔拉在假裝失憶，但我並不生氣。",
  ui_story_5040_50401401_9_dialog_content = "倒不如說知道這件事的時候，我整個人都松了一口氣。",
  ui_story_5040_50401401_10_dialog_content = "因為我終於確認塔拉並不是因為討厭我才想忘記我的。",
  ui_story_5040_50401401_11_dialog_content = "那你到底是為什麼生氣啊？",
  ui_story_5040_50401401_12_dialog_content = "是因為「妥協」吧？",
  ui_story_5040_50401401_13_dialog_content = "「妥協」？妥協什麼？",
  ui_story_5040_50401401_14_dialog_content = "不愧是耶利亞小姐，一下子就把我看穿了。",
  ui_story_5040_50401401_15_dialog_content = "這到底是什麼和什麼啊？能不能別再說謎語了？",
  ui_story_5040_50401401_16_dialog_content = "我在生氣的是，塔拉剛才竟然說會放棄前往世界各地探險，只為了在北境陪我。",
  ui_story_5040_50401401_17_option_content = "你不希望塔拉被束縛？",
  ui_story_5040_50401401_18_dialog_content = "沒錯！",
  ui_story_5040_50401401_19_option_content = "難道你討厭塔拉？",
  ui_story_5040_50401401_20_dialog_content = "怎麼可能！我一點也不討厭塔拉。",
  ui_story_5040_50401401_21_dialog_content = "我太瞭解塔拉的性格了，我知道她不可能心甘情願地在北境度過平靜的一生。",
  ui_story_5040_50401401_22_dialog_content = "就算塔拉現在說願意陪我留在北境，我也清楚地知道，那是她的妥協，她的退讓。",
  ui_story_5040_50401401_23_dialog_content = "我不希望她因為我而委屈自己！",
  ui_story_5040_50401401_24_dialog_content = "亞度尼斯？你……",
  ui_story_5040_50401401_25_dialog_content = "我喜歡的，一直是那個敢於去各地冒險、探索遺跡的塔拉。",
  ui_story_5040_50401401_26_dialog_content = "也是因為塔拉，一直居住在北境的我才能認識到艾斯特拉有多寬廣。",
  ui_story_5040_50401401_27_dialog_content = "我到現在還記得，你跟我講述從紅油沙漠看向啟光防線時地平線上蜿蜒的城牆剪影。",
  ui_story_5040_50401401_28_dialog_content = "還有站在白夜城俯瞰艾斯特拉時看到的山脈和平原，以及腳下變幻的雲彩……",
  ui_story_5040_50401401_29_dialog_content = "噗……之後是不是還有我被誤認為成小偷、被白夜城的士兵纏住的事？",
  ui_story_5040_50401401_30_dialog_content = "那次還真是麻煩啊，我還義務陪他們抓了半天小偷。",
  ui_story_5040_50401401_31_dialog_content = "哈哈哈，是啊，不過最後還是抓到了，多虧妳眼神好、跑得快。",
  ui_story_5040_50401401_32_dialog_content = "我為了自證清白，可是相當努力的！",
  ui_story_5040_50401401_33_dialog_content = "其實，說了這麼多，我只是想說——",
  ui_story_5040_50401401_34_dialog_content = "塔拉，在我遇到妳之前，我的世界是一片雪一樣的白色。",
  ui_story_5040_50401401_35_dialog_content = "是妳給我一成不變的生活裡帶來了珍貴的色彩。",
  ui_story_5040_50401401_36_dialog_content = "我愛著這樣的妳，所以不希望因此束縛住妳，讓你沒辦法自由地探索世界。",
  ui_story_5040_50401401_37_dialog_content = "我會努力鼓起勇氣，與妳同行！",
  ui_story_5040_50401401_38_dialog_content = "<size=45>亞度尼斯——！</size>",
  ui_story_5040_50401401_39_dialog_content = "疼——！好疼，輕點！！！",
  ui_story_5040_50401401_40_dialog_content = "原來他們是這樣想的啊。",
  ui_story_5040_50401401_41_dialog_content = "就算是擁有感應能力、能夠看穿想法的空裔，也不一定能準確地理解他人的內心。",
  ui_story_5040_50401401_42_dialog_content = "我的感應能力也不是萬能的！",
  ui_story_5040_50401401_43_dialog_content = "是啊，所以人們之間才會有誤會，而誤會又會帶來隔閡，斬斷人們之間的聯繫。",
  ui_story_5040_50401401_44_dialog_content = "但是，如果人們能通過互相理解打破這層隔閡，重新締結聯繫——",
  ui_story_5040_50401401_45_dialog_content = "那麼這聯繫就會變得更加穩固，牢不可破。",
  ui_story_5040_50401401_46_dialog_content = "唔……這裡怎麼這麼吵……？",
  ui_story_5040_50401401_47_dialog_content = "凱雅，妳終於醒了！",
  ui_story_5040_50401401_48_dialog_content = "PlayerName，耶利亞長老？還有塔拉和亞度尼斯，他們和好了？",
  ui_story_5040_50401401_49_dialog_content = "他們經歷了一些事，不過終於和好了！",
  ui_story_5040_50401401_50_dialog_content = "那真是太好了，我和小黑被沙蟲卷走的時候，還很擔心亞度尼斯的安危呢。",
  ui_story_5040_50401401_51_dialog_content = "對了，小黑呢？她在哪裡？",
  ui_story_5040_50401401_52_dialog_content = "我們來到這裡以後只看到昏迷的妳和亞度尼斯，沒有看到小黑，我也沒感應到她在附近。",
  ui_story_5040_50401401_53_dialog_content = "妳還記得暈過去之前發生了什麼嗎？",
  ui_story_5040_50401401_54_dialog_content = "我、我只記得自己和小黑一起被沙暴卷到了半空中，小黑好像抓住了沙蟲的角。",
  ui_story_5040_50401401_55_dialog_content = "在那之後，我們就和沙蟲一起鑽進地底，我的頭撞到地底的石頭，暈了過去。",
  ui_story_5040_50401401_56_dialog_content = "如果凱雅暈過去了的話，又是誰把妳和亞度尼斯藏在這裡的？",
  ui_story_5040_50401401_57_dialog_content = "難道是……",
  ui_story_5040_50401401_58_dialog_content = "小黑？！",
  ui_story_5040_50401401_59_dialog_content = "但如果是小黑把他們藏起來的，為什麼她沒有在附近？",
  ui_story_5040_50401401_60_dialog_content = "或許是她想一個人引開沙蟲，保護凱雅他們的安全，也可能是因為——",
  ui_story_5040_50401401_61_dialog_content = "她感覺到自己快到極限了。",
  ui_story_5040_50401401_62_dialog_content = "極限？你們又在商量什麼我聽不懂的話？",
  ui_story_5040_50401401_63_dialog_content = "PlayerName，其實小黑並不是光靈，或者說，她曾經是光靈。",
  ui_story_5040_50401401_64_dialog_content = "欸？！",
  ui_story_5040_50401401_65_dialog_content = "果然……",
  ui_story_5040_50401401_66_dialog_content = "空裔小哥看起來一點也不驚訝。",
  ui_story_5040_50401401_67_dialog_content = "我在半路上就多多少少察覺了一點，雖然一直沒有證據……",
  ui_story_5040_50401401_68_dialog_content = "她曾經被自己的戀人拋棄，在絕望的時候受到了暗鬼的誘惑，變成了像是暗鬼的樣子。",
  ui_story_5040_50401401_69_dialog_content = "她雖然外表發生變化，內心也受到影響，但是她自己的意志一直在與破壞的衝動抗爭。",
  ui_story_5040_50401401_70_dialog_content = "但她之前告訴我，她已經快堅持不住了……",
  ui_story_5040_50401401_71_dialog_content = "怎麼會這樣……",
  ui_story_5040_50401401_72_dialog_content = "（這種情況，似乎也在其他冒險途中見到過……）",
  ui_story_5040_50401401_73_dialog_content = "PlayerName，你覺得小黑是一個怎樣的人？",
  ui_story_5040_50401401_74_option_content = "是一個好人",
  ui_story_5040_50401401_75_dialog_content = "就算她的樣子有些奇怪，但她對大家都很友好，所以我認為她是一個好人。",
  ui_story_5040_50401401_76_dialog_content = "她現在身處困境，我們應該向她伸出援手。",
  ui_story_5040_50401401_77_option_content = "我和她不熟……",
  ui_story_5040_50401401_78_dialog_content = "她好像有點害羞，我幾乎沒和她說過話，但是這不妨礙我認為她是一個善良的人！",
  ui_story_5040_50401401_79_dialog_content = "如果她不介意的話，我願意和她成為朋友。",
  ui_story_5040_50401401_80_dialog_content = "那我們就全力去尋找小黑吧。",
  ui_story_5040_50401401_81_dialog_content = "嗯！",
  ui_story_5040_50401401_82_dialog_content = "啾——！",
  ui_story_5040_50401401_83_dialog_content = "看起來我的小鳥兒帶回了消息，真是辛苦你了。",
  ui_story_5040_50401401_84_dialog_content = "啾，啾！",
  ui_story_5040_50401401_85_dialog_content = "你是說，你發現小黑的蹤跡了？",
  ui_story_5040_50401401_86_dialog_content = "她在哪裡？！",
  ui_story_5040_50401401_87_dialog_content = "啾——",
  ui_story_5040_50401401_88_dialog_content = "你是說，她在我們腳下？",
  ui_story_5040_50401401_89_dialog_content = "腳下？",
  ui_story_5040_50401401_90_dialog_content = "我好像確實感應到了腳下有一股微弱的暗能在靠近……",
  ui_story_5040_50401401_91_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_5040_50401401_92_dialog_content = "嗚啊？！這個震動，難道是沙蟲？！",
  ui_story_5040_50401401_93_dialog_content = "<size=45>吼——！！！</size>",
  ui_story_5040_50401401_94_dialog_content = "塔拉，小心！",
  ui_story_5040_50401401_95_dialog_content = "呵呵，牠果然還在附近。",
  ui_story_5040_50401401_96_dialog_content = "<size=45>吼——！</size>",
  ui_story_5040_50401401_97_dialog_content = "好像有什麼東西追著沙蟲從地下冒出來了，那是……小黑？！",
  ui_story_5040_50401401_98_dialog_content = "不會，讓你，過去！",
  ui_story_5040_50401401_99_dialog_content = "小黑？！那個樣子，和暗鬼……",
  ui_story_5040_50401401_100_dialog_content = "不管是暗鬼還是別的什麼，現在她都是站在我們這邊的。",
  ui_story_5040_50401401_101_dialog_content = "PlayerName，請你幫幫她！",
  ui_story_5040_50401401_102_dialog_content = "……",
  ui_story_5040_50401401_103_dialog_content = "我知道了，我會幫忙。",
  ui_story_5040_50401401_104_dialog_content = "準備好了嗎，空裔小哥？讓我們去解決掉這個粉色的麻煩吧。",
  ui_story_5040_50401401_105_dialog_content = "妳沒事嗎？已經連續戰鬥了這麼久，還消耗了那麼多光能。",
  ui_story_5040_50401401_106_dialog_content = "呵呵，空裔小哥還真會關心人。",
  ui_story_5040_50401401_107_dialog_content = "不用擔心，在開車趕來這裡的時候，我就已經趁機恢復了一些光能。",
  ui_story_5040_50401401_108_dialog_content = "我們走吧。",
  ui_story_5040_50401401_109_dialog_content = "嗯，那就上吧，去幫小黑！",
  ui_story_5040_50401402_1_dialog_content = "我的記憶，已經非常模糊了。",
  ui_story_5040_50401402_2_dialog_content = "它們像是被剪碎的膠片，在我的腦海中浮沉，偶爾閃過不完整的片段。",
  ui_story_5040_50401402_3_dialog_content = "我最初的記憶是關於一片廣袤的沙漠，我在這裡出生、成長……",
  ui_story_5040_50401402_4_dialog_content = "在收到信使寄來的那封信前，我以為自己只是芸芸眾生中最普通的一個。",
  ui_story_5040_50401402_5_dialog_content = "是那封信讓我認識到了沙漠之外瑰麗的世界，認識了「那個人」。",
  ui_story_5040_50401402_6_dialog_content = "我已經忘了他的名字，卻還記得那份隨著一封封信而逐漸加深的，戀慕。",
  ui_story_5040_50401402_7_dialog_content = "所以，當我透過信件向他表白心意，並被他接受的時候……",
  ui_story_5040_50401402_8_dialog_content = "歡喜與雀躍幾乎要溢出我的心。",
  ui_story_5040_50401402_9_dialog_content = "也是從那時開始，我收到的他的回信開始漸漸變少。",
  ui_story_5040_50401402_10_dialog_content = "我以為是自己的信不夠真誠，於是便隨信附上禮物。",
  ui_story_5040_50401402_11_dialog_content = "起初是沙漠中難以尋找的鮮花和稀有的古代遺物。",
  ui_story_5040_50401402_12_dialog_content = "然後慢慢增加、變得貴重，最終變成白夜幣。",
  ui_story_5040_50401402_13_dialog_content = "但他的回信卻更加少了起來，回信的內容也變成了索要更多禮物。",
  ui_story_5040_50401402_14_dialog_content = "我很不解，但仍然沒有懷疑他，而是想要與他見面，於是，他在信中告訴了我一個地址。",
  ui_story_5040_50401402_15_dialog_content = "我鼓起勇氣，第一次走出沙漠。",
  ui_story_5040_50401402_16_dialog_content = "順著那一封封信件，我追到了啟光……",
  ui_story_5040_50401402_17_dialog_content = "追到了白夜城……",
  ui_story_5040_50401402_18_dialog_content = "最終追到鏡湖邊。",
  ui_story_5040_50401402_19_dialog_content = "那個人說，他在北境為我準備了盛大的婚禮。",
  ui_story_5040_50401402_20_dialog_content = "但哪裡都沒有他的身影。",
  ui_story_5040_50401402_21_dialog_content = "我絕望地哭泣著，不知道該去哪裡，也不知道還能不能回家。",
  ui_story_5040_50401402_22_dialog_content = "那時，有人對我說……",
  ui_story_5040_50401402_23_dialog_content = "收下這顆「種子」吧，它會給予你實現自己願望的力量。",
  ui_story_5040_50401402_24_dialog_content = "我寄希望於「種子」，但卻沒想到，因此失去了一切。",
  ui_story_5040_50401402_25_dialog_content = "我失去了記憶和思考的能力，淪為野獸一樣的怪物、四處遊蕩……",
  ui_story_5040_50401402_26_dialog_content = "直到我看到亞度尼斯和塔拉，他們用行動告訴我，世界上還存在著愛。",
  ui_story_5040_50401402_27_dialog_content = "還有凱雅，我在她身上看到了對責任和承諾的重視。",
  ui_story_5040_50401402_28_dialog_content = "我還遇到了耶利亞，她雖然看起來對人漠不關心，但其實非常可靠。",
  ui_story_5040_50401402_29_dialog_content = "我在她身上看到了自由的樣子。",
  ui_story_5040_50401402_30_dialog_content = "所以，現在我能做的，就只剩下一件事……",
  ui_story_5040_50401402_31_dialog_content = "我，不會，讓你，過去！",
  ui_story_5040_50401402_32_dialog_content = "<size=45>吼——！！！</size>",
  ui_story_5040_50401402_33_dialog_content = "呃——！",
  ui_story_5040_50401402_34_dialog_content = "小黑！",
  ui_story_5040_50401402_35_dialog_content = "那只沙蟲好像要咬小黑！耶利亞，快攻擊牠的頭，分散牠的注意力！",
  ui_story_5040_50401402_36_dialog_content = "不要，管我！",
  ui_story_5040_50401402_37_dialog_content = "弱點，機會！",
  ui_story_5040_50401402_38_dialog_content = "……",
  ui_story_5040_50401402_39_dialog_content = "我知道了。",
  ui_story_5040_50401402_40_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5040_50401402_41_dialog_content = "吼……",
  ui_story_5040_50401402_42_dialog_content = "呃！",
  ui_story_5040_50401402_43_dialog_content = "（沙蟲被打倒了……）",
  ui_story_5040_50401402_44_dialog_content = "（耶利亞的光能術精準地命中了沙蟲的舊傷，將牠貫穿了。）",
  ui_story_5040_50401402_45_dialog_content = "（但是小黑她也被沙蟲重重咬了一口，並被甩飛了出去……）",
  ui_story_5040_50401402_46_dialog_content = "小黑！妳沒事吧？！",
  ui_story_5040_50401402_47_dialog_content = "痛……",
  ui_story_5040_50401402_48_dialog_content = "小黑，小黑！清醒一點！",
  ui_story_5040_50401402_49_dialog_content = "這傷也太重了？！",
  ui_story_5040_50401402_50_dialog_content = "就算是生命力頑強的暗鬼，恐怕也……",
  ui_story_5040_50401402_51_dialog_content = "讓我試試用光能術治療！",
  ui_story_5040_50401402_52_dialog_content = "怎麼可能，完全沒有效果……",
  ui_story_5040_50401402_53_dialog_content = "沒用的，那已經不是你的光能術能治好的傷口了……",
  ui_story_5040_50401402_54_dialog_content = "耶利亞長老！為什麼你剛才不救她？！",
  ui_story_5040_50401402_55_dialog_content = "我只是完成了她的請求而已。",
  ui_story_5040_50401402_56_dialog_content = "妳自己也清楚吧，就算我剛才救下她，用不了多久，她也會變回沒有意識的怪物。",
  ui_story_5040_50401402_57_dialog_content = "……",
  ui_story_5040_50401402_58_dialog_content = "凱雅……",
  ui_story_5040_50401402_59_dialog_content = "小黑，我在這裡！",
  ui_story_5040_50401402_60_dialog_content = "請，不要，責怪耶利亞。",
  ui_story_5040_50401402_61_dialog_content = "是我自己，害怕，傷害你們，所以決定離開。但是，遇到沙蟲……",
  ui_story_5040_50401402_62_dialog_content = "能在最後，與你，與你們，相遇……",
  ui_story_5040_50401402_63_dialog_content = "最後，能想起，我，曾是光靈……",
  ui_story_5040_50401402_64_dialog_content = "很開心。",
  ui_story_5040_50401402_65_dialog_content = "可是，我還沒有帶妳回家，我還沒有完成妳的委託！",
  ui_story_5040_50401402_66_dialog_content = "那我，更改，委託。",
  ui_story_5040_50401402_67_dialog_content = "請把，這個，帶回我的家……",
  ui_story_5040_50401402_68_dialog_content = "請妳……替我向，家人，道歉……",
  ui_story_5040_50401402_69_dialog_content = "……",
  ui_story_5040_50401402_70_dialog_content = "我，信使公會的信使凱雅，接受妳的委託。",
  ui_story_5040_50401402_71_dialog_content = "信使公會，使命必達！",
  ui_story_5040_50401402_72_dialog_content = "那就，拜託妳了。",
  ui_story_5040_50401402_73_dialog_content = "小黑……嗚……",
  ui_story_5040_50401402_74_dialog_content = "凱雅，別太傷心了……",
  ui_story_5040_50401402_75_dialog_content = "我、我去給凱雅拿紙巾擦眼淚。",
  ui_story_5040_50401402_76_dialog_content = "……",
  ui_story_5040_50401402_77_dialog_content = "哭吧，盡情地哭出來。",
  ui_story_5040_50401402_78_dialog_content = "然後這份悲傷就會成為妳的動力。",
  ui_story_5040_50401402_79_dialog_content = "耶利亞……？",
  ui_story_5040_50401402_80_dialog_content = "妳還好嗎？怎麼突然離開了？",
  ui_story_5040_50401402_81_dialog_content = "就算是我，也需要一些時間調整心情呀，空裔小哥。",
  ui_story_5040_50401402_82_dialog_content = "呃，抱歉，我總是下意識地把耶利亞當成任何場合都能輕鬆應對的人。",
  ui_story_5040_50401402_83_dialog_content = "呵呵，謝謝你的讚美，空裔小哥。",
  ui_story_5040_50401402_84_dialog_content = "其實，我很早就知道，小黑已經走不了多遠了。",
  ui_story_5040_50401402_85_dialog_content = "我以為能像過去那樣置身事外，但是這一次好像不行呢。",
  ui_story_5040_50401402_86_dialog_content = "妳之前就看穿她的身分了？為什麼沒有告訴大家呢？",
  ui_story_5040_50401402_87_dialog_content = "我為什麼要告訴大家呢？",
  ui_story_5040_50401402_88_dialog_content = "唔……如果告訴我和塔拉他們，我們就能提供更多幫助。",
  ui_story_5040_50401402_89_dialog_content = "如果是塔拉和亞度尼斯的話，一定不會排斥她的。",
  ui_story_5040_50401402_90_dialog_content = "他們確實沒問題，但是，別的人呢？",
  ui_story_5040_50401402_91_dialog_content = "一個祕密，知道的人越多，就越容易被洩露。",
  ui_story_5040_50401402_92_dialog_content = "更何況這個世界上，與暗鬼有仇的光靈並不在少數。",
  ui_story_5040_50401402_93_dialog_content = "而那隻小鳥，已經向著無法回頭的風暴深處飛得太遠了。",
  ui_story_5040_50401402_94_dialog_content = "她的祕密一旦暴露，或許會為她珍貴的「最後一程」帶來不必要的麻煩吧。",
  ui_story_5040_50401402_95_dialog_content = "妳說得對……",
  ui_story_5040_50401402_96_dialog_content = "所以，空裔小哥，你要認清一件事。",
  ui_story_5040_50401402_97_dialog_content = "人與人之間的聯繫固然重要，但這種聯繫有時並不是愈多、愈緊密就愈好的。",
  ui_story_5040_50401402_98_dialog_content = "很多時候，適當地保持距離、保守祕密，才是更好的選擇。",
  ui_story_5040_50401402_99_dialog_content = "要讓這份聯繫成為托著鳥兒飛翔的風，而不是纏住鳥兒翅膀的網。",
  ui_story_5040_50401402_100_dialog_content = "嗯……",
  ui_story_5040_50401402_101_dialog_content = "耶利亞長老，我回來了。",
  ui_story_5040_50401402_102_dialog_content = "哭了那麼長時間，給大家添麻煩了……",
  ui_story_5040_50401402_103_dialog_content = "這有什麼麻煩的？不要總是把情緒憋在心裡，該表露出來的時候就要好好說。",
  ui_story_5040_50401402_104_dialog_content = "塔拉說得沒錯。",
  ui_story_5040_50401402_105_dialog_content = "看起來妳已經下定決心了，凱雅。",
  ui_story_5040_50401402_106_dialog_content = "嗯，我不會再哭了，因為我還有我的使命，小黑委託我將這枚郵票送回她的家鄉。",
  ui_story_5040_50401402_107_dialog_content = "雖然一時沒辦法找到，不過，在一切結束以後，我會向長老申請調到紅油扳手分部工作。",
  ui_story_5040_50401402_108_dialog_content = "我會一邊工作，一邊熟悉沙漠的環境，尋找小黑的故鄉。",
  ui_story_5040_50401402_109_dialog_content = "哪怕要探訪整片紅油沙漠，我也不會放棄。",
  ui_story_5040_50401402_110_dialog_content = "不論遷徙的路再長，有了目標的鳥兒也能堅持下去，是嗎？",
  ui_story_5040_50401402_111_dialog_content = "嗯！",
  ui_story_5040_50401402_112_dialog_content = "那你們呢？",
  ui_story_5040_50401402_113_dialog_content = "我已經再次確認了，我是真心地愛著亞度尼斯。",
  ui_story_5040_50401402_114_dialog_content = "這份心意不需要任何考驗就能證明。",
  ui_story_5040_50401402_115_dialog_content = "我也確認了，外面的世界雖然危險，卻並不向我想像中的那樣可怕。",
  ui_story_5040_50401402_116_dialog_content = "過去的我所懼怕的也並不是外面，而是未知。",
  ui_story_5040_50401402_117_dialog_content = "現在，在塔拉的幫助下，我已經克服了這份恐懼。",
  ui_story_5040_50401402_118_dialog_content = "我也不會再強迫亞度尼斯做他能力之外的事了。",
  ui_story_5040_50401402_119_dialog_content = "雖然這次繞了個大圈子，還遇到了不少危險、留下了一些遺憾……",
  ui_story_5040_50401402_120_dialog_content = "但還好最後你們兩個人又互相理解了。",
  ui_story_5040_50401402_121_dialog_content = "這也算是不幸之中的萬幸吧。",
  ui_story_5040_50401402_122_dialog_content = "不過，要是亞度尼斯沒有順利拿到鱗片，考驗失敗了，那塔拉妳會怎麼做呢？",
  ui_story_5040_50401402_123_dialog_content = "難道要一直假裝失憶下去嗎？",
  ui_story_5040_50401402_124_dialog_content = "這個問題啊……",
  ui_story_5040_50401402_125_dialog_content = "我猜，妳一定準備了其他的對策吧？",
  ui_story_5040_50401402_126_dialog_content = "嗯，還真是什麼事都瞞不住妳。",
  ui_story_5040_50401402_127_dialog_content = "怎麼還有一片鱗片？！",
  ui_story_5040_50401402_128_dialog_content = "這片鱗片就是最初醒山打下來的那一片，我用高價在拍賣行把它拍了下來。",
  ui_story_5040_50401402_129_dialog_content = "是、是妳買下來的？！",
  ui_story_5040_50401402_130_dialog_content = "難怪你在第一時間就確認了那瓶魔藥是假的，因為靈媒所說的原材料就在妳手裡。",
  ui_story_5040_50401402_131_dialog_content = "不僅如此，只是「萬能魔藥」這個名頭就已經足夠離譜了。",
  ui_story_5040_50401402_132_dialog_content = "也只有你這樣一時衝動又單純的傢伙會上當了吧。",
  ui_story_5040_50401402_133_dialog_content = "我、我……唔……",
  ui_story_5040_50401402_134_dialog_content = "其實最開始我決定假裝失憶的時候，就考慮好了這種情況。",
  ui_story_5040_50401402_135_dialog_content = "如果亞度尼斯沒有完成考驗……",
  ui_story_5040_50401402_135X1_dialog_content = "我就會把這片鱗片給耶利亞，讓她用「別的方法」使我們獲得鱗片。",
  ui_story_5040_50401402_136_dialog_content = "原來是這樣，那妳當初為什麼要買下這枚鱗片呢？",
  ui_story_5040_50401402_137_dialog_content = "……！",
  ui_story_5040_50401402_138_dialog_content = "因為是稀有的沙蟲鱗片，而且是粉色的，所以我就……",
  ui_story_5040_50401402_139_dialog_content = "我希望把這件新奇的事情跟亞度尼斯分享，衝動之下就把這枚鱗片買了下來。",
  ui_story_5040_50401402_140_dialog_content = "我本來想請工匠把它打造成結婚戒指，給亞度尼斯佩戴。",
  ui_story_5040_50401402_141_dialog_content = "哦？這倒是個新奇的想法，也不枉這隻沙蟲長了這麼漂亮的粉色鱗片。",
  ui_story_5040_50401402_142_dialog_content = "不過，這片鱗只有靠近中間的一小塊足夠堅硬，恐怕只夠打造一枚戒指吧？",
  ui_story_5040_50401402_143_dialog_content = "如果不是這次真的打倒了沙蟲，這單獨的一枚給了亞度尼斯，妳自己怎麼辦？",
  ui_story_5040_50401402_144_dialog_content = "這……我倒是沒想好。",
  ui_story_5040_50401402_145_dialog_content = "不過不重要啦，隨便找點材料打造就好了。",
  ui_story_5040_50401402_146_dialog_content = "塔拉從過去開始就一直不太在意自己，不過這可不行。",
  ui_story_5040_50401402_147_dialog_content = "結婚戒指還是成雙成對的比較好，更何況——",
  ui_story_5040_50401402_148_dialog_content = "我們現在有很多枚粉色鱗片了。",
  ui_story_5040_50401402_149_dialog_content = "<color=#e8d9bb>吱嘎——</color>",
  ui_story_5040_50401402_150_dialog_content = "沙蟲呢？沙蟲在哪裡？",
  ui_story_5040_50401402_151_dialog_content = "冷靜點，黑潮。你看那邊。",
  ui_story_5040_50401402_152_dialog_content = "還真的有粉色的沙蟲！但是完全不動了……",
  ui_story_5040_50401402_153_dialog_content = "這不就是死了嗎？！",
  ui_story_5040_50401402_154_dialog_content = "弗勞爾，黑潮？你們怎麼在這裡？",
  ui_story_5040_50401402_155_dialog_content = "啊，原來是PlayerName，你沒事真是太好了。",
  ui_story_5040_50401402_156_dialog_content = "我從醒山那裡聽說你們在找一隻粉色的沙蟲後，就有些擔心。",
  ui_story_5040_50401402_157_dialog_content = "所以就馬上趕過來想要幫忙，不過現在似乎不需要了。",
  ui_story_5040_50401402_158_dialog_content = "哦？看來紅油扳手也有熱心的傢伙，可惜……你來得太晚了。",
  ui_story_5040_50401402_159_dialog_content = "是啊……如果下次你們需要幫助的話，我們會儘快趕到的。",
  ui_story_5040_50401402_160_dialog_content = "既然你們自己解決了問題，那我們也先走了。",
  ui_story_5040_50401402_161_dialog_content = "這次被你們搶先了，但是下次我一定會狩獵到比這隻沙蟲更強的傢伙。",
  ui_story_5040_50401402_162_dialog_content = "不過，這隻大沙蟲該怎麼處理？要我們幫忙嗎？這些粉色的鱗片應該能賣不少錢吧？",
  ui_story_5040_50401402_163_dialog_content = "這畢竟是凱雅的某位朋友付出了生命的代價才換回來的，自然不能隨隨便便交給你們。",
  ui_story_5040_50401402_164_dialog_content = "至少徵求一下凱雅的意見吧？",
  ui_story_5040_50401402_165_dialog_content = "……我對怎麼處理這隻沙蟲沒有意見。",
  ui_story_5040_50401402_166_dialog_content = "只要給塔拉和亞度尼斯留夠打造戒指用的鱗片，剩下的就隨你們處理吧。",
  ui_story_5040_50401402_167_dialog_content = "小黑大概也是這麼希望的。",
  ui_story_5040_50401402_168_dialog_content = "雖然不清楚你們經歷了什麼，但希望妳能別太傷心。",
  ui_story_5040_50401402_169_dialog_content = "我們會好好利用這條沙蟲，絕對不會浪費的。",
  ui_story_5040_50401402_170_dialog_content = "那我們就先回去找人了，想處理這條沙蟲，需要不少人幫忙。",
  ui_story_5040_50401402_171_dialog_content = "下次見，PlayerName。",
  ui_story_5040_50401402_172_dialog_content = "好，下次見！",
  ui_story_5040_50401402_173_dialog_content = "還真是忙了一整天，不過在經歷苦戰後，我們終於打倒了粉色沙蟲。",
  ui_story_5040_50401402_174_dialog_content = "既然如此，亞度尼斯也算是正式通過了最後的考驗。",
  ui_story_5040_50401402_175_dialog_content = "雖然小黑的事情有些遺憾……",
  ui_story_5040_50401402_176_dialog_content = "但是這一次，我也終於弄清楚了亞度尼斯的心意。",
  ui_story_5040_50401402_177_dialog_content = "我也理解了塔拉，還獲得了面對外面世界的勇氣。",
  ui_story_5040_50401402_178_dialog_content = "既然都有所收穫，那麼就來進行最後的環節吧——我來為你們蓋章。",
  ui_story_5040_50401402_179_dialog_content = "<color=#e8d9bb>啪</color>",
  ui_story_5040_50401402_180_dialog_content = "恭喜你們。",
  ui_story_5040_50401402_181_dialog_content = "嗯，恭喜你們！",
  ui_story_5040_50401402_182_option_content = "恭喜",
  ui_story_5040_50401402_183_dialog_content = "謝謝！",
  ui_story_5040_50401402_184_dialog_content = "謝謝各位！",
  ui_story_5040_50401402_185_dialog_content = "如果沒有你們幫忙，我可能現在還縮在北境，不敢出來吧。",
  ui_story_5040_50401402_186_dialog_content = "但是現在你克服了自己的恐懼。",
  ui_story_5040_50401402_187_dialog_content = "是啊，我終於有了足夠的勇氣，能夠一直陪伴在妳身邊了。",
  ui_story_5040_50401402_188_dialog_content = "咳咳……不是我想打擾你們，但是，在你們卿卿我我之前，還有一堆事情沒有收尾呢。",
  ui_story_5040_50401402_189_dialog_content = "……！",
  ui_story_5040_50401402_190_dialog_content = "對啊！還有最重要的事沒解決呢！",
  ui_story_5040_50401402_191_dialog_content = "很好，看來小鳥兒們都已經意識到最嚴重的問題了。",
  ui_story_5040_50401402_192_dialog_content = "啊？還有什麼事啊？",
  ui_story_5040_50401402_193_dialog_content = "那當然就是——",
  ui_story_5040_50401402_194_dialog_content = "婚禮。",
  ui_story_5040_50401501_1_dialog_content = "<color=#e8d9bb>幾天後·北境</color>",
  ui_story_5040_50401501_2_dialog_content = "亞度尼斯和塔拉好慢啊……",
  ui_story_5040_50401501_3_dialog_content = "哈啾——！",
  ui_story_5040_50401501_4_dialog_content = "好冷……我們還要等多久呢？",
  ui_story_5040_50401501_5_dialog_content = "空裔小哥還真是缺乏耐心，既然是重要的儀式，就多給他們一些時間準備吧。",
  ui_story_5040_50401501_6_dialog_content = "唉，好吧。",
  ui_story_5040_50401501_7_dialog_content = "不過話說回來，這裡不是之前亞度尼斯準備的婚禮場地吧……？",
  ui_story_5040_50401501_8_dialog_content = "當然不是。",
  ui_story_5040_50401501_9_dialog_content = "這一次又不用偷偷摸摸地準備私奔，當然要光明正大地舉辦儀式了。",
  ui_story_5040_50401501_10_dialog_content = "還是說……空裔小哥更喜歡那種背德感呢？",
  ui_story_5040_50401501_11_dialog_content = "現在的比較好！能夠接受親朋好友的祝福肯定更好！",
  ui_story_5040_50401501_12_dialog_content = "PlayerName？",
  ui_story_5040_50401501_13_dialog_content = "沒想到能在這裡遇見您。",
  ui_story_5040_50401501_14_dialog_content = "諾維亞，你也是來參加婚禮的嗎？",
  ui_story_5040_50401501_15_dialog_content = "沒錯，我受到亞度尼斯的邀請，前來參加他的婚禮。",
  ui_story_5040_50401501_16_dialog_content = "亞度尼斯是我的學生，我為他帶來了來自冬宮的祝福。",
  ui_story_5040_50401501_17_dialog_content = "我想起來了，之前亞度尼斯的父母和納努塞爾確實說過這件事。",
  ui_story_5040_50401501_18_dialog_content = "亞度尼斯性格謹慎內向，過去從來沒有離開過北境。",
  ui_story_5040_50401501_19_dialog_content = "當我聽說他即將和來自紅油扳手的塔拉結婚時，著實出乎我的預料。",
  ui_story_5040_50401501_20_dialog_content = "但是，能夠看到更多北境人與外界交流，拓寬眼界，女王陛下也會高興吧。",
  ui_story_5040_50401501_21_dialog_content = "確實呢！",
  ui_story_5040_50401501_22_dialog_content = "也請替我們向伯利恆陛下致以問候。",
  ui_story_5040_50401501_23_dialog_content = "當然。",
  ui_story_5040_50401501_24_dialog_content = "我還要去把伴手禮送給亞度尼斯他們，先失陪了。",
  ui_story_5040_50401501_25_dialog_content = "沒事，有機會再見！",
  ui_story_5040_50401501_26_dialog_content = "下次再見，PlayerName。",
  ui_story_5040_50401501_27_dialog_content = "說起來，凱雅怎麼還沒來？",
  ui_story_5040_50401501_28_dialog_content = "她在飛過影鎮的時候突然說有急事，急匆匆地叫巨像降落。",
  ui_story_5040_50401501_29_dialog_content = "就連我問她去做什麼，她都沒聽見，甚至巨像還沒停穩就跳下去了。",
  ui_story_5040_50401501_30_dialog_content = "難道她不打算參加塔拉和亞度尼斯的婚禮了嗎？",
  ui_story_5040_50401501_31_dialog_content = "凱雅可是一隻信守承諾的小鳥兒。",
  ui_story_5040_50401501_32_dialog_content = "終於，趕上了！！！",
  ui_story_5040_50401501_33_dialog_content = "呼，呼，還好沒有遲到！",
  ui_story_5040_50401501_34_dialog_content = "凱雅？！妳怎麼氣喘吁吁的？",
  ui_story_5040_50401501_35_dialog_content = "喝點水，休息一下吧，婚禮馬上就開始了。",
  ui_story_5040_50401501_36_dialog_content = "謝謝妳，長老。",
  ui_story_5040_50401501_37_dialog_content = "<color=#e8d9bb>咕咚咕咚——</color>",
  ui_story_5040_50401501_38_dialog_content = "呼……能趕上真是太好了，萬一遲到，我可就要犯大錯了。",
  ui_story_5040_50401501_39_dialog_content = "這幾天妳到底跑到哪裡去了？",
  ui_story_5040_50401501_40_dialog_content = "對了，我還沒把這件事告訴PlayerName吧。",
  ui_story_5040_50401501_41_dialog_content = "塔拉和亞度尼斯委託我將那兩片沙蟲鱗片送給工匠進行打磨，做成了戒指。",
  ui_story_5040_50401501_42_dialog_content = "你看！",
  ui_story_5040_50401501_43_dialog_content = "好漂亮，完全看不出使用的材料是沙蟲的鱗片！",
  ui_story_5040_50401501_44_dialog_content = "為了打磨這對戒指，工匠師傅可是花了比預期還要長的時間。",
  ui_story_5040_50401501_45_dialog_content = "如果不是愛梅洛前輩留給我的筆記中寫了一條近路，我就要遲到了！",
  ui_story_5040_50401501_46_dialog_content = "哦？哪條近路，我怎麼不知道。",
  ui_story_5040_50401501_47_dialog_content = "當然是天上！我為了趕上去北境的馬車，連續飛了好長時間呢！",
  ui_story_5040_50401501_48_dialog_content = "我的翅膀現在還在痛呢！",
  ui_story_5040_50401501_49_dialog_content = "那妳知不知道，接到急件的信使只要向影鎮的信使公會報備，公會就會盡力幫妳準備交通工具？",
  ui_story_5040_50401501_50_dialog_content = "欸？！",
  ui_story_5040_50401501_51_dialog_content = "我怎麼不知道！而且愛梅洛前輩的筆記裡也沒有寫。",
  ui_story_5040_50401501_52_dialog_content = "這是影鎮分部最近才推出的服務，當然不會寫在老前輩的筆記裡。",
  ui_story_5040_50401501_53_dialog_content = "唉……看來我還是需要多瞭解公會不同分部的事。",
  ui_story_5040_50401501_54_dialog_content = "能及時趕上已經很棒啦，還是先好好休息，等待儀式開始吧。",
  ui_story_5040_50401501_55_dialog_content = "嗯！",
  ui_story_5040_50401501_56_dialog_content = "我不在的這幾天，你們準備得還順利嗎？",
  ui_story_5040_50401501_57_dialog_content = "尤其是那個自稱靈媒的騙子，有沒有好好找他理論，禁止他繼續騙人呢？",
  ui_story_5040_50401501_58_dialog_content = "呵呵，當然了。",
  ui_story_5040_50401501_59_dialog_content = "我們剛一回來，就去找了那個傢伙——",
  ui_story_5040_50401501_60_dialog_content = "就是他，靈媒！",
  ui_story_5040_50401501_61_dialog_content = "呀……？！這、這位先生，您有什麼事嗎？",
  ui_story_5040_50401501_62_dialog_content = "幾天前，我在你這裡購買了一瓶「萬能魔藥」，但我發現這瓶魔藥是假的。",
  ui_story_5040_50401501_63_dialog_content = "哦！我想起來了，原來是你啊。",
  ui_story_5040_50401501_64_dialog_content = "但是你可不要亂說，我的魔藥可是真材實料、確保有效的！",
  ui_story_5040_50401501_65_dialog_content = "裡面包含了粉色沙蟲的鱗片！",
  ui_story_5040_50401501_66_dialog_content = "你之前不是還自己找到我說，我的魔藥讓你的未婚妻失憶了嗎？",
  ui_story_5040_50401501_67_dialog_content = "我就是他的未婚妻，那全都是我裝的，你的魔藥根本就沒用。",
  ui_story_5040_50401501_68_dialog_content = "更何況，那裡面根本就沒有什麼粉色沙蟲的鱗片！",
  ui_story_5040_50401501_69_dialog_content = "妳、妳憑什麼這麼說，有什麼證據嗎？",
  ui_story_5040_50401501_70_dialog_content = "你先說說看，你用來做魔藥的鱗片是哪裡來的？",
  ui_story_5040_50401501_71_dialog_content = "那是、那是我不久前在拍賣會上拍到的，整個艾斯特拉絕無僅有的唯一一枚鱗片。",
  ui_story_5040_50401501_72_dialog_content = "哦？那還真是巧啊，我也是在拍賣會上，買下了一枚粉色沙蟲的鱗片。",
  ui_story_5040_50401501_73_dialog_content = "什麼？！",
  ui_story_5040_50401501_74_dialog_content = "我還留著拍賣成交時簽署的證明檔案呢，你要看嗎？",
  ui_story_5040_50401501_75_dialog_content = "那個高價拍下沙蟲鱗片的神祕買家竟然是妳……？！",
  ui_story_5040_50401501_76_dialog_content = "呵呵，還真是輕而易舉地就承認了呢。",
  ui_story_5040_50401501_77_dialog_content = "我不是很清楚北境是如何處理行騙者的，但是……",
  ui_story_5040_50401501_78_dialog_content = "我想你們一定不願意知道，在紅油沙漠大家會怎麼對付這樣的人。",
  ui_story_5040_50401501_79_dialog_content = "呃……那妳就，不要說了……",
  ui_story_5040_50401501_80_dialog_content = "對、對不起！",
  ui_story_5040_50401501_81_dialog_content = "我立刻就把錢還給你們，然、然後去自首！",
  ui_story_5040_50401501_82_dialog_content = "太好了，順利解決了。",
  ui_story_5040_50401501_83_dialog_content = "那亞度尼斯的父母呢，他們同意了嗎？",
  ui_story_5040_50401501_84_dialog_content = "在看見亞度尼斯的變化以後，他們根本就沒有再多說什麼。",
  ui_story_5040_50401501_85_dialog_content = "非常痛快地同意了亞度尼斯和塔拉的婚事！",
  ui_story_5040_50401501_86_dialog_content = "真的嗎？簡直不敢相信！",
  ui_story_5040_50401501_87_dialog_content = "明明之前他們那麼堅決地批評了亞度尼斯想要和塔拉私奔的想法。",
  ui_story_5040_50401501_88_dialog_content = "那是因為，你沒有看穿他們原本的想法。",
  ui_story_5040_50401501_89_dialog_content = "能夠輕易看穿別人這件事，也只有耶利亞長老才能做到吧……",
  ui_story_5040_50401501_90_dialog_content = "如果用感應能力的讀心的話，說不定空裔小哥也能做到？",
  ui_story_5040_50401501_91_dialog_content = "我可不會隨便使用感應能力窺探別人的想法，那是非常不禮貌的行為！",
  ui_story_5040_50401501_92_dialog_content = "想要理解別人，還是要依靠交流。",
  ui_story_5040_50401501_93_dialog_content = "亞度尼斯的父母到底是怎麼想的呢？",
  ui_story_5040_50401501_94_dialog_content = "他們的想法其實非常簡單，就像其他千千萬萬普通的父親母親一樣。",
  ui_story_5040_50401501_95_dialog_content = "他們擔心自己從未離開北境的孩子無法適應外面複雜的環境。",
  ui_story_5040_50401501_96_dialog_content = "而這份擔心，又反過來使他們更加不願意讓亞度尼斯走出北境。",
  ui_story_5040_50401501_97_dialog_content = "這不就陷入閉環了嗎！",
  ui_story_5040_50401501_98_dialog_content = "是啊，所以我「小小地」說服了他們一下，讓他們給了亞度尼斯這個機會。",
  ui_story_5040_50401501_99_dialog_content = "難道妳像威脅靈媒一樣，威脅了亞度尼斯的父母？",
  ui_story_5040_50401501_100_dialog_content = "在空裔小哥眼裡，我是那樣的人嗎？",
  ui_story_5040_50401501_101_dialog_content = "不，不是……",
  ui_story_5040_50401501_102_dialog_content = "想要說服不同的人，需要的技巧和交涉方式是不同的。",
  ui_story_5040_50401501_103_dialog_content = "亞度尼斯的父母都是通情達理的人，只是在對待自己重要的家人時，有些鑽牛角尖了。",
  ui_story_5040_50401501_104_dialog_content = "只要將他們的問題點出來，他們就立刻意識到，自己這樣做是不對的了。",
  ui_story_5040_50401501_105_dialog_content = "還真是一對令人羡慕的父母。",
  ui_story_5040_50401501_106_dialog_content = "原來妳在幕後做了這麼多事！",
  ui_story_5040_50401501_107_dialog_content = "只是隨隨便便幫了一把，畢竟，我很好奇這對跨越千里結成的戀人，最終的結局會是什麼。",
  ui_story_5040_50401501_108_dialog_content = "現在看來，似乎還不錯。",
  ui_story_5040_50401501_109_dialog_content = "快看，他們來了！",
  ui_story_5040_50401501_110_dialog_content = "是亞度尼斯和塔拉！",
  ui_story_5040_50401501_111_dialog_content = "他們兩個都換上了儀式用的禮服！",
  ui_story_5040_50401501_112_dialog_content = "塔拉好漂亮，亞度尼斯換了一身衣服以後竟然變得這麼帥氣了？！",
  ui_story_5040_50401501_113_dialog_content = "塔拉，亞度尼斯，恭喜你們。",
  ui_story_5040_50401501_114_dialog_content = "新婚快樂！",
  ui_story_5040_50401501_115_dialog_content = "新婚快樂！",
  ui_story_5040_50401501_116_dialog_content = "謝謝！",
  ui_story_5040_50401501_117_dialog_content = "謝謝各位，讓你們久等了！",
  ui_story_5040_50401501_118_dialog_content = "能一口氣請到兩位信使見證婚禮，我們一定是整個艾斯特拉最幸福的人！",
  ui_story_5040_50401501_119_dialog_content = "那麼，就由我來為你們證婚吧。",
  ui_story_5040_50401501_120_dialog_content = "塔拉，你是否願意讓這名男子成為妳的丈夫，與他締結婚約？",
