  ui_story_5040_50401501_123_dialog_content = "我願意！",
  ui_story_5040_50401501_124_dialog_content = "亞度尼斯，你是否願意讓這名女子成為你的妻子，與她締結婚約？",
  ui_story_5040_50401501_125_dialog_content = "無論疾病還是健康，無論貧窮還是富有，或任何其他理由——",
  ui_story_5040_50401501_126_dialog_content = "都愛她，照顧她，尊重她，接納她，永遠對她忠貞不渝直至生命盡頭？",
  ui_story_5040_50401501_127_dialog_content = "我願意！",
  ui_story_5040_50401501_128_dialog_content = "那麼，來自相隔萬里的不同地方、跨越無數艱難險阻終於相會的鳥兒們啊……",
