  ui_story_5040_50401501_144_dialog_content = "亞度尼斯經常在深夜，趁我們都睡著以後，一個人偷偷換上禮服，跑到鏡子前面練習儀態。",
  ui_story_5040_50401501_145_dialog_content = "他很重視這場婚禮，也希望能給塔拉妳一段最完美的記憶。",
  ui_story_5040_50401501_146_dialog_content = "不過他的動靜實在是太大了，每次都會把我們吵醒。",
