  ui_story_5040_50401501_160_dialog_content = "現在，這裡是不但是我們的家，也是塔拉的家了。",
  ui_story_5040_50401501_161_dialog_content = "雖然你們可能會經常前往艾斯特拉各地，但是別忘了，北境的家隨時歡迎你們回來。",
