  ui_story_5040_50401501_165_dialog_content = "竟然花了這麼長時間……",
  ui_story_5040_50401501_166_dialog_content = "本來以為只是從紅油沙漠送人到北境，沒想到最後幾乎繞著整個艾斯特拉跑了好幾圈！",
  ui_story_5040_50401501_167_dialog_content = "還好最後趕在薇絲和卡蓮休假結束之前回來了，納努塞爾支付的酬勞也足夠買下浮雕唱片機。",
  ui_story_5040_50401501_168_dialog_content = "平時都是她們一直在幫助我，這次總算是以我自己的力量為她們準備了一份驚喜。",
  ui_story_5040_50401501_169_dialog_content = "PlayerName，我們回來了！",
  ui_story_5040_50401501_170_dialog_content = "冠月節的事情像往年一樣多，不過還好今年仍然平靜，沒有發生什麼混亂。",
  ui_story_5040_50401501_171_dialog_content = "我們不在的這幾天，你過得怎麼樣？",
  ui_story_5040_50401501_172_dialog_content = "和平常一樣",
  ui_story_5040_50401501_173_dialog_content = "我乘著臨空者號去四處轉了轉，感受了一下各地的節日氣氛。",
  ui_story_5040_50401501_174_dialog_content = "順便接了信使公會的委託，賺了一些錢。",
  ui_story_5040_50401501_175_dialog_content = "啊，我聽說了！尤拉還問我為什麼沒和你一起行動。",
  ui_story_5040_50401501_176_dialog_content = "白夜城的巡邏士兵也看到你在給信使公會的人幫忙，辛苦你了。",
