  ui_story_5040_50401501_178_dialog_content = "很忙碌",
  ui_story_5040_50401501_179_dialog_content = "我接了一項來自信使公會的委託，賺了一些錢。",
  ui_story_5040_50401501_180_dialog_content = "原本計畫快去快回，結果花了好長時間！",
  ui_story_5040_50401501_181_dialog_content = "我聽說了，你不僅來了白夜城，還去了啟光吧？",
  ui_story_5040_50401501_182_dialog_content = "好像還去了紅油沙漠和北境？這一趟可真夠遠的！",
  ui_story_5040_50401501_183_dialog_content = "等等，為什麼我去了哪裡妳們都知道啊？！",
  ui_story_5040_50401501_184_dialog_content = "因為臨空者號很顯眼啊，不管跑到哪裡，都會成為大家的焦點！",
  ui_story_5040_50401501_185_dialog_content = "這倒是確實……",
  ui_story_5040_50401501_186_dialog_content = "總之，我用委託獲得的報酬為你們準備了禮物！",
