  ui_story_5040_50401501_188_dialog_content = "這是那台唱片機？！",
  ui_story_5040_50401501_189_dialog_content = "沒記錯的話，這個應該很貴才是。",
  ui_story_5040_50401501_190_dialog_content = "那天在影鎮購物的時候，我看到你們站在櫥窗前盯著這台唱片機看了很久。",
