  ui_story_5040_50401501_192_dialog_content = "但一想到之前都是妳們在幫助我，我幾乎沒什麼機會向妳們表示感謝的時候……",
  ui_story_5040_50401501_193_dialog_content = "我就下定決心想要買下這台唱片機送給妳們了！",
