  ui_story_5040_50401501_195_dialog_content = "PlayerName……",
  ui_story_5040_50401501_196_dialog_content = "我們當初盯著這台唱片機看，其實是有原因的……",
  ui_story_5040_50401501_197_dialog_content = "之前我就一直在和卡蓮商量，想要送給和我們一起旅行的PlayerName一件禮物。",
